// UNDO履歴を記録すべきか判定
function shouldRecordSlotsUndoHistory() {
  return !isUndoingSlots && !skipSlotsUndoHistory
}

function addToSlotsUndoHistory(type, data) {
  if (!shouldRecordSlotsUndoHistory()) {
    return
  }
  
  const entry = {
    type, // 'slot_update', 'slot_create', 'slot_delete', 'file_delete', 'file_assign', 'file_unassign', 'category_assign'
    data,
    timestamp: Date.now()
  }
  
  // 同一スロットの同一フィールドへの連続編集のみ統合
  if (type === 'slot_update' || type === 'file_assign' || type === 'slot_copy' || type === 'slot_drag_copy') {
    const lastEntry = slotsUndoHistory.value[slotsUndoHistory.value.length - 1]
    
    // slotIdまたはtargetSlotIdで比較
    const lastSlotId = lastEntry?.data?.slotId || lastEntry?.data?.targetSlotId
    const currentSlotId = data.slotId || data.targetSlotId
    
    if (lastEntry && 
        lastEntry.type === type && 
        lastSlotId === currentSlotId) {
      
      // 編集対象のフィールドが完全に同じ場合のみ統合
      const lastFields = Object.keys(lastEntry.data.updates || lastEntry.data.oldValues || {}).sort().join(',')
      const currentFields = Object.keys(data.updates || data.oldValues || {}).sort().join(',')
      
      if (lastFields === currentFields && lastFields !== '') {
        // 統合: oldValuesは最初のまま、updatesのみ更新
        if (type === 'slot_update') {
          lastEntry.data.updates = { ...lastEntry.data.updates, ...data.updates }
        } else if (type === 'file_assign') {
          lastEntry.data.fileId = data.fileId
          lastEntry.data.updates = { ...lastEntry.data.updates, ...data.updates }
        } else if (type === 'slot_copy' || type === 'slot_drag_copy') {
          lastEntry.data.updates = { ...lastEntry.data.updates, ...data.updates }
        }
        lastEntry.timestamp = Date.now()
        saveSlotsUndoToIndexedDB()
        return
      }
    }
  }
  
  // 新規追加
  slotsUndoHistory.value.push(entry)
  
  // 最大件数を超えたら最も古いものを削除
  if (slotsUndoHistory.value.length > MAX_SLOTS_UNDO_HISTORY) {
    slotsUndoHistory.value.shift()
  }
  
  // IndexedDBに保存
  saveSlotsUndoToIndexedDB()
}

