async function whileUploadOverlayPaused(fn) {
  const shouldPause =
    Boolean(uploadProgress.value?.active) ||
    (uploadQueueCount.value || 0) > 0
  if (shouldPause) uploadOverlayPaused.value = true
  try {
    return await fn()
  } finally {
    if (shouldPause) uploadOverlayPaused.value = false
  }
}

