function onMobileLeftPanelFilesAllSimilarCycle() {
  const blocked = !!(assignModeFile.value || reverseAssignModeSlotId.value)
  if (workKind.value === 'small') {
    leftPanelMode.value = leftPanelMode.value === 'all' ? 'files' : 'all'
    return
  }
  if (blocked) {
    if (leftPanelMode.value === 'similar' || leftPanelMode.value === 'comparison') {
      leftPanelMode.value = 'files'
      return
    }
    leftPanelMode.value = leftPanelMode.value === 'all' ? 'files' : 'all'
    return
  }
  if (leftPanelMode.value === 'files') {
    leftPanelMode.value = 'all'
  } else if (leftPanelMode.value === 'all') {
    leftPanelMode.value = 'comparison'
  } else if (leftPanelMode.value === 'comparison') {
    leftPanelMode.value = 'similar'
  } else if (leftPanelMode.value === 'similar') {
    leftPanelMode.value = 'files'
  } else {
    leftPanelMode.value = 'files'
  }
}

