function findBacmpServerRowByBeforeFileId(beforeFileId) {
  const fid = String(beforeFileId || '').trim()
  if (!fid) return null
  const srv = slotBeforeAfterCompareFromServer.value
  if (!Array.isArray(srv)) return null
  return (
    srv.find((r) => r?.before_file_id != null && String(r.before_file_id) === fid) ?? null
  )
}

function resolveBacmpRowIdForBeforeFileId(beforeFileId) {
  const fid = String(beforeFileId || '').trim()
  if (!fid) return null
  const memRow = (beforeAfterCompareRows.value || []).find(
    (r) => r.beforeFileId != null && String(r.beforeFileId) === fid
  )
  if (memRow?.id) return String(memRow.id)
  const srvRow = findBacmpServerRowByBeforeFileId(fid)
  return srvRow?.id != null ? String(srvRow.id) : null
}

function hydrateBacmpStateFromServerSnapshot() {
  if (beforeAfterCompareDirty.value) return
  beforeAfterCompareAfterFileByRowId.value = {}
  beforeAfterCompareBillingDroppedByRowId.value = {}
  beforeAfterCompareRoomOrderByRowId.value = {}

  const srv = slotBeforeAfterCompareFromServer.value
  if (Array.isArray(srv) && srv.length > 0) {
    beforeAfterCompareRows.value = srv.map((r) => ({
      id: String(r.id),
      beforeFileId: r.before_file_id || null
    }))
    const af = {}
    const bl = {}
    const ro = {}
    for (const r of srv) {
      const id = String(r.id)
      if (r.after_file_id) af[id] = String(r.after_file_id)
      const rawRlo = r.room_label_order
      if (rawRlo === null || rawRlo === undefined || (typeof rawRlo === 'string' && rawRlo.trim() === '')) {
        ro[id] = null
      } else {
        const rlo = Number(rawRlo)
        ro[id] = Number.isFinite(rlo) ? rlo : null
      }
      bl[id] = bacmpBillingLinesTabFromServerBillingLines(r.billing_lines)
    }
    beforeAfterCompareAfterFileByRowId.value = af
    beforeAfterCompareBillingDroppedByRowId.value = bl
    beforeAfterCompareRoomOrderByRowId.value = ro
  } else {
    beforeAfterCompareRows.value = (sekkoumaeFiles.value || []).map((f) => ({
      id: `bacmp-${f.id}`,
      beforeFileId: f.id
    }))
    const ro = {}
    for (const row of beforeAfterCompareRows.value) {
      ro[row.id] = null
    }
    beforeAfterCompareRoomOrderByRowId.value = ro
  }
}

function applyBacmpRowsFromServerSnapshot() {
  if (!slotBeforeAfterCompareActive.value) return
  hydrateBacmpStateFromServerSnapshot()
  beforeAfterCompareDirty.value = false
}

watch(slotBeforeAfterCompareMode, (on) => {
