  if (beforeAfterCompareDirty.value) return
  applyBacmpRowsFromServerSnapshot()
})

const similarityByFileId = computed(() => {
  const baseId = similarBaseFileId.value ? String(similarBaseFileId.value) : ''
  const baseVec = baseId ? similarEmbeddingByFileId.value[baseId] : null
  const out = {}
  if (!baseVec || !Array.isArray(baseVec) || baseVec.length !== 384) return out
  for (const f of sekkougoFiles.value) {
    const id = String(f.id)
    const vec = similarEmbeddingByFileId.value[id]
    if (!Array.isArray(vec) || vec.length !== 384) continue
    let dot = 0
    for (let i = 0; i < 384; i++) dot += Number(baseVec[i]) * Number(vec[i])
    out[id] = dot
  }
  return out
})

const similarSortedFiles = computed(() => {
  const baseId = similarBaseFileId.value ? String(similarBaseFileId.value) : ''
  return [...sekkougoFiles.value]
    .filter((f) => String(f.id) !== baseId)
    .sort((a, b) => {
      const av = similarityByFileId.value[String(a.id)]
      const bv = similarityByFileId.value[String(b.id)]
      if (av == null && bv == null) return 0
      if (av == null) return 1
      if (bv == null) return -1
      return bv - av
    })
})

const similarEmbeddingPendingCount = computed(() => {
  return sekkougoFiles.value.filter((f) => !similarEmbeddingByFileId.value[String(f.id)]).length
})

const similarBaseLinks = computed(() => {
  const fid = similarBaseFileId.value ? String(similarBaseFileId.value) : ''
  if (!fid) return []
  return similarLinksByFileId.value[fid] || []
})

/** 類似タブ基準画像に対応する施工前後モードの追加工事行（フォトリンクスとは別） */
const similarBaseBacmpBillingLines = computed(() => {
  const fid = similarBaseFileId.value ? String(similarBaseFileId.value) : ''
  if (!fid) return []

  const rowId = resolveBacmpRowIdForBeforeFileId(fid)
  const memMap = beforeAfterCompareBillingDroppedByRowId.value || {}
  if (rowId && Object.prototype.hasOwnProperty.call(memMap, rowId)) {
    return filterNonEmptyBacmpBillingLineTabs(memMap[rowId])
  }

  const srvRow = findBacmpServerRowByBeforeFileId(fid)
  if (srvRow) {
    return filterNonEmptyBacmpBillingLineTabs(
      bacmpBillingLinesTabFromServerBillingLines(srvRow.billing_lines)
    )
  }

  return []
})

