// スマホ: スロット→未割当割当モード（逆割り当て）
const reverseAssignModeSlotId = ref(null) // slot ID
/** 施工前後モードの逆割当: 施工前セル / 施工後セルのどちらへ入れるか */
const reverseCompareAssignZone = ref(null) // 'before' | 'after' | null

// 逆割り当てモード開始（スロットから未割当画像を選択）
async function handleStartReverseAssignMode(slotId, compareZoneMarker = null, options = {}) {
  if (!slotId) return
  if (!options.skipPanelSnapshot) {
    snapshotLeftPanelCollapsedForAssign()
  }
  const wasCollapsed = leftPanelCollapsedSnapshotForAssign.value === true
  reverseAssignModeSlotId.value = slotId
  if (compareZoneMarker === 'compare-before') {
    reverseCompareAssignZone.value = 'before'
  } else if (compareZoneMarker === 'compare-after') {
    reverseCompareAssignZone.value = 'after'
  } else {
    reverseCompareAssignZone.value = null
  }
  if (!options.keepLeftPanelMode) {
    if (leftPanelMode.value === 'similar' || leftPanelMode.value === 'comparison') {
      leftPanelMode.value = 'files'
    }
  }
  if (isMobile.value) {
    isLeftPanelCollapsed.value = false
  } else if ((isTablet.value || isDesktop.value) && wasCollapsed) {
    isLeftPanelCollapsed.value = false
    if (isTablet.value) {
      await scrollSlotGridToSlotAfterPanelExpand(slotId)
    }
  }
}

// 逆割り当てモードキャンセル
function cancelReverseAssignMode() {
  reverseAssignModeSlotId.value = null
  reverseCompareAssignZone.value = null
  restoreLeftPanelCollapsedAfterAssign()
}
// エラーメッセージ（赤いフロート表示）は一定時間で自動的に消す
const ERROR_AUTO_DISMISS_MS = 8000
let errorDismissTimer = null

watch(error, (val) => {
  if (errorDismissTimer) {
    clearTimeout(errorDismissTimer)
    errorDismissTimer = null
  }
  if (!val) return

  const captured = val
  errorDismissTimer = setTimeout(() => {
    // 途中で別のエラーに変わっていたら消さない
    if (error.value === captured) {
      error.value = null
    }
  }, ERROR_AUTO_DISMISS_MS)
})

