// Templatesタブ：静的データを全取得してIndexedDBを更新（強制完全更新）
const staticDataRefreshing = ref(false)
async function refreshAllStaticData() {
  if (staticDataRefreshing.value) return
  if (!await dialogConfirm('強制更新\nブラウザデータを全クリア後、すべてのデータを再取得\nしばらく時間がかかる場合があります。\n続けますか？', { title: '確認' })) return
  staticDataRefreshing.value = true
  try {
    // 1. IndexedDBを全クリア
    console.log('🗑️ IndexedDBをクリア中...')
    await indexedDBService.clearCache()
    
    // 2. 静的データを全取得してキャッシュ
    console.log('📥 静的データを取得中...')
    const data = await supabaseService.getAllStaticData()
    await indexedDBService.cacheAllStaticData(data)
    
    // グリッドの依頼先セレクト候補も IndexedDB から再読み込み
    await reloadContractors()

    // スケジュールラベルテンプレを IndexedDB から各画面へ反映
    await reloadScheduleLabelTemplates()
    if (scheduleLabelTemplateEditorRef.value?.reload) {
      await scheduleLabelTemplateEditorRef.value.reload()
    }
    
    // 静的データ読み込みフラグをリセット（HomePageで再読み込みされるように）
    if (homePageRef.value?.resetStaticDataFlag) {
      homePageRef.value.resetStaticDataFlag()
    }
    
    // HomePageで静的データを再読み込み
    if (homePageRef.value?.loadAllStaticData) {
      await homePageRef.value.loadAllStaticData(true) // 強制再読み込み
    }
    
    // 3. スロット右クリック用のカスタム文字列をメモリに再読み込み
    await loadCustomSnippets(true)

    // 4. テンプレートエディターをリロード
    reloadTemplateEditor()
    
    // 5. WORKS一覧を全取得
    console.log('📥 WORKS一覧を取得中...')
    if (homePageRef.value?.reloadWorks) {
      await homePageRef.value.reloadWorks()
    }
    
    await dialogAlert('強制更新完了', { title: '成功' })
  } catch (err) {
    console.error('Failed to refresh all data:', err)
    await dialogAlert('更新に失敗: ' + (err?.message || err), { title: 'エラー' })
  } finally {
    staticDataRefreshing.value = false
  }
}

