// URLパラメータをチェック
function checkUrlParams() {
  const workIdParam = route.query.work_id
  const tabParam = route.query.tab
  
  // work_idがある場合は復元
  if (workIdParam) {
    workId.value = workIdParam
    
    // tabパラメータがあればそのタブに、なければデフォルトで編集タブに
    if (tabParam) {
      if (tabParam === 'billingTemplates' && isMobile.value) {
        activeTab.value = 'works'
      } else {
        activeTab.value = tabParam
      }
      // 編集タブの場合は編集モードをON
      if (tabParam === 'edit') {
        isEditMode.value = true
      }
    } else {
      // tabパラメータがない場合はデフォルトで編集タブ
      isEditMode.value = true
      activeTab.value = 'works'
    }
  } else {
    isEditMode.value = false
    // work_idがない場合で、tabパラメータがあればそのタブに移動
    if (tabParam && ['works', 'templates', 'billingTemplates', 'grid', 'edit', 'cloudStorage', 'manual', 'schedule'].includes(tabParam)) {
      if (tabParam === 'billingTemplates' && isMobile.value) {
        activeTab.value = 'works'
      } else {
        activeTab.value = tabParam
      }
    } else if (activeTab.value === 'edit') {
      // work_idがなく、現在編集タブにいる場合はworksタブに戻る
      activeTab.value = 'works'
    }
  }
}

