async function handleReturnTabNavigation(tab, mySeq) {
  const session = returnTabSession.value
  if (!session || session.tab !== tab) return

  returnTabSessionLoading.value = true
  try {
    const targetWorkId = String(session.workId)
    const stale = Date.now() - session.leftAt > RETURN_TAB_SESSION_MAX_AGE_MS

    workId.value = targetWorkId

    if (tab === 'edit') {
      isEditMode.value = true
      indexedDBService.saveAppState('last_edit_work_id', targetWorkId)
      if (stale) {
        loading.value = true
        try {
          await loadData(true, false, true)
        } finally {
          loading.value = false
        }
      } else if (isAuthenticated.value && !dataLoaded.value) {
        loading.value = true
        try {
          await loadData(true, false, false)
        } finally {
          loading.value = false
        }
      }
      activeTab.value = 'edit'
    } else {
      indexedDBService.saveAppState('last_grid_work_id', targetWorkId)
      try {
        const cachedWork = await indexedDBService.works.get(targetWorkId)
        workKind.value = cachedWork?.kind || workKind.value || null
        repairItemInput.value = cachedWork?.display_text || ''
      } catch {
        repairItemInput.value = ''
      }
      if (stale) {
        gridLoading.value = true
        try {
          await nextTick()
          if (estimateGridEditorRef.value?.reloadFromServer) {
            await estimateGridEditorRef.value.reloadFromServer()
          }
          // 類似パネルは見積ボタン時のみ更新（タブ復帰ではスキップ）
        } finally {
          gridLoading.value = false
        }
      }
      activeTab.value = 'grid'
    }

    if (mySeq !== tabClickSeq || activeTab.value !== tab) return

    clearReturnTabSession()
    router.push({ path: '/', query: { work_id: targetWorkId, tab } })
  } finally {
    returnTabSessionLoading.value = false
  }
}

// タブをクリックした時
async function handleTabClick(tab) {
  if (returnTabSessionLoading.value) return

  // このクリックが最新か判定するためのシーケンス
  const mySeq = ++tabClickSeq
  const fromTab = activeTab.value
  const isReturnNav =
    isLookupTab(fromTab) &&
    (tab === 'edit' || tab === 'grid') &&
    returnTabSession.value?.tab === tab

  if (isReturnNav) {
    await handleReturnTabNavigation(tab, mySeq)
    return
  }

  if (isLookupTab(tab) && fromTab !== 'edit' && fromTab !== 'grid' && !isReturnNav) {
    clearReturnTabSession()
  }

  if (tab === 'edit' || tab === 'grid') {
    clearReturnTabSession()
  }

  // 進捗状況グリッドタブ（schedule）からの切り替え時：未保存の変更がある場合は警告
  if (activeTab.value === 'schedule') {
    if (scheduleGridEditorRef.value?.hasUnsavedChanges?.()) {
      if (!await dialogConfirm('未保存の変更があります。\n破棄してもよろしいですか？', { title: '確認' })) {
        return
      }
      if (scheduleGridEditorRef.value.discardUnsavedChanges) {
        await scheduleGridEditorRef.value.discardUnsavedChanges()
      }
    }
  }

  let workTabLeaveDiscarded = false

  // スロット編集タブ（edit）からの切り替え時：未保存の変更がある場合は警告
  if (hasUnsavedChanges.value && activeTab.value === 'edit') {
    if (!await dialogConfirm('未保存の変更があります。\n破棄してもよろしいですか？', { title: '確認' })) {
      return
    }

    workTabLeaveDiscarded = true

    // ダーティフラグと削除セットをクリア
    slotsDirty.value.clear()
    filesDirty.value.clear()
    categoriesDirty.value.clear()
    deletedSlots.value.clear()
    deletedFiles.value.clear()
    deletedCategories.value.clear()

    // 🆕 UNDO履歴もクリア
    slotsUndoHistory.value = []
    saveSlotsUndoToIndexedDB()
    // ローカルデータを破棄（work_id関連の情報をクリア）
    clearData()
    workId.value = null
  }

  // グリッド編集タブ（grid）からの切り替え時：未保存の変更がある場合は警告
  if (activeTab.value === 'grid') {
    if (estimateGridEditorRef.value && estimateGridEditorRef.value.hasUnsavedChanges) {
      const gridHasUnsavedChanges = estimateGridEditorRef.value.hasUnsavedChanges()
      if (gridHasUnsavedChanges) {
        if (!await dialogConfirm('未保存の変更があります。破棄してもよろしいですか？', { title: '確認' })) {
          return
        }

        workTabLeaveDiscarded = true

        // グリッド編集の未保存変更をクリア（IndexedDBも削除）
        if (estimateGridEditorRef.value.clearUnsavedChanges) {
          await estimateGridEditorRef.value.clearUnsavedChanges()
        }

        // サーバーから最新データを再取得
        if (workId.value && estimateGridEditorRef.value.reloadFromServer) {
          await estimateGridEditorRef.value.reloadFromServer()
        }
      }
    }
  }

  const sessionWorkIdOnLeave =
    !workTabLeaveDiscarded &&
    (fromTab === 'edit' || fromTab === 'grid') &&
    isLookupTab(tab) &&
    workId.value
      ? String(workId.value)
      : null

  // 編集タブ（写真タブ）の場合
  if (tab === 'edit') {
    isEditMode.value = true

    // workIdがない場合、IndexedDBから前回のwork_idを復元
    if (!workId.value && isAuthenticated.value) {
      const lastWorkId = await indexedDBService.getAppState('last_edit_work_id')
      if (lastWorkId) {
        workId.value = lastWorkId
        // URLパラメータも設定
        router.push({ path: '/', query: { work_id: lastWorkId, tab: 'edit' } })
        // IndexedDBから読み込み（forceReload=false）
        await loadData(true, false, false)
      }
    } else if (workId.value && isAuthenticated.value && !dataLoaded.value) {
      // workIdがあるがデータ未読み込みの場合
      // タブ切り替え時はIndexedDBから読み込み（forceReload=false）
      await loadData(true, false, false)
    }

    // 取得完了後に移動
    activeTab.value = tab  // ← ここに移動
  } else {
    // 他のタブの場合は即座に切り替え
    activeTab.value = tab
  }

  // worksタブの場合は編集モードをOFF
  if (tab === 'works') {
    isEditMode.value = false

    // HomePageコンポーネントは v-show で常に存在するため、
    // データは既にメモリ上に保持されている
    // タブ切り替え時に loadWorks() を呼ばず、そのまま表示する
  }

  // グリッド編集タブの場合
  if (tab === 'grid') {
    // workIdがない場合、IndexedDBから前回のwork_idを復元
    if (!workId.value && isAuthenticated.value) {
      const lastGridWorkId = await indexedDBService.getAppState('last_grid_work_id')
      if (lastGridWorkId) {
        workId.value = lastGridWorkId
        // URLパラメータも設定
        router.push({ path: '/', query: { work_id: lastGridWorkId, tab: 'grid' } })

        // IndexedDBからdisplay_textを取得してrepairItemInputに設定
        try {
          const cachedWork = await indexedDBService.works.get(lastGridWorkId)
          if (cachedWork) {
            repairItemInput.value = cachedWork.display_text || ''
          } else {
            repairItemInput.value = ''
          }
        } catch (err) {
          console.warn('⚠️ [handleTabClick] Failed to get display_text from IndexedDB:', err)
          repairItemInput.value = ''
        }
        if (sessionWorkIdOnLeave) {
          returnTabSession.value = { tab: fromTab, workId: sessionWorkIdOnLeave, leftAt: Date.now() }
        }
        return
      }
    } else if (workId.value && isAuthenticated.value) {
      // workIdがある場合もIndexedDBからdisplay_textを取得
      try {
        const cachedWork = await indexedDBService.works.get(workId.value)
        if (cachedWork) {
          repairItemInput.value = cachedWork.display_text || ''
        } else {
          repairItemInput.value = ''
        }
      } catch (err) {
        console.warn('⚠️ [handleTabClick] Failed to get display_text from IndexedDB:', err)
        repairItemInput.value = ''
      }
    }
  }

  // ローディング中などでawaitを跨いでいる間に他タブへ移動した場合、
  // 古いhandleTabClickが最後にURL/タブを上書きしないようにする
  if (mySeq !== tabClickSeq || activeTab.value !== tab) {
    return
  }

  if (sessionWorkIdOnLeave) {
    returnTabSession.value = { tab: fromTab, workId: sessionWorkIdOnLeave, leftAt: Date.now() }
  }

  // URLパラメータを更新
  const query = {}

  // work_idがあれば保持
  if (workId.value && (tab === 'edit' || tab === 'estimate' || tab === 'grid')) {
    query.work_id = workId.value
  }

  // tabパラメータを設定（worksタブの場合は省略）
  if (tab !== 'works') {
    query.tab = tab
  }

  router.push({ path: '/', query })
}

