// ルートの変更を監視
watch(() => route.query, async (newQuery, oldQuery) => {
  const newWorkId = newQuery.work_id
  const oldWorkId = oldQuery?.work_id
  const newTab = newQuery.tab
  
  if (newWorkId) {
    const previousWorkId = workId.value
    workId.value = newWorkId
    
    // tabパラメータがある場合はそのタブに切り替え
    if (newTab) {
      activeTab.value = newTab
      // if (newTab === 'estimate') {
      //   estimateWorkId.value = newWorkId
      // } else 
      if (newTab === 'edit') {
        isEditMode.value = true
        // ワークIDが変更された場合のみリロード
        if (isAuthenticated.value && (previousWorkId !== newWorkId || !dataLoaded.value)) {
          // ワークIDが変更される場合、未保存の変更があれば警告
          if (previousWorkId !== newWorkId && hasUnsavedChanges.value) {
            if (!await dialogConfirm('未保存の変更があります。\n別の案件に切り替えると変更が失われます。\n続けますか？', { title: '確認' })) {
              // キャンセルされた場合は前のwork_idに戻す
              router.push({ path: '/', query: { work_id: previousWorkId, tab: 'edit' } })
              return
            }
            // ダーティフラグをクリア
            slotsDirty.value.clear()
            filesDirty.value.clear()
            categoriesDirty.value.clear()
            deletedSlots.value.clear()
            deletedFiles.value.clear()
            deletedCategories.value.clear()
          }
          loadData()
        }
      }
    } else {
      // tabパラメータがない場合はデフォルトで編集タブ
      isEditMode.value = true
      activeTab.value = 'edit'
      if (isAuthenticated.value && (previousWorkId !== newWorkId || !dataLoaded.value)) {
        // ワークIDが変更される場合、未保存の変更があれば警告
        if (previousWorkId !== newWorkId && hasUnsavedChanges.value) {
          if (!await dialogConfirm('未保存の変更があります。別の案件に切り替えると変更が失われますが、続けますか？', { title: '確認' })) {
            // キャンセルされた場合は前のwork_idに戻す
            router.push({ path: '/', query: { work_id: previousWorkId, tab: 'edit' } })
            return
          }
          // ダーティフラグをクリア
          slotsDirty.value.clear()
          filesDirty.value.clear()
          categoriesDirty.value.clear()
          deletedSlots.value.clear()
          deletedFiles.value.clear()
          deletedCategories.value.clear()
        }
        loadData()
      }
    }
  } else if (oldWorkId) {
    // URLパラメータがクリアされた場合（worksタブに戻った場合）
    // データは保持する（クリアしない）
    isEditMode.value = false
  }
}, { deep: true })

