// ログイン成功時の処理
async function handleLoginSuccess() {
  // モーダルを即座に閉じる
  showLoginModal.value = false
  
  isAuthenticated.value = true
  
  // セッションとユーザー情報を取得
  const { data: { session } } = await supabaseClient.auth.getSession()
  if (session) {
    supabaseService.setAccessToken(session.access_token)
    
    // Edge Function経由でuser_profile_idを取得
    try {
      const profileData = await supabaseService.getUserProfile()
      
      if (profileData && profileData.user_profile_id) {
        userProfileId.value = profileData.user_profile_id
      } else {
        console.error('❌ [Login] Failed to get user profile: no user_profile_id in response')
      }
    } catch (error) {
      console.error('❌ [Login] Failed to fetch user profile:', error)
    }
  }
  
  // ログイン後、work_idパラメータがある場合のみ編集タブに移動
  if (route.query.work_id) {
    workId.value = route.query.work_id
    isEditMode.value = true
    activeTab.value = 'edit'
    loadData()
  } else {
    // work_idパラメータがない場合はworksタブに移動
    activeTab.value = 'works'
    // WORKS一覧を自動読み込み（通常ロード：キャッシュ/差分同期を優先）
    setTimeout(() => {
      if (homePageRef.value && homePageRef.value.loadWorks) {
        homePageRef.value.loadWorks()
      }
    }, 100) // DOMが更新されるまで少し待つ
  }
}

// ログアウト時: IndexedDB とメモリ上の読み込みフラグをクリア
async function clearSessionLocalCaches() {
  try {
    await indexedDBService.clearAllUserData()
  } catch (err) {
    console.warn('⚠️ [Logout] Failed to clear IndexedDB:', err)
  }
  if (homePageRef.value?.resetStaticDataFlag) {
    homePageRef.value.resetStaticDataFlag()
  }
}

// ログアウト処理
async function handleLogout() {
  clearReturnTabSession()
  // まず、UI状態を即座にクリア（onAuthStateChangeを待たない）
  isAuthenticated.value = false
  supabaseService.setAccessToken(null)
  userProfileId.value = null
  isEditMode.value = false
  workId.value = ''
  editDataWorkId.value = null
  dataLoaded.value = false
  files.value = []
  slots.value = []
  imageUrls.value = {}
  error.value = null
  
  // Dirty状態もクリア
  slotsDirty.value.clear()
  filesDirty.value.clear()
  categoriesDirty.value.clear()
  deletedSlots.value.clear()
  deletedFiles.value.clear()
  deletedCategories.value.clear()
  
  try {
    // Supabaseのローカルサインアウトを実行（セッション削除）
    const { error: signOutError } = await supabaseClient.auth.signOut({ scope: 'local' })
    
    if (signOutError) {
      console.error('❌ [Logout] signOut() returned error:', signOutError)
      throw signOutError
    }
    
    // サインアウト後のセッション確認
    const { data: { session } } = await supabaseClient.auth.getSession()
    
  } catch (err) {
    console.error('❌ [Logout] Sign out failed:', err.message, err)
    
    // エラーが発生した場合、手動でlocalStorageをクリア
    try {
      // Supabaseのセッションキーを全て削除
      Object.keys(localStorage).forEach(key => {
        if (key.startsWith('sb-') || key.includes('supabase')) {
          localStorage.removeItem(key)
        }
      })
    } catch (storageErr) {
      console.warn('⚠️  [Logout] Failed to clear localStorage:', storageErr)
    }
  } finally {
    await clearSessionLocalCaches()
    activeTab.value = 'works'
    router.push({ path: '/', query: {} })
  }
}

