// 認証状態の監視
supabaseClient.auth.onAuthStateChange(async (event, session) => {
  if (event === 'SIGNED_IN' && session) {
    // モーダルを確実に閉じる
    showLoginModal.value = false
    
    isAuthenticated.value = true
    supabaseService.setAccessToken(session.access_token)
    
    // Edge Function経由でuser_profile_idを取得
    try {
      const profileData = await supabaseService.getUserProfile()
      
      if (profileData && profileData.user_profile_id) {
        userProfileId.value = profileData.user_profile_id
      } else {
        console.error('❌ [Auth] Failed to get user profile: no user_profile_id in response')
      }
    } catch (error) {
      console.error('❌ [Auth] Failed to fetch user profile:', error)
    }
    
    checkUrlParams()
  } else if (event === 'SIGNED_OUT') {
    // モーダルを閉じる
    showLoginModal.value = false
    
    isAuthenticated.value = false
    supabaseService.setAccessToken(null)
    userProfileId.value = null
    isEditMode.value = false
    workId.value = ''
    editDataWorkId.value = null
    dataLoaded.value = false
    files.value = []
    slots.value = []
    imageUrls.value = {}
    
    // ダーティ状態もクリア
    slotsDirty.value.clear()
    filesDirty.value.clear()
    categoriesDirty.value.clear()
    deletedSlots.value.clear()
    deletedFiles.value.clear()
    deletedCategories.value.clear()
            
    // 🆕 UNDO履歴もクリア
    slotsUndoHistory.value = []
    saveSlotsUndoToIndexedDB()

    await clearSessionLocalCaches()
  } else if (event === 'TOKEN_REFRESHED' && session) {
    supabaseService.setAccessToken(session.access_token)
  }
})

// ウィンドウの可視性変更を監視（最小化/復帰時の不要なローディングを防ぐ）
let visibilityChangeHandler = null
let isWindowHidden = false

// 案件切り替え時（loadDataが画像を再読み込みする）
watch(workId, (newId, oldId) => {
  if (oldId && oldId !== newId) {
    console.log(`[Cleanup] Work changed: ${oldId} → ${newId}`)
