watch(activeTab, (newTab, oldTab) => {
  if (oldTab === 'report' && newTab !== 'report') {
    console.log(`[Cleanup] Tab changed: ${oldTab} → ${newTab}`)
    imageUrls.value = {}
  }
})

// コンポーネントアンマウント時
onBeforeUnmount(() => {
  console.log('[Cleanup] Component unmounting')
  imageUrls.value = {}
  
  // イベントリスナーをクリーンアップ
  if (visibilityChangeHandler) {
    document.removeEventListener('visibilitychange', visibilityChangeHandler)
  }
})

// ページ読み込み時にURLパラメータをチェック
onMounted(() => {
  // IndexedDBサービスをwindowに登録（他のサービスから使用できるように）
  window.indexedDBService = indexedDBService
  checkUrlParams()
  
  // ウィンドウの可視性変更を監視（最小化/復帰時の不要なローディングを防ぐ）
  visibilityChangeHandler = () => {
    if (document.hidden) {
      // ウィンドウが非表示になったとき
      isWindowHidden = true
    } else if (isWindowHidden) {
      // ウィンドウが非表示から表示に戻ったとき
      isWindowHidden = false
      // ウィンドウ復帰時に誤ってローディングが表示されるのを防ぐ
      // ユーザーが明示的にリロードボタンを押した場合のみデータを再読み込み
      // 画像URLの有効期限切れなどで自動的にローディングが表示されるのを防ぐ
      // 短時間の間、自動読み込みを防ぐ
      setTimeout(() => {
        // この時点でまだローディング中で、PDF生成中でもない場合はリセット
        // （誤ってローディングが表示されている可能性がある）
        if (loading.value && !pdfGenerating.value) {
          loading.value = false
        }
      }, 100)
    }
  }
  
  document.addEventListener('visibilitychange', visibilityChangeHandler)
  
  // ページ離脱時
  const handleBeforeUnload = () => {
    console.log('[Cleanup] Page unloading')
    imageUrls.value = {}
  }
  window.addEventListener('beforeunload', handleBeforeUnload)
})

