// loadData の競合防止（最後に開始したリクエストのみ反映）
let loadDataRequestSeq = 0

// データ読み込み
async function loadData(loadTemplates = true, skipVisibilityCheck = false, forceReload = false) {
  if (!workId.value) {
    error.value = 'Work IDを入力してください'
    return
  }

  // 未保存の変更がある場合は読み込みを防ぐ
  if (hasUnsavedChanges.value) {
    console.warn('⚠️ [LoadData] Skipping loadData: unsaved changes exist')
    console.warn('⚠️ [LoadData] Unsaved changes:', {
      slotsDirty: slotsDirty.value.size,
      filesDirty: filesDirty.value.size,
      categoriesDirty: categoriesDirty.value.size,
      deletedSlots: deletedSlots.value.size,
      deletedFiles: deletedFiles.value.size,
      deletedCategories: deletedCategories.value.size
    })
    return
  }

  // ウィンドウが非表示から復帰した直後の自動読み込みを防ぐ
  if (!skipVisibilityCheck && isWindowHidden) {
    return
  }

  loading.value = true
  error.value = null

  const requestWorkId = workId.value
  const requestSeq = ++loadDataRequestSeq
  const isStaleRequest = () => requestSeq !== loadDataRequestSeq || requestWorkId !== workId.value

  skipSlotsUndoHistory = true

  try {
    // スロットは常にサーバーから取得
    const slotsResult = await supabaseService.getWorkSlots(requestWorkId)
    if (isStaleRequest()) return
    workKind.value = slotsResult.workKind
    workDataForPDF.value = slotsResult.workData

    // フォルダとファイルも常にサーバーから取得（get_work_file_folder_list / storage_metadata ベース）
    const result = await supabaseService.getWorkFileFolderList(requestWorkId)
    if (isStaleRequest()) return
    const filesData = result.files || []
    const foldersData = result.folders || []

    // master_work_phaseとテンプレートを並列で取得
    const promises = [
      // IndexedDBからmaster_work_phasesを取得
      (async () => {
        try {
          const phases = await indexedDBService.getMasterData('master_work_phases')
          // workKindでフィルタリング
          return phases.filter(p => p.kind === workKind.value)
        } catch (err) {
          console.error('Error fetching master_work_phases from IndexedDB:', err)
          return [] // エラー時は空配列を返す
        }
      })()
    ]
    
    // テンプレート取得はloadTemplatesがtrueの場合のみ（IndexedDBから取得）
    if (loadTemplates) {
      promises.push(
        (async () => {
          try {
            // IndexedDBからreport_slot_templatesを取得
            const templates = await indexedDBService.getTemplates('report_slot_templates', userProfileId.value)
            // workKindでフィルタリング
            const filtered = templates.filter(t => t.kind === workKind.value)
            return filtered
          } catch (err) {
            console.error('Error fetching slot templates from IndexedDB:', err)
            return [] // エラー時は空配列を返す
          }
        })()
      )
    }
    
    const results = await Promise.all(promises)
    if (isStaleRequest()) return
    const workPhasesData = results[0] // これは配列
    const templatesData = loadTemplates ? results[1] : slotTemplates.value // テンプレートを取得しない場合は既存の値を保持

    files.value = filesData
    slots.value = slotsResult.slots
    workPhases.value = sortWorkPhasesBySortOrder(workPhasesData)
    if (loadTemplates) {
      slotTemplates.value = templatesData
    }

    // フォルダは get_work_file_folder_list から取得（work_categories は取得しない）
    workCategories.value = (foldersData || [])
      .filter(f => f && f.id)
      .map(f => ({
        id: f.id,
        label: f.name || f.label || '',
        parent_id: f.parent_id ?? null,
        work_id: workId.value,
        is_phase: false
      }))
    
    // 画像URLを取得
    await loadImageUrls(filesData)
    if (isStaleRequest()) return

    // PDFファイル情報を取得
    await loadPdfFile()
    if (isStaleRequest()) return

    // worksテーブルからdisplay_textを取得してrepairItemInputに設定
    // NOTE: display_textが空の場合も必ず設定する（過去の値が残らないようにする）
    repairItemInput.value = slotsResult.workData?.display_text || workDataForPDF.value?.display_text || ''

    // カスタム文字列を読み込み
    await loadCustomSnippets(forceReload)
    if (isStaleRequest()) return

    // billing_itemsをIndexedDBから読み込み
    await loadBillingItems()
    if (isStaleRequest()) return
    await refreshSimilarPanelData({ force: forceReload })
    if (isStaleRequest()) return

    await nextTick()
    if (isStaleRequest()) return
    editDataWorkId.value = requestWorkId
    dataLoaded.value = true
  } catch (err) {
    const errorMessage = err.message || err.toString() || '不明なエラー'
    
    // BigQueryクォータ超過エラー
    if (errorMessage.includes('Quota exceeded') || errorMessage.includes('quotaExceeded')) {
      error.value = 'データの読み込みに失敗しました: Supabaseのクォータ制限に達しています。しばらく待ってから再度お試しください。'
    } else {
      error.value = `データの読み込みに失敗しました: ${errorMessage}`
    }
    console.error(err)
  } finally {
    if (!isStaleRequest()) {
      loading.value = false
      skipSlotsUndoHistory = false
    }
  }
}

// 画像URLを取得
async function loadImageUrls(filesData) {
  const urlPromises = filesData.map(async (file) => {
    try {
      // スロット一覧・未割当ビューではSサムネイル(180px)を使用
      const publicUrl = supabaseService.getPublicUrlFromFileInfo(file, true, true)
      if (!publicUrl) {
        throw new Error('Failed to generate public URL')
      }
      return { fileId: file.id, url: publicUrl }
      
    } catch (err) {
      return { fileId: file.id, url: null }
    }
  })

  const results = await Promise.all(urlPromises)
  
  imageUrls.value = Object.fromEntries(
    results.filter(r => r.url).map(r => [r.fileId, r.url])
  )
  
  await nextTick()
}

// 画像URLの再取得
async function reloadImageUrl(fileId, isThumbnail = true, useSthumb = true) {
  console.log(`[ImageReload] Reloading image for file ${fileId}`)
  
  try {
    const file = files.value.find(f => f.id === fileId)
    if (!file) {
      throw new Error(`File not found: ${fileId}`)
    }
    const publicUrl = supabaseService.getPublicUrlFromFileInfo(file, isThumbnail, useSthumb)
    if (!publicUrl) {
      throw new Error(`Failed to generate public URL for ${fileId}`)
    }
    
    // 2. 画像URLを更新（ブラウザキャッシュに任せる）
    imageUrls.value[fileId] = publicUrl
    
    console.log(`[ImageReload] Successfully reloaded ${fileId}`)
    return publicUrl
    
  } catch (err) {
    console.error(`[ImageReload] Failed to reload image for ${fileId}:`, err)
    imageUrls.value[fileId] = null
    return null
  }
}

// 画像読み込みエラーハンドラ
async function handleImageLoadError(fileId) {
  console.warn(`[ImageError] Image load error for file ${fileId}`)
  
  // リトライ回数をチェック
  const retryCount = imageLoadRetries.value.get(fileId) || 0
  
  if (retryCount >= MAX_RETRY_COUNT) {
    console.error(`[ImageError] Max retry count reached for ${fileId}`)
    imageLoadRetries.value.delete(fileId)
    imageUrls.value[fileId] = null
    return
  }
  
  // リトライ回数を増やす
  imageLoadRetries.value.set(fileId, retryCount + 1)
  
  // 少し待ってから再試行（指数バックオフ）
  await new Promise(resolve => setTimeout(resolve, 1000 * (retryCount + 1)))
  
  // 再読み込み（Sサムネイル使用）
  await reloadImageUrl(fileId, true, true)
  
  // 成功したらリトライカウントをクリア
  if (imageUrls.value[fileId]) {
    imageLoadRetries.value.delete(fileId)
  }
}

// 特定の画像を手動で再読み込み
async function reloadSingleImage(fileId) {
  console.log(`[ImageReload] Manual reload requested for ${fileId}`)
  
  // リトライカウントをクリア
  imageLoadRetries.value.delete(fileId)
  
  // 再読み込み（Sサムネイル使用）
  await reloadImageUrl(fileId, true, true)
}

const FULL_IMAGE_CACHE_CONCURRENCY = 5

function isImageFileForCache(file) {
  if (!file) return false
  const mime = String(file.mime_type || '').toLowerCase()
  if (mime.startsWith('image/')) return true
  const name = String(file.original_name || file.name || file.object_key || '').toLowerCase()
  const ext = name.split('.').pop()
  return !!ext && ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'heic', 'heif'].includes(ext)
}

async function fetchUrlForCache(url) {
  const response = await fetch(url, {
    method: 'GET',
    cache: 'force-cache'
  })
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`)
  }
  await response.blob()
}

async function runTasksWithConcurrency(taskFactories, concurrency = 5) {
  let currentIndex = 0
  const workers = Array.from({ length: Math.min(concurrency, taskFactories.length) }, async () => {
    while (currentIndex < taskFactories.length) {
      const index = currentIndex
      currentIndex += 1
      await taskFactories[index]()
    }
  })
  await Promise.allSettled(workers)
}

async function handleWarmupFullImageCache() {
  if (fullImageCacheLoading.value) return
  const targets = (files.value || []).filter(isImageFileForCache)
  if (targets.length === 0) return

  fullImageCacheLoading.value = true
  try {
    const taskFactories = targets.map((file) => async () => {
      const fullUrl = supabaseService.getPublicUrlFromFileInfo(file, false, false)
      if (!fullUrl) return
      try {
        await fetchUrlForCache(fullUrl)
      } catch (err) {
        console.warn('[full-image-cache] warmup failed', { fileId: file.id, err })
      }
    })
    await runTasksWithConcurrency(taskFactories, FULL_IMAGE_CACHE_CONCURRENCY)
  } finally {
    fullImageCacheLoading.value = false
  }
}

// billing_itemsをIndexedDBから読み込み
async function loadBillingItems() {
  if (!workId.value) {
    billingItems.value = []
    billingItemsWorkId.value = ''
    return
  }
  const targetWorkId = workId.value
  billingItemsLoading.value = true
  try {
    const cached = await indexedDBService.getBillingItems(targetWorkId)
    if (targetWorkId !== workId.value) return
    if (cached && cached.items) {
      billingItems.value = cached.items
    } else {
      billingItems.value = []
    }
    billingItemsWorkId.value = targetWorkId
  } catch (err) {
    console.error('Error loading billing items from IndexedDB:', err)
    if (targetWorkId !== workId.value) return
    billingItems.value = []
    billingItemsWorkId.value = targetWorkId
  } finally {
    if (targetWorkId === workId.value) {
      billingItemsLoading.value = false
    }
  }
}

async function refreshSimilarPanelData(options = {}) {
  if (!workId.value) {
    similarLinksByFileId.value = {}
    similarEmbeddingByFileId.value = {}
    slotBeforeAfterCompareFromServer.value = null
    similarPanelCachedWorkId.value = null
    bacmpRoomLabels.value = []
    return
  }
  const targetWorkId = workId.value
  try {
    const embRes = await supabaseService.getPhotoEmbeddingsWithVectorsByWork(targetWorkId)
    if (targetWorkId !== workId.value) return
    const linksByFileId = embRes?.links_by_file_id || {}
    similarLinksByFileId.value = linksByFileId
    slotBeforeAfterCompareFromServer.value = embRes?.slot_before_after_compare?.rows ?? null
    if (!beforeAfterCompareDirty.value) {
      hydrateBacmpStateFromServerSnapshot()
    }
    try {
      const rl = await supabaseService.getRoomLabelsForWork(targetWorkId, false)
      const arr = Array.isArray(rl?.room_labels) ? rl.room_labels : []
      bacmpRoomLabels.value = [...arr].sort(
        (a, b) => (Number(a?.sort_order) || 0) - (Number(b?.sort_order) || 0)
      )
    } catch {
      bacmpRoomLabels.value = []
    }
    const embMap = {}
    for (const row of embRes?.embeddings || []) {
      if (!row?.file_id || !Array.isArray(row?.embedding)) continue
      embMap[String(row.file_id)] = row.embedding
    }
    similarEmbeddingByFileId.value = embMap
    similarPanelCachedWorkId.value = targetWorkId

  } catch (err) {
    console.warn('[similar] panel cache refresh failed', err)
  }
}

function shouldRefreshSimilarPanelData(options = {}) {
  if (options.force) return true
  if (!workId.value) return false
  return similarPanelCachedWorkId.value !== workId.value
}

async function ensureSimilarPanelData(options = {}) {
  if (!shouldRefreshSimilarPanelData(options)) return
  await refreshSimilarPanelData(options)
}

async function ensureSimilarLinksForFileId(fileId) {
  const key = String(fileId || '')
  if (!key) return
  if (similarLinksByFileId.value && Object.prototype.hasOwnProperty.call(similarLinksByFileId.value, key)) return
  try {
    const linksRes = await supabaseService.getPhotoWorkLinksByWork(workId.value)
    similarLinksByFileId.value = linksRes?.links_by_file_id || {}
  } catch (err) {
    console.warn('[similar] links fallback fetch failed', err)
  }
}

async function handleOpenSimilarTabFromSlot({ slotId, fileId }) {
  if (!fileId) return
  if (workKind.value === 'small') return

  // スマホ×施工前後: 類似タブへ。読み込み完了を待たずに施工後逆割当を開始（類似データは裏で更新）
  if (isMobile.value && slotBeforeAfterCompareActive.value && slotId) {
    similarBaseSlotId.value = slotId || null
    similarBaseFileId.value = fileId
    similarPairedBacmpRedHighlightActive.value = false
    assignModeFile.value = null
    isLeftPanelCollapsed.value = false
    leftPanelMode.value = 'similar'
    handleStartReverseAssignMode(slotId, 'compare-after', {
      keepLeftPanelMode: true,
      skipPanelSnapshot: true
    })
    await nextTick()
    await unassignedFilesRef.value?.scrollSimilarToTop?.()
    ensureSimilarPanelData({ allowOutsideGrid: true }).catch(() => {})
    ensureSimilarLinksForFileId(fileId).catch(() => {})
    return
  }

  isSimilarPanelSwitching.value = true
  try {
    await ensureSimilarPanelData({ allowOutsideGrid: true })
    await ensureSimilarLinksForFileId(fileId)
    similarBaseSlotId.value = slotId || null
    similarBaseFileId.value = fileId
    similarPairedBacmpRedHighlightActive.value =
      !slotBeforeAfterCompareActive.value &&
      similarTabPairedRedAfterFileIds.value.length > 0
    isLeftPanelCollapsed.value = false
    leftPanelMode.value = 'similar'
    await nextTick()
    await unassignedFilesRef.value?.scrollSimilarToTop?.()
  } finally {
    isSimilarPanelSwitching.value = false
  }
}

async function handleJumpToAllByCode(payload) {
  if (!payload?.categoryId || !Array.isArray(payload?.fileIds) || payload.fileIds.length === 0) return
  if (!isMobile.value) {
    isLeftPanelCollapsed.value = false
  }
  leftPanelMode.value = 'all'
  await nextTick()
  await unassignedFilesRef.value?.focusByComparisonCode?.(payload)
}

async function handleGenerateSimilarEmbeddingFromSlot({ slotId, fileId }) {
  if (!fileId || !workId.value) return
  if (workKind.value === 'small') return
  if (similarActionBusy.value) return
  similarActionBusy.value = true
  try {
    const f = files.value.find((x) => String(x.id) === String(fileId))
    if (!f) throw new Error('対象ファイルが見つかりません')
    const url = imageUrls.value[fileId] || supabaseService.getPublicUrlFromFileInfo(f, true, true)
    if (!url) throw new Error('画像URLの取得に失敗しました')
    const fetched = await fetch(url)
    if (!fetched.ok) throw new Error('画像の取得に失敗しました')
    const blob = await fetched.blob()
    const { extractPhotoEmbeddingFloat32MultiCrop, getPhotoEmbeddingModelVersion } = await import('./utils/photoEmbedding.js')
    const vec = await extractPhotoEmbeddingFloat32MultiCrop(blob)
    let housingDetailId = null
    try {
      const w = await indexedDBService.getWorkById(workId.value)
      housingDetailId = w?.housing_detail_id ?? null
    } catch {
      housingDetailId = null
    }
    await supabaseService.savePhotoEmbedding({
      file_id: fileId,
      work_id: workId.value,
      housing_detail_id: housingDetailId,
      embedding: Array.from(vec),
      model_name_version: getPhotoEmbeddingModelVersion()
    })
    similarEmbeddingByFileId.value = {
      ...similarEmbeddingByFileId.value,
      [String(fileId)]: Array.from(vec)
    }
    await handleOpenSimilarTabFromSlot({ slotId, fileId })
  } catch (err) {
    await dialogAlert(`類似値の生成に失敗しました: ${err?.message || err}`, { title: 'エラー' })
  } finally {
    similarActionBusy.value = false
  }
}

async function handleGenerateMissingSimilarEmbeddings() {
  if (!workId.value || similarEmbeddingGenerating.value) return
  const targets = sekkougoFiles.value.filter((f) => !similarEmbeddingByFileId.value[String(f.id)])
  if (targets.length === 0) {
    await dialogAlert('施工後フォルダ内に未生成の画像はありません。')
    return
  }
  similarEmbeddingGenerating.value = true
  similarEmbeddingProgress.value = { current: 0, total: targets.length }
  let success = 0
  let failed = 0
  try {
    const { extractPhotoEmbeddingFloat32MultiCrop, getPhotoEmbeddingModelVersion } = await import('./utils/photoEmbedding.js')
    const modelVersion = getPhotoEmbeddingModelVersion()
    let housingDetailId = null
    try {
      const w = await indexedDBService.getWorkById(workId.value)
      housingDetailId = w?.housing_detail_id ?? null
    } catch {
      housingDetailId = null
    }

    const CONCURRENCY = 4
    const embeddingItems = []
    for (let i = 0; i < targets.length; i += CONCURRENCY) {
      const chunk = targets.slice(i, i + CONCURRENCY)
      const settled = await Promise.allSettled(
        chunk.map(async (f) => {
          const fileId = String(f.id)
          const url = imageUrls.value[fileId] || supabaseService.getPublicUrlFromFileInfo(f, true, true)
          if (!url) throw new Error('画像URLの取得に失敗')
          const res = await fetch(url)
          if (!res.ok) throw new Error(`画像取得失敗: HTTP ${res.status}`)
          const blob = await res.blob()
          const vec = await extractPhotoEmbeddingFloat32MultiCrop(blob)
          return { file_id: fileId, embedding: Array.from(vec) }
        })
      )
      for (let j = 0; j < settled.length; j++) {
        const r = settled[j]
        const f = chunk[j]
        if (r.status === 'fulfilled') {
          embeddingItems.push(r.value)
        } else {
          failed += 1
          console.warn('[similar-bulk-generate] failed', { fileId: f?.id, error: r.reason })
        }
        similarEmbeddingProgress.value.current += 1
      }
    }

    if (embeddingItems.length > 0) {
      await supabaseService.savePhotoEmbeddingsBatch({
        work_id: workId.value,
        items: embeddingItems,
        model_name_version: modelVersion,
        housing_detail_id: housingDetailId
      })
      for (const item of embeddingItems) {
        similarEmbeddingByFileId.value[String(item.file_id)] = item.embedding
        success += 1
      }
    }
    await refreshSimilarPanelData({ force: true })
    await dialogAlert(`特徴値生成 完了\n成功: ${success} 件\n失敗: ${failed} 件`, { title: '成功' })
  } finally {
    similarEmbeddingGenerating.value = false
    similarEmbeddingProgress.value = { current: 0, total: 0 }
  }
}

