// カテゴリーを追加（同期キュー使用）
async function handleAddCategory({ label, is_phase }) {
  if (!workId.value) return
  
  try {
    isCategoryCreating.value = true
    // 一時IDを生成
    const tempId = `temp_${Date.now()}`
    
    // 同期キューに追加（CRITICAL優先度）
    await syncQueueService.addToQueue({
      workId: workId.value,
      operationType: 'add_category',
      data: { label, is_phase },
      tempId: tempId
    })
    
    // 楽観的UI更新: カテゴリーをローカルに即座に追加
    // 実際のIDはサーバーから返されるが、一旦ダミーIDで表示
    const tempCategory = {
      id: tempId,
      work_id: workId.value,
      label: label,
      is_phase: is_phase || false,
      sort_order: (workCategories.value.length + 1) * 1000,
      deleted_at: null,
      updated_at: new Date().toISOString(),
      _isTemp: true
    }
    workCategories.value = [...workCategories.value, tempCategory]
    
    // 同期キュー処理完了を待つ（バックグラウンドで処理）
    // 完了後にサーバーから最新データを再取得して一時IDを本IDに差し替え
    // 非同期で処理し、UIをブロックしない
    setTimeout(async () => {
      try {
        // 同期キューが完了するまで少し待つ（CRITICAL優先度なので通常は数秒以内に完了）
        let retries = 0
        const maxRetries = 30 // 最大30秒待つ
        
        while (retries < maxRetries) {
          await new Promise(resolve => setTimeout(resolve, 1000)) // 1秒待つ
          
          // 一時IDが本IDに解決されたかチェック
          const realId = syncQueueService.resolveTempId(tempId)
          if (realId) {
            // 本IDが取得できたら、ローカルのカテゴリーを更新
            workCategories.value = workCategories.value.map(c => 
              c.id === tempId ? { ...c, id: realId, _isTemp: false } : c
            )
            console.log(`✅ Category temp ID ${tempId} resolved to real ID ${realId}`)
            break
          }
          
          retries++
        }
        
        if (retries >= maxRetries) {
          console.warn(`⚠️ Failed to resolve temp ID ${tempId} after ${maxRetries} retries. Reloading categories from server.`)
          // タイムアウトした場合はサーバーから再取得
          await loadWorkCategories()
        }
      } catch (err) {
        console.error('Failed to resolve temp ID:', err)
        // エラーが発生した場合もサーバーから再取得
        await loadWorkCategories()
      } finally {
        isCategoryCreating.value = false
      }
    }, 0)
    
  } catch (err) {
    console.error('Failed to add category to sync queue:', err)
    error.value = `カテゴリーの追加に失敗しました: ${err.message}`
    isCategoryCreating.value = false
  }
}

// カテゴリーを更新（ダーティ管理）
function handleUpdateCategory(categoryId, updates) {
  // ローカルのカテゴリーリストを更新
  workCategories.value = workCategories.value.map(c => 
    c.id === categoryId ? { ...c, ...updates } : c
  )
  
  // ダーティ状態に追加
  const existingChanges = categoriesDirty.value.get(categoryId) || {}
  categoriesDirty.value.set(categoryId, {
    ...existingChanges,
    ...updates
  })
}

// カテゴリーを削除（ダーティ管理）
// 再帰削除に合わせる: 配下ファイルは filesDirty に入れず、表示から除外するだけ。
// バッチ処理でフォルダ削除がサーバー再帰削除されるため、二重管理を避ける。
function handleDeleteCategory(categoryId) {
  // フォルダ内の画像がスロットに割り当てられている場合はキャンセル
  const filesInCategory = files.value.filter(f => f.work_category_id === categoryId && !deletedFiles.value.has(f.id))
  const assignedFileIds = new Set(slots.value.map(s => s.file_id).filter(Boolean))
  const hasAssigned = filesInCategory.some(f => assignedFileIds.has(f.id))
  if (hasAssigned) {
    void dialogAlert('フォルダ内にスロットに割り当てられた画像があります。\n先にスロットの割り当てを解除してください。', { title: '中断' })
    return
  }

  // 削除されたカテゴリーをリストから除外
  workCategories.value = workCategories.value.filter(c => c.id !== categoryId)

  // 再帰削除に合わせる: 配下ファイルは filesDirty に入れない。
  // 表示は deletedCategories でフィルタし、バッチ後に files から除外する。
  
  // 削除セットに追加
  deletedCategories.value.add(categoryId)
  
  // ダーティ状態から削除（既に変更がある場合）
  categoriesDirty.value.delete(categoryId)
}

