// カスタム文字列を読み込み（IndexedDBから取得）
// カスタムスニペット読み込み済みフラグ
let customSnippetsLoaded = false

async function loadCustomSnippets(forceReload = false) {
  // 既に読み込み済みで、強制再読み込みでない場合はスキップ
  if (customSnippetsLoaded && !forceReload) {
    return
  }
  
  try {
    // IndexedDBからカスタムスニペットグループを取得
    const groups = await indexedDBService.getTemplates('custom_note_snippets', userProfileId.value)
    
    // sort_orderでソート
    const sortedGroups = groups.sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
    snippetGroups.value = sortedGroups
    
    // 各グループのアイテムを取得（custom_note_snippet_itemsとして保存されている）
    const itemsMap = {}
    for (const group of sortedGroups) {
      try {
        // IndexedDBからアイテムを取得
        const allItems = await indexedDBService.getTemplates('custom_note_snippet_items', userProfileId.value)
        const items = allItems.filter(item => {
          return item.snippet_id === group.id
        })
        
        // sort_orderでソート
        const sortedItems = items.sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
        itemsMap[group.id] = sortedItems
      } catch (err) {
        console.error(`Failed to load items for group ${group.id}:`, err)
        itemsMap[group.id] = []
      }
    }
    snippetItemsByGroup.value = itemsMap
    
    // 後方互換性のため、お気に入りアイテムをcustomSnippetsに格納
    const likeSnippetGroup = sortedGroups.find(g => g.label === 'like_snippet')
    if (likeSnippetGroup && itemsMap[likeSnippetGroup.id]) {
      // すでにsort_orderでソート済み
      customSnippets.value = itemsMap[likeSnippetGroup.id].map(item => ({
        ...item,
        is_favorite: true
      }))
    } else {
      customSnippets.value = []
    }
    
    // 読み込み完了フラグを設定
    customSnippetsLoaded = true
  } catch (err) {
    console.error('Failed to load custom snippets from IndexedDB:', err)
    customSnippets.value = []
    snippetGroups.value = []
    snippetItemsByGroup.value = {}
  }
}

