/** アップロードキュー完了後、コミット・特徴値生成フェーズも操作不可にする */
function setSlotUploadOverlayPhase(phase, { current = 0, total = 0 } = {}) {
  const prev = uploadProgress.value
  const t = Number(total) || Number(prev?.total) || 1
  const c = Number(current) || 0
  uploadProgress.value = {
    active: true,
    phase,
    current: phase === SLOT_UPLOAD_PHASE.COMMIT ? (c > 0 ? c : t) : c,
    total: t,
    fileName: phase === SLOT_UPLOAD_PHASE.FOLDER ? FOLDER_CREATING_OVERLAY_LABEL : ''
  }
}

function beginPostUploadCommitPhaseForSlotUpload() {
  const cur = uploadProgress.value
  const t = Math.max(Number(cur?.total) || 0, 1)
  setSlotUploadOverlayPhase(SLOT_UPLOAD_PHASE.COMMIT, { total: t, current: t })
}

// ファイルアップロード（バックグラウンド処理）
// 戻り値: Promise（キュー完了時に resolve）| 中断時 { aborted, reason }
async function handleFileUpload(filesToUpload, targetSlotId = null, uploadOptions = {}) {
  const userAfterAttempt = uploadOptions.onAfterUploadAttempt
  const userSessionComplete = uploadOptions.onUploadSessionComplete
  const opts = { ...uploadOptions }
  delete opts.onAfterUploadAttempt
  delete opts.onUploadSessionComplete
  delete opts.overwrite
  const allowPartialCommitFlag = !!opts.allowPartialCommit
  delete opts.allowPartialCommit

  if (workKind.value) opts.work_kind = workKind.value
  try {
    const w = await indexedDBService.getWorkById(workId.value)
    if (w?.housing_detail_id != null && w.housing_detail_id !== '') {
      opts.housing_detail_id = w.housing_detail_id
    }
  } catch {
    /* embedding 用。未取得時は Edge 側で works から補完 */
  }

  if (isUploadingImages.value) {
    error.value = '画像アップロード中です。完了後に再度実行してください。'
    return { aborted: true, reason: 'busy' }
  }

  if (!workId.value) {
    error.value = 'Work IDを入力してください'
    return { aborted: true, reason: 'no_work' }
  }

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return { aborted: true, reason: 'auth' }
  }

  error.value = null

  if (opts.ensure_folder) {
    const { name, parent_id: folderParentId = null } = opts.ensure_folder
    delete opts.ensure_folder
    try {
      setSlotUploadOverlayPhase(SLOT_UPLOAD_PHASE.FOLDER, {
        total: Math.max(filesToUpload.length, 1)
      })
      opts.work_category_id = await ensureUploadFolderForDrop(name, folderParentId)
    } catch (err) {
      error.value = err?.message || 'フォルダの作成に失敗しました'
      uploadProgress.value = { active: false, current: 0, total: 0, fileName: '' }
      return { aborted: true, reason: 'folder_create' }
    }
  }

  // 同名チェック
  const existingNames = new Set(getExistingFileNamesInFolder(opts.work_category_id))
  const conflicts = [...new Set([...filesToUpload].map((f) => f.name).filter((name) => existingNames.has(name)))]
  if (conflicts.length > 0) {
    uploadProgress.value = { active: false, current: 0, total: 0, fileName: '' }
    slotOverwriteConflictNames.value = conflicts
    pendingSlotUploadData.value = { files: filesToUpload, targetSlotId, uploadOptions: opts }
    showSlotOverwriteModal.value = true
    return { aborted: true, reason: 'name_conflict' }
  }

  const uploadResults = {
    success: [],
    errors: []
  }

  return await new Promise((resolve) => {
    let sessionSettled = false
    const endSession = () => {
      if (sessionSettled) return
      sessionSettled = true
      refreshDataAfterUpload(targetSlotId, uploadResults, {
        onAfterUploadAttempt: userAfterAttempt,
        allowPartialCommit: allowPartialCommitFlag
      }).finally(() => {
        uploadProgress.value = { active: false, current: 0, total: 0, fileName: '' }
        userSessionComplete?.(uploadResults)
        resolve(uploadResults)
      })
    }

    const onProgress = (progress) => {
      if (progress.active === false) {
        beginPostUploadCommitPhaseForSlotUpload()
        endSession()
      } else {
        uploadProgress.value = progress
      }
    }

    uploadQueue
      .addFiles(filesToUpload, workId.value, opts, null, onProgress, uploadResults)
      .then(() => {
        if (uploadResults.errors.length > 0 && uploadResults.success.length === 0) {
          const hasActiveProgress = uploadProgress.value && uploadProgress.value.active
          const isRejectedOnly = uploadResults.errors.every(
            (err) =>
              err.error?.includes('画像ファイル以外') ||
              err.error?.includes('リサイズできない') ||
              err.error?.includes('処理できません') ||
              err.error?.includes('アップロードできません')
          )
          if (!isRejectedOnly && !hasActiveProgress) {
            beginPostUploadCommitPhaseForSlotUpload()
            endSession()
          }
        }
      })
      .catch((err) => {
        console.error('アップロードキューエラー:', err)
        error.value = `ファイルのアップロードに失敗しました: ${err.message}`
        if (!sessionSettled) {
          sessionSettled = true
          beginPostUploadCommitPhaseForSlotUpload()
          refreshDataAfterUpload(targetSlotId, uploadResults, {
            onAfterUploadAttempt: userAfterAttempt,
            allowPartialCommit: allowPartialCommitFlag
          }).finally(() => {
            uploadProgress.value = { active: false, current: 0, total: 0, fileName: '' }
            userSessionComplete?.(uploadResults)
            resolve({ error: err })
          })
        }
      })
  })
}

function confirmSlotOverwrite() {
  const data = pendingSlotUploadData.value
  const conflictNames = new Set(slotOverwriteConflictNames.value)
  slotOverwriteConflictNames.value = []
  pendingSlotUploadData.value = null
