// アップロード完了後のデータ再読み込み
// extra.onAfterUploadAttempt(uploadResults) は成否に関わらず最後に 1 回呼ぶ（黒板 IndexedDB 同期用）
// extra.allowPartialCommit: true のとき、成功分だけ commit / 再読込（黒板カメラ「完了」用）
async function refreshDataAfterUpload(targetSlotId, uploadResults, extra = {}) {
  const allowPartialCommit = !!extra.allowPartialCommit
  try {
    const hasErrors = uploadResults.errors.length > 0
    if (hasErrors) {
      const successCount = uploadResults.success.length
      const rejectedErrors = uploadResults.errors.filter(err =>
        err.error && (
          err.error.includes('画像ファイル以外') ||
          err.error.includes('リサイズできない') ||
          err.error.includes('処理できません') ||
          err.error.includes('アップロードできません')
        )
      )
      const otherErrors = uploadResults.errors.filter(err => !rejectedErrors.includes(err))

      if (rejectedErrors.length > 0) {
        const rejectedFileNames = rejectedErrors
          .map(err => err.file ? err.file.name : '不明なファイル')
          .filter((name, index, self) => self.indexOf(name) === index)
        const rejectedMessage = rejectedErrors.length === 1
          ? `以下のファイルは画像ファイル以外、またはリサイズできない形式のためアップロードできませんでした:\n\n${rejectedFileNames.join('\n')}`
          : `以下の${rejectedFileNames.length}件のファイルは画像ファイル以外、またはリサイズできない形式のためアップロードできませんでした:\n\n${rejectedFileNames.join('\n')}`
        void dialogAlert(rejectedMessage, { title: 'エラー' })
      }

      if (otherErrors.length > 0) {
        if (successCount > 0) {
          error.value = `${successCount}件のアップロードに成功しましたが、${otherErrors.length}件のファイルでエラーが発生しました。`
        } else {
          error.value = `${otherErrors.length}件のファイルでエラーが発生しました。`
        }
      } else {
        if (successCount > 0) {
          error.value = null
        } else {
          error.value = 'アップロードできるファイルがありませんでした。'
        }
      }
      if (!allowPartialCommit) {
        console.info('[refreshDataAfterUpload] エラーありのためコミット・ベクトル化をスキップ（allowPartialCommit=false）', {
          errors: uploadResults.errors.length,
          successBuffered: uploadResults.success.length
        })
        return
      }
    }

    const successFileIds = uploadResults.success.map(r => r.id)
    if (successFileIds.length > 0) {
      setSlotUploadOverlayPhase(SLOT_UPLOAD_PHASE.COMMIT, {
        total: successFileIds.length,
        current: successFileIds.length
      })
      await supabaseService.commitUploadedFiles(workId.value, successFileIds)
    }

    if (successFileIds.length > 0) {
      const folderListResult = await supabaseService.getWorkFileFolderList(workId.value)
      const filesData = folderListResult.files || []

      try {
        let housingDetailId = null
        try {
          const w = await indexedDBService.getWorkById(workId.value)
          if (w?.housing_detail_id != null && w.housing_detail_id !== '') {
            housingDetailId = w.housing_detail_id
          }
        } catch {
          /* Edge 側で works から補完可 */
        }
        const localThumbByFileId = new Map()
        for (const row of uploadResults.success) {
          const b = row?.embed_thumbnail_blob
          if (row?.id && b instanceof Blob && b.size > 0) {
            localThumbByFileId.set(row.id, b)
          }
        }
        let runPhotoEmbed = false
        let embedTargetCount = 0
        if (workKind.value === 'large') {
          const targetFolderIdSet = new Set(
            (folderListResult.folders || [])
              .filter((fo) => ['施工前', '施工後'].includes(String(fo?.name || '').trim()) && fo?.id)
              .map((fo) => String(fo.id))
          )
          const successIdSet = new Set(successFileIds.map((id) => String(id)))
          embedTargetCount = (filesData || []).filter((f) => {
            if (!successIdSet.has(String(f?.id))) return false
            const parentId = String(f?.work_category_id ?? f?.folder_id ?? '')
            if (!targetFolderIdSet.has(parentId)) return false
            const mime = String(f?.mime_type || '').toLowerCase()
            if (mime.startsWith('image/')) return true
            const fileName = String(f?.original_name || f?.name || '').toLowerCase()
            const ext = fileName.split('.').pop()
            return ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(ext)
          }).length
          runPhotoEmbed = embedTargetCount > 0
            ? await whileUploadOverlayPaused(() =>
              dialogConfirm('この画像で類似画像検索値の生成を行いますか？', { title: '確認' })
            )
            : false
        }
        if (runPhotoEmbed) {
          setSlotUploadOverlayPhase(SLOT_UPLOAD_PHASE.EMBEDDING, {
            total: embedTargetCount,
            current: 0
          })
          await supabaseService.runBatchPhotoEmbeddingsAfterCommit(workId.value, successFileIds, {
            work_kind: workKind.value,
            housing_detail_id: housingDetailId,
            target_folder_names: ['施工前', '施工後'],
            folders: folderListResult.folders,
            files: filesData,
            localThumbByFileId,
            onProgress: ({ current, total }) => {
              setSlotUploadOverlayPhase(SLOT_UPLOAD_PHASE.EMBEDDING, { current, total })
            }
          })
        }
      } catch (embedErr) {
        console.warn('[refreshDataAfterUpload] batch photo embeddings', embedErr)
      }

      const filteredFiles = filesData.filter(f => !deletedFiles.value.has(f.id))

      const filesWithDirtyData = filteredFiles.map(file => {
        const dirtyData = filesDirty.value.get(file.id)
        if (dirtyData) {
          return {
            ...file,
            work_category_id: dirtyData.work_category_id !== undefined ? dirtyData.work_category_id : file.work_category_id,
            default_work_phase_id: dirtyData.default_work_phase_id !== undefined ? dirtyData.default_work_phase_id : file.default_work_phase_id
          }
        }
        return file
      })

      files.value = filesWithDirtyData
      await refreshSimilarPanelData({ force: true })

      const newFileIds = uploadResults.success.map(r => r.id)
      const newFiles = filesData.filter(f => newFileIds.includes(f.id))

      console.log(`[ImageCache] Processing ${newFiles.length} new images`)

      newFiles.forEach(file => {
        try {
          const publicUrl = supabaseService.getPublicUrlFromFileInfo(file, true, true)
          if (publicUrl) {
            imageUrls.value[file.id] = publicUrl
          } else {
            console.error(`Failed to generate public URL for ${file.id}`)
            imageUrls.value[file.id] = null
          }
        } catch (err) {
          console.error(`Failed to generate URL for ${file.id}:`, err)
          imageUrls.value[file.id] = null
        }
      })

      console.log(`[ImageCache] Generated URLs for ${newFiles.length} new images`)

      if (targetSlotId && uploadResults.success.length > 0) {
        const uploadedFile = uploadResults.success[0]
        handleAssignFile(targetSlotId, uploadedFile.id)
      }
    }

    if (!hasErrors) {
      error.value = null
    }
  } catch (err) {
    console.error('データ再読み込みエラー:', err)
    error.value = `データの再読み込みに失敗しました: ${err.message}`
  } finally {
    try {
      await extra.onAfterUploadAttempt?.(uploadResults)
    } catch (hookErr) {
      console.error('[refreshDataAfterUpload] onAfterUploadAttempt', hookErr)
    }
  }
}

const SAME_NAME_ERROR_STR = '同名のファイルが既に存在'

function isSameNameOnlyErrors(errors) {
  if (!Array.isArray(errors) || errors.length === 0) return false
  return errors.every((e) => String(e?.error || '').includes(SAME_NAME_ERROR_STR))
}

function cancelCategoryMoveOverwrite() {
  showCategoryMoveOverwriteModal.value = false
  categoryMoveOverwriteConflictNames.value = []
  pendingCategoryMoveOverwrite.value = null
}

async function confirmCategoryMoveOverwrite() {
  const pending = pendingCategoryMoveOverwrite.value
  showCategoryMoveOverwriteModal.value = false
  categoryMoveOverwriteConflictNames.value = []
  pendingCategoryMoveOverwrite.value = null
  if (!pending || !pending.fileId) return

  try {
    if (pending.conflictTargetIds?.length > 0) {
      await supabaseService.manageCloudStorage({
        action: 'delete_batch',
        scope: 'work',
        work_id: workId.value,
        items: pending.conflictTargetIds.map((id) => ({ id, is_folder: false }))
      })
    }
    await runMoveFileCategory(pending.fileId, pending.categoryId)
  } catch (err) {
    await dialogAlert(err?.message || 'ファイル移動に失敗しました', { title: 'エラー' })
  }
}

async function runMoveFileCategory(fileId, categoryId) {
  await supabaseService.manageCloudStorage({
    action: 'move_batch',
    target_scope: 'work',
    target_parent_id: categoryId || null,
    target_work_id: workId.value,
    items: [{ id: fileId, is_folder: false, scope: 'work', work_id: workId.value }]
  })
  // サーバ反映済みの移動なので、保存用ダーティには積まない（オプティミスティック表示のみ更新）
  const target = files.value.find((f) => String(f.id) === String(fileId))
  if (target) {
    target.work_category_id = categoryId || null
    target.default_work_phase_id = null
  }
}

async function handleMoveFileCategory(fileId, categoryId) {
  const file = files.value.find((f) => String(f.id) === String(fileId))
  if (!file || !workId.value) return
  const targetCategoryId = categoryId || null
  const currentCategoryId = file.work_category_id ?? null
  if (String(currentCategoryId ?? '') === String(targetCategoryId ?? '')) return

  const moveItem = {
    id: file.id,
    name: file.original_name || file.name || '',
    is_folder: false,
    scope: 'work',
    work_id: workId.value
  }

  try {
    const checkRes = await supabaseService.manageCloudStorage({
      action: 'check_move_batch',
      target_scope: 'work',
      target_parent_id: targetCategoryId,
      target_work_id: workId.value,
      items: [moveItem]
    })

    if (!checkRes?.all_ok && Array.isArray(checkRes?.errors) && checkRes.errors.length > 0) {
      if (!isSameNameOnlyErrors(checkRes.errors)) {
        await dialogAlert(checkRes.errors.map((x) => `${x.name || x.id || ''}: ${x.error}`).join('\n'), { title: 'エラー' })
        return
      }
      const conflictTargetIds = [...new Set(checkRes.errors.map((e) => e.conflict_target_id).filter(Boolean))]
      categoryMoveOverwriteConflictNames.value = [...new Set(checkRes.errors.map((e) => e.name || e.id).filter(Boolean))]
      pendingCategoryMoveOverwrite.value = {
        fileId,
        categoryId: targetCategoryId,
        conflictTargetIds
      }
      showCategoryMoveOverwriteModal.value = true
      return
    }

    await runMoveFileCategory(file.id, targetCategoryId)
  } catch (err) {
    await dialogAlert(err?.message || 'ファイル移動に失敗しました', { title: 'エラー' })
  }
}

// ファイルのカテゴリー/フェーズを更新（ダーティ管理）
function handleUpdateFileCategory(fileId, categoryId) {
  // ローカルでファイル情報を更新（フェーズは常にnull）
  const file = files.value.find(f => f.id === fileId)
  if (file) {
    file.work_category_id = categoryId
    file.default_work_phase_id = null
  }

  // ダーティ状態に追加
  const existingChanges = filesDirty.value.get(fileId) || {}
  filesDirty.value.set(fileId, {
    ...existingChanges,
    work_category_id: categoryId,
    default_work_phase_id: null
  })
}

/**
 * 施工前後モード保存用: filesDirty の work_category_id を manageCloudStorage で反映し、
 * 該当キーを filesDirty から外す（batch_update_slot_file_folder は parent_id 更新不可のため）。
 */
async function persistFilesDirtyCategoryMovesForBacmpSave() {
  const entries = [...filesDirty.value.entries()].filter(
    ([id, ch]) => !String(id).startsWith('temp_') && ch?.work_category_id !== undefined
  )
  for (const [fileId, changes] of entries) {
    const targetCategoryId = changes.work_category_id
    const file = files.value.find((f) => String(f.id) === String(fileId))
    if (!file || !workId.value) continue
    const currentCategoryId = file.work_category_id ?? null
    if (String(currentCategoryId ?? '') === String(targetCategoryId ?? '')) {
      const ch = filesDirty.value.get(fileId)
      if (!ch) continue
      const { work_category_id, default_work_phase_id, ...rest } = ch
      if (Object.keys(rest).length === 0) filesDirty.value.delete(fileId)
      else filesDirty.value.set(fileId, rest)
      continue
    }
    const moveItem = {
      id: file.id,
      name: file.original_name || file.name || '',
      is_folder: false,
      scope: 'work',
      work_id: workId.value
    }
    const checkRes = await supabaseService.manageCloudStorage({
      action: 'check_move_batch',
      target_scope: 'work',
      target_parent_id: targetCategoryId || null,
      target_work_id: workId.value,
      items: [moveItem]
    })
    if (!checkRes?.all_ok && Array.isArray(checkRes?.errors) && checkRes.errors.length > 0) {
      if (!isSameNameOnlyErrors(checkRes.errors)) {
        throw new Error(
          checkRes.errors.map((x) => `${x.name || x.id || ''}: ${x.error}`).join('\n')
        )
      }
      throw new Error(
        'フォルダ移動で同名ファイルがあります。未割当から移動し直すか、上書き確認後に保存してください。'
      )
    }
    await runMoveFileCategory(file.id, targetCategoryId)
    const ch = filesDirty.value.get(fileId)
    if (!ch) continue
    const { work_category_id, default_work_phase_id, ...rest } = ch
    if (Object.keys(rest).length === 0) filesDirty.value.delete(fileId)
    else filesDirty.value.set(fileId, rest)
  }
}

