function buildCompareBillingLineFromItem(item) {
  const code = String(item?.external_code || '').trim()
  const desc = String(item?.description || item?.billing_description || '').trim()
  const content = String(item?.content || '').trim()
  if (!code && !desc && !content) return null
  return [code, desc, content].join('\t')
}

