function onCompareDeleteRow(slotId) {
  const sid = String(slotId || '')
  if (!sid) return

  const rows = beforeAfterCompareRows.value || []
  const rowIndex = rows.findIndex((r) => r.id === sid)
  if (rowIndex < 0) return

  const row = rows[rowIndex]
  addToSlotsUndoHistory('bacmp_row_delete', {
    slotId: sid,
    rowIndex,
    row: { ...row },
    afterFileId: beforeAfterCompareAfterFileByRowId.value[sid] ?? null,
    billingLines: beforeAfterCompareBillingDroppedByRowId.value[sid]
      ? [...beforeAfterCompareBillingDroppedByRowId.value[sid]]
      : null,
    roomOrder: beforeAfterCompareRoomOrderByRowId.value[sid] ?? null,
    hadAfterFileKey: Object.prototype.hasOwnProperty.call(beforeAfterCompareAfterFileByRowId.value, sid),
    hadBillingKey: Object.prototype.hasOwnProperty.call(beforeAfterCompareBillingDroppedByRowId.value, sid),
    hadRoomOrderKey: Object.prototype.hasOwnProperty.call(beforeAfterCompareRoomOrderByRowId.value, sid)
  })

  beforeAfterCompareRows.value = rows.filter((r) => r.id !== sid)
  const af = { ...beforeAfterCompareAfterFileByRowId.value }
  delete af[sid]
  beforeAfterCompareAfterFileByRowId.value = af
  const bf = { ...beforeAfterCompareBillingDroppedByRowId.value }
  delete bf[sid]
  beforeAfterCompareBillingDroppedByRowId.value = bf
  const ro = { ...beforeAfterCompareRoomOrderByRowId.value }
  delete ro[sid]
  beforeAfterCompareRoomOrderByRowId.value = ro
  markBacmpDirty()
}

