// ファイルをスロットに割り当て（ローカル更新のみ）
function handleAssignFile(slotId, fileId) {
  if (slotBeforeAfterCompareActive.value) {
    const revSlot = reverseAssignModeSlotId.value
    const zone = reverseCompareAssignZone.value
    if (
      revSlot != null &&
      String(revSlot) === String(slotId) &&
      (zone === 'before' || zone === 'after')
    ) {
      reverseAssignModeSlotId.value = null
      reverseCompareAssignZone.value = null
      if (isMobile.value) {
        isLeftPanelCollapsed.value = true
        leftPanelCollapsedSnapshotForAssign.value = null
        rightPanelScrollTopSnapshotForAssign.value = null
      } else {
        restoreLeftPanelCollapsedAfterAssign()
      }
      if (zone === 'before') {
        onCompareSetBeforeFile({ slotId, fileId })
      } else {
        onCompareSetAfterFile({ slotId, fileId })
      }
      return
    }
    return
  }
  // ローカル状態を更新
  const slotIndex = slots.value.findIndex(s => s.id === slotId)
  if (slotIndex === -1) {
    console.warn(`Slot ${slotId} not found`)
    return
  }
  
  const file = files.value.find(f => f.id === fileId)
  if (!file) {
    console.warn(`File ${fileId} not found`)
    return
  }
  
  // 🆕 UNDO用に変更前の状態を保存
  const oldFileId = slots.value[slotIndex].file_id
  const oldCaption = slots.value[slotIndex].caption
  const oldNote = slots.value[slotIndex].note
  const oldWorkPhaseId = slots.value[slotIndex].work_phase_id
  
  // ファイルの情報をスロットに反映
  const updates = {
    file_id: fileId
  }
  
  // デフォルト値を適用（既存の値がない場合のみ）
  if (file.default_caption && !slots.value[slotIndex].caption) {
    updates.caption = file.default_caption
  }
  if (file.default_note && !slots.value[slotIndex].note) {
    updates.note = file.default_note
  }
  if (file.default_work_phase_id && !slots.value[slotIndex].work_phase_id) {
    updates.work_phase_id = file.default_work_phase_id
  }
  
  slots.value[slotIndex] = {
    ...slots.value[slotIndex],
    ...updates
  }

  // 割当モード中に割り当てたらモード解除
  if (assignModeFile.value?.id === fileId) {
    assignModeFile.value = null
    restoreLeftPanelCollapsedAfterAssign()
  }
  // 逆割当モード中に割り当てたらモード解除
  if (reverseAssignModeSlotId.value === slotId) {
    reverseAssignModeSlotId.value = null
    reverseCompareAssignZone.value = null
    restoreLeftPanelCollapsedAfterAssign()
  }
  // ダーティフラグを立てる
  const existingChanges = slotsDirty.value.get(slotId) || {}
  slotsDirty.value.set(slotId, {
    ...existingChanges,
    ...updates
  })

  // 🆕 UNDO履歴に追加
  addToSlotsUndoHistory('file_assign', {
    slotId,
    fileId,
    oldFileId,
    updates,
    oldValues: {
      file_id: oldFileId,
      caption: oldCaption,
      note: oldNote,
      work_phase_id: oldWorkPhaseId
    }
  })
}

