// スロットを更新（ローカル更新のみ）
function handleUpdateSlot(slotId, updates) {
  // ローカル状態を更新
  const slotIndex = slots.value.findIndex(s => s.id === slotId)
  if (slotIndex === -1) {
    console.warn(`Slot ${slotId} not found`)
    return
  }
  
  // 🆕 UNDO用に変更前の状態を保存
  const oldValues = {}
  for (const key of Object.keys(updates)) {
    oldValues[key] = slots.value[slotIndex][key]
  }
  
  slots.value[slotIndex] = {
    ...slots.value[slotIndex],
    ...updates
  }
  
  // ダーティフラグを立てる
  const existingChanges = slotsDirty.value.get(slotId) || {}
  slotsDirty.value.set(slotId, {
    ...existingChanges,
    ...updates
  })

  // 🆕 UNDO履歴に追加
  addToSlotsUndoHistory('slot_update', {
    slotId,
    updates,
    oldValues
  })
}
// スロット編集エリアのキーボードショートカット
function handleSlotsKeyDown(event) {
  // Ctrl+Z: 元に戻す
  if ((event.ctrlKey || event.metaKey) && event.key === 'z') {
    event.preventDefault()
    handleSlotsUndo()
    return
  }
}

// スロット編集のUNDO実行
function handleSlotsUndo() {
  if (slotsUndoHistory.value.length === 0) {
    console.log('⚠️ UNDO履歴がありません')
    return
  }
  
  const lastChange = slotsUndoHistory.value.pop()
  console.log('🔙 UNDO実行:', lastChange.type, lastChange.data)
  
  // UNDO実行中フラグをON
  isUndoingSlots = true
  
  try {
    switch (lastChange.type) {
      case 'slot_update':
        // スロット更新を戻す
        {
          const { slotId, oldValues } = lastChange.data
          const slotIndex = slots.value.findIndex(s => s.id === slotId)
          if (slotIndex !== -1) {
            slots.value[slotIndex] = {
              ...slots.value[slotIndex],
              ...oldValues
            }
            
            // ダーティフラグを更新
            const existingChanges = slotsDirty.value.get(slotId) || {}
            slotsDirty.value.set(slotId, {
              ...existingChanges,
              ...oldValues
            })
          }
        }
        break
      
      case 'slot_copy':
        // スロットコピーを戻す
        {
          const { targetSlotId, oldValues } = lastChange.data
          const slotIndex = slots.value.findIndex(s => s.id === targetSlotId)
          if (slotIndex !== -1) {
            slots.value[slotIndex] = {
              ...slots.value[slotIndex],
              ...oldValues
            }
            
            // ダーティフラグを更新
            const existingChanges = slotsDirty.value.get(targetSlotId) || {}
            slotsDirty.value.set(targetSlotId, {
              ...existingChanges,
              ...oldValues
            })
          }
        }
        break

      case 'file_delete':
        // ファイル削除を戻す（復元）
        {
          const { fileId, fileData, wasDirty, dirtyData } = lastChange.data
          
          // ファイルを復元
          files.value.push(fileData)
          
          // 削除セットから削除
          deletedFiles.value.delete(fileId)
          
          // ダーティ状態を復元
          if (wasDirty && dirtyData) {
            filesDirty.value.set(fileId, dirtyData)
          }
        }
        break
        
      case 'file_assign':
        // ファイル割り当てを戻す
        {
          const { slotId, oldValues } = lastChange.data
          const slotIndex = slots.value.findIndex(s => s.id === slotId)
          if (slotIndex !== -1) {
            slots.value[slotIndex] = {
              ...slots.value[slotIndex],
              ...oldValues
            }
            
            // ダーティフラグを更新
            const existingChanges = slotsDirty.value.get(slotId) || {}
            slotsDirty.value.set(slotId, {
              ...existingChanges,
              ...oldValues
            })
          }
        }
        break
        
      case 'file_unassign':
        // ファイル割り当て解除を戻す（再割り当て）
        {
          const { slotId, oldFileId } = lastChange.data
          const slotIndex = slots.value.findIndex(s => s.id === slotId)
          if (slotIndex !== -1) {
            slots.value[slotIndex] = {
              ...slots.value[slotIndex],
              file_id: oldFileId
            }
            
            // ダーティフラグを更新
            const existingChanges = slotsDirty.value.get(slotId) || {}
            slotsDirty.value.set(slotId, {
              ...existingChanges,
              file_id: oldFileId
            })
          }
        }
        break
        
      case 'slot_create':
        // スロット作成を戻す（削除）
        {
          const { slotId, slotData } = lastChange.data
          
          // スロットを削除
          slots.value = slots.value.filter(s => s.id !== slotId)
          
          // ダーティ情報を削除
          slotsDirty.value.delete(slotId)
        }
        break
        
      case 'slot_delete':
        // スロット削除を戻す（復元）
        {
          const { slotId, slotData, slotIndex, wasDirty, dirtyData } = lastChange.data
          
          // スロットを復元
          if (slotIndex !== undefined && slotIndex >= 0) {
            slots.value.splice(slotIndex, 0, slotData)
          } else {
            slots.value.push(slotData)
          }
          
          // 削除セットから削除
          deletedSlots.value.delete(slotId)
          
          // ダーティ状態を復元
          if (wasDirty && dirtyData) {
            slotsDirty.value.set(slotId, dirtyData)
          }
        }
        break
      case 'slots_reorder':
        // スロット並び替えを戻す
        {
          const { oldOrder } = lastChange.data
          
          // 元のsort_indexに戻す
          oldOrder.forEach(item => {
            const slotIndex = slots.value.findIndex(s => s.id === item.id)
            if (slotIndex !== -1) {
              slots.value[slotIndex].sort_index = item.sort_index
              
              // ダーティフラグを更新
              const existingChanges = slotsDirty.value.get(item.id) || {}
              slotsDirty.value.set(item.id, {
                ...existingChanges,
                sort_index: item.sort_index
              })
            }
          })
        }
        break
      case 'page_delete':
        // ページ削除を戻す（複数スロットを復元）
        {
          const { deletedSlots: deletedSlotsData } = lastChange.data
          
          // 逆順で復元（元の位置に戻すため）
          for (let i = deletedSlotsData.length - 1; i >= 0; i--) {
            const { slotId, slotData, slotIndex, wasDirty, dirtyData } = deletedSlotsData[i]
            
            // スロットを復元
            if (slotIndex !== undefined && slotIndex >= 0) {
              slots.value.splice(slotIndex, 0, slotData)
            } else {
              slots.value.push(slotData)
            }
            
            // 削除セットから削除
            deletedSlots.value.delete(slotId)
            
            // ダーティ状態を復元
            if (wasDirty && dirtyData) {
              slotsDirty.value.set(slotId, dirtyData)
            }
          }
        }
        break
        
      case 'slots_insert':
        // スロット挿入を戻す（複数スロット削除）
        {
          const { insertedSlots } = lastChange.data
          
          for (const item of insertedSlots) {
            const { id } = item
            
            // スロットを削除
            slots.value = slots.value.filter(s => s.id !== id)
            
            // ダーティ情報を削除
            slotsDirty.value.delete(id)
          }
        }
        break
        
      case 'slot_move':
      case 'slot_swap':
        // スロット移動・入替を戻す
        {
          const { movedSlotIds, oldOrder, additionalFieldChanges } = lastChange.data
          
          // 元のsort_indexに戻す
          oldOrder.forEach(item => {
            const slotIndex = slots.value.findIndex(s => s.id === item.id)
            if (slotIndex !== -1) {
              slots.value[slotIndex].sort_index = item.sort_index
              
              // ダーティフラグを更新
              const existingChanges = slotsDirty.value.get(item.id) || {}
              slotsDirty.value.set(item.id, {
                ...existingChanges,
                sort_index: item.sort_index
              })
            }
          })

          // sort_index以外の補助変更（break_before/caption等）を戻す
          if (Array.isArray(additionalFieldChanges)) {
            additionalFieldChanges.forEach((change) => {
              const slotIndex = slots.value.findIndex(s => s.id === change.id)
              if (slotIndex !== -1) {
                slots.value[slotIndex] = {
                  ...slots.value[slotIndex],
                  ...change.oldValues
                }
                const existingChanges = slotsDirty.value.get(change.id) || {}
                slotsDirty.value.set(change.id, {
                  ...existingChanges,
                  ...change.oldValues
                })
              }
            })
          }
          
          // sort_indexでソート
          slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
        }
        break
        
      case 'slot_drag_copy':
        // ドラッグコピーを戻す
        {
          const { targetSlotId, oldValues } = lastChange.data
          const slotIndex = slots.value.findIndex(s => s.id === targetSlotId)
          if (slotIndex !== -1) {
            slots.value[slotIndex] = {
              ...slots.value[slotIndex],
              ...oldValues
            }
            
            // ダーティフラグを更新
            const existingChanges = slotsDirty.value.get(targetSlotId) || {}
            slotsDirty.value.set(targetSlotId, {
              ...existingChanges,
              ...oldValues
            })
          }
        }
        break
      case 'slot_drag_copy_range':
        // ドラッグ範囲コピーを戻す
        {
          const { copyItems } = lastChange.data
          if (Array.isArray(copyItems)) {
            copyItems.forEach((item) => {
              const slotIndex = slots.value.findIndex(s => s.id === item.targetSlotId)
              if (slotIndex !== -1) {
                slots.value[slotIndex] = {
                  ...slots.value[slotIndex],
                  ...item.oldValues
                }
                const existingChanges = slotsDirty.value.get(item.targetSlotId) || {}
                slotsDirty.value.set(item.targetSlotId, {
                  ...existingChanges,
                  ...item.oldValues
                })
              }
            })
          }
        }
        break
      case 'slot_row_insert':
        // 行挿入を戻す（追加2スロット削除 + 既存sort_index復元）
        {
          const { insertedSlotIds, oldOrder, additionalFieldChanges } = lastChange.data

          if (Array.isArray(insertedSlotIds)) {
            insertedSlotIds.forEach((id) => {
              slots.value = slots.value.filter(s => s.id !== id)
              slotsDirty.value.delete(id)
            })
          }

          if (Array.isArray(additionalFieldChanges)) {
            additionalFieldChanges.forEach((change) => {
              const slotIndex = slots.value.findIndex(s => s.id === change.id)
              if (slotIndex !== -1) {
                slots.value[slotIndex] = {
                  ...slots.value[slotIndex],
                  ...change.oldValues
                }
                const existingChanges = slotsDirty.value.get(change.id) || {}
                slotsDirty.value.set(change.id, {
                  ...existingChanges,
                  ...change.oldValues
                })
              }
            })
          }

          if (Array.isArray(oldOrder)) {
            oldOrder.forEach((item) => {
              const slotIndex = slots.value.findIndex(s => s.id === item.id)
              if (slotIndex !== -1) {
                slots.value[slotIndex].sort_index = item.sort_index
                const existingChanges = slotsDirty.value.get(item.id) || {}
                slotsDirty.value.set(item.id, {
                  ...existingChanges,
                  sort_index: item.sort_index
                })
              }
            })
          }

          slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
        }
        break
      case 'slot_column_delete':
        // 列削除を戻す（削除した左右ペアを復元）
        {
          const { deletedSlotsData, oldOrder } = lastChange.data
          if (Array.isArray(deletedSlotsData)) {
            for (let i = deletedSlotsData.length - 1; i >= 0; i--) {
              const { slotId, slotData, slotIndex, wasDirty, dirtyData } = deletedSlotsData[i]
              if (!slotData) continue
              const safeIndex = Number.isInteger(slotIndex) ? Math.max(0, Math.min(slotIndex, slots.value.length)) : slots.value.length
              slots.value.splice(safeIndex, 0, slotData)
              if (deletedSlots.value.has(slotId)) {
                deletedSlots.value.delete(slotId)
              }
              if (wasDirty && dirtyData) {
                slotsDirty.value.set(slotId, dirtyData)
              } else {
                slotsDirty.value.delete(slotId)
              }
            }
          }
          if (Array.isArray(oldOrder)) {
            oldOrder.forEach((item) => {
              const slotIndex = slots.value.findIndex(s => s.id === item.id)
              if (slotIndex !== -1) {
                slots.value[slotIndex].sort_index = item.sort_index
                const existingChanges = slotsDirty.value.get(item.id) || {}
                slotsDirty.value.set(item.id, {
                  ...existingChanges,
                  sort_index: item.sort_index
                })
              }
            })
          }
          slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
        }
        break

      case 'bacmp_billing_append': {
        const { slotId, previousLines } = lastChange.data
        const sid = String(slotId || '')
        if (!sid) break
        const next = { ...beforeAfterCompareBillingDroppedByRowId.value }
        if (previousLines?.length) {
          next[sid] = [...previousLines]
        } else {
          delete next[sid]
        }
        beforeAfterCompareBillingDroppedByRowId.value = next
        markBacmpDirty()
        break
      }

      case 'bacmp_row_delete': {
        const {
          slotId,
          rowIndex,
          row,
          afterFileId,
          billingLines,
          roomOrder,
          hadAfterFileKey,
          hadBillingKey,
          hadRoomOrderKey
        } = lastChange.data
        const sid = String(slotId || '')
        if (!sid || !row) break

        const rows = [...beforeAfterCompareRows.value]
        const insertAt =
          Number.isInteger(rowIndex) && rowIndex >= 0 && rowIndex <= rows.length
            ? rowIndex
            : rows.length
        rows.splice(insertAt, 0, { ...row })
        beforeAfterCompareRows.value = rows

        if (hadAfterFileKey) {
          beforeAfterCompareAfterFileByRowId.value = {
            ...beforeAfterCompareAfterFileByRowId.value,
            [sid]: afterFileId ?? null
          }
        }

        if (hadBillingKey) {
          beforeAfterCompareBillingDroppedByRowId.value = {
            ...beforeAfterCompareBillingDroppedByRowId.value,
            [sid]: billingLines ? [...billingLines] : []
          }
        }

        if (hadRoomOrderKey) {
          beforeAfterCompareRoomOrderByRowId.value = {
            ...beforeAfterCompareRoomOrderByRowId.value,
            [sid]: roomOrder ?? null
          }
        }

        markBacmpDirty()
        break
      }
    }
  } finally {
    // UNDO実行中フラグをOFF
    isUndoingSlots = false
  }
  
  // IndexedDBに保存
  saveSlotsUndoToIndexedDB()
}

