// スロット編集の変更を保存（バッチ送信）
async function handleSaveSlotChanges() {
  if (!hasEditSaveableWork.value) {
    return
  }

  if (!workId.value) {
    error.value = 'Work IDを入力してください'
    return
  }

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return
  }

  error.value = null

  if (slotBeforeAfterCompareMode.value) {
    slotSaving.value = true
    try {
      await persistFilesDirtyCategoryMovesForBacmpSave()
      const sidecarOps = collectBacmpSidecarBatchOperations()
      if (sidecarOps.length > 0) {
        const response = await supabaseService.batchUpdateSlots(workId.value, sidecarOps)
        if (response?.failed > 0 && response?.errors?.length) {
          const msg = response.errors.map((e) => e.error || '').filter(Boolean).join('\n')
          error.value = `保存しましたが、ファイル・フォルダの更新・削除の一部に失敗しました:\n${msg}`
        }
        applyBacmpSidecarBatchClear(sidecarOps)
        for (const op of sidecarOps) {
          if (op.type !== 'delete' || !op.id) continue
          if (workCategories.value.some((c) => String(c.id) === String(op.id))) {
            workCategories.value = workCategories.value.filter((c) => String(c.id) !== String(op.id))
            files.value = files.value.filter((f) => String(f.work_category_id ?? '') !== String(op.id))
          }
        }
      }
      if (beforeAfterCompareDirty.value) {
        const rowsPayload = (beforeAfterCompareRows.value || []).map((row, idx) => {
          const sid = String(row.id)
          const afterId = beforeAfterCompareAfterFileByRowId.value[sid]
          const rlo = beforeAfterCompareRoomOrderByRowId.value[sid]
          const lines = beforeAfterCompareBillingDroppedByRowId.value[sid] || []
          return {
            before_file_id: row.beforeFileId || null,
            after_file_id: afterId || null,
            sort_order: idx,
            room_label_order:
              rlo === null || rlo === undefined
                ? null
                : Number.isFinite(Number(rlo))
                  ? Number(rlo)
                  : null,
            billing_lines: lines.map((line, j) => {
              const parts = String(line).split('\t')
              return {
                external_code: (parts[0] || '').trim(),
                description: (parts[1] || '').trim(),
                content: (parts[2] || '').trim(),
                sort_order: j
              }
            })
          }
        })
        await supabaseService.saveSlotBeforeAfterCompareBatch(workId.value, rowsPayload)
        await refreshSimilarPanelData()
        applyBacmpRowsFromServerSnapshot()
        beforeAfterCompareDirty.value = false
      }
    } catch (cmpErr) {
      error.value = `施工前後モードの保存に失敗しました: ${cmpErr?.message || cmpErr}`
      console.error('save slot before/after compare / sidecar', cmpErr)
    } finally {
      slotSaving.value = false
    }
    return
  }

  slotSaving.value = true
  try {
    // ダーティな変更を収集
    const operations = []

    // スロットの変更
    for (const [slotId, changes] of slotsDirty.value.entries()) {
      // temp_idを本IDに解決
      const resolvedChanges = { ...changes }

      // file_idがtemp_idの場合は解決
      if (resolvedChanges.file_id && typeof resolvedChanges.file_id === 'string' && resolvedChanges.file_id.startsWith('temp_')) {
        const realId = syncQueueService.resolveTempId(resolvedChanges.file_id)
        if (realId) {
          resolvedChanges.file_id = realId
        } else {
          // まだアップロード中の場合はスキップ
          console.warn(`⏳ File ${resolvedChanges.file_id} is still uploading, skipping...`)
          continue
        }
      }

      // 新規スロット（_isNewフラグ）の場合はcreate、それ以外はupdate
      if (resolvedChanges._isNew) {
        // _isNewフラグを削除
        const { _isNew, ...dataWithoutFlag } = resolvedChanges

        operations.push({
          type: 'create',
          table: 'report_slots',
          temp_id: slotId, // 仮IDを記録（サーバーで本IDが生成される）
          data: dataWithoutFlag
        })
      } else {
        operations.push({
          type: 'update',
          table: 'report_slots',
          id: slotId,
          data: resolvedChanges
        })
      }
    }

    // ファイルのフォルダ移動は禁止（batch_update では parent_id 更新を行わない）

    // ファイルのメタデータ変更（rotation 等）
    for (const [fileId, changes] of filesDirty.value.entries()) {
      if (fileId.startsWith('temp_')) continue
      const data = {}
      if (changes.rotation !== undefined) data.rotation = String(changes.rotation)
      if (Object.keys(data).length === 0) continue
      operations.push({
        type: 'update',
        table: 'storage_metadata',
        id: fileId,
        data
      })
    }

    // カテゴリー（フォルダ）の変更（folder_metadata: リネーム）
    for (const [categoryId, changes] of categoriesDirty.value.entries()) {
      if (categoryId.startsWith('temp_')) continue
      if (changes.label === undefined) continue
      operations.push({
        type: 'update',
        table: 'storage_metadata',
        id: categoryId,
        data: { name: changes.label }
      })
    }

    // スロットの削除
    for (const slotId of deletedSlots.value) {
      // 仮IDの場合は、まだサーバーに存在しないのでスキップ
      if (slotId.startsWith('temp_slot_')) {
        continue
      }

      operations.push({
        type: 'delete',
        table: 'report_slots',
        id: slotId
      })
    }

    // ファイルの論理削除（storage_metadata）
    for (const fileId of deletedFiles.value) {
      if (fileId.startsWith('temp_')) continue
      operations.push({
        type: 'delete',
        table: 'storage_metadata',
        id: fileId
      })
    }

    // フォルダの削除（storage_metadata）
    for (const categoryId of deletedCategories.value) {
      if (categoryId.startsWith('temp_')) continue
      operations.push({
        type: 'delete',
        table: 'storage_metadata',
        id: categoryId
      })
    }

    if (operations.length === 0) {
      return
    }

    // バッチ送信
    const response = await supabaseService.batchUpdateSlots(workId.value, operations)

    // 一部失敗時（フォルダ移動の同名 conflict 等）のエラー表示
    if (response?.failed > 0 && response?.errors?.length) {
      const msg = response.errors.map((e) => e.error || '').filter(Boolean).join('\n')
      error.value = `保存しましたが、次の処理に失敗しました:\n${msg}`
    }

    // 新規作成されたスロットの仮IDと本IDのマッピングを処理
    if (response && response.updated && Array.isArray(response.updated)) {
      for (const result of response.updated) {
        if (result.type === 'create' && result.temp_id && result.id) {
          // ローカルのスロット配列内の仮IDを本IDに置き換え
          const slotIndex = slots.value.findIndex(s => s.id === result.temp_id)
          if (slotIndex !== -1) {
            slots.value[slotIndex].id = result.id
          }

          // ダーティマップからも削除（既にクリアされるが念のため）
          slotsDirty.value.delete(result.temp_id)
        }
      }
    }

    // 再帰削除でサーバー側削除されたフォルダ配下のファイルをローカルから除外
    const deletedCatIds = new Set(deletedCategories.value)
    if (deletedCatIds.size > 0) {
      files.value = files.value.filter(f => !deletedCatIds.has(f.work_category_id))
    }

    // ダーティフラグと削除セットをクリア
    slotsDirty.value.clear()
    filesDirty.value.clear()
    categoriesDirty.value.clear()
    deletedSlots.value.clear()
    deletedFiles.value.clear()
    deletedCategories.value.clear()

    // 🆕 UNDO履歴もクリア
    slotsUndoHistory.value = []
    saveSlotsUndoToIndexedDB()
  } catch (err) {
    error.value = `保存に失敗しました: ${err.message}`
    console.error('Save error:', err)
  } finally {
    slotSaving.value = false
  }
}

// スロットを挿入（ローカルのみ、仮ID使用）
async function handleInsertSlot({ sourceSlotId, targetSlotId, position }) {
  if (!workId.value) {
    error.value = 'Work IDを入力してください'
    return
  }

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return
  }

  error.value = null

  try {
    // 現在のスロットをソート
    const allSlots = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
    
    // sourceSlotIdが指定されている場合、コピー元のスロットを取得
    let sourceSlot = null
    if (sourceSlotId) {
      sourceSlot = allSlots.find(s => s.id === sourceSlotId)
    }
    
    let insertCount = 1

    // positionに応じて挿入数を決定
    if (position === 'plus') {
      insertCount = 1
    } else if (position === 'plus3') {
      insertCount = 3
    } else if (position === 'plus6') {
      insertCount = 6
    }

    // 挿入するスロットの配列
    const newSlots = []
    
    // ソートインデックスを計算
    let currentSlot = null
    let nextSlot = null
    
    if (targetSlotId && allSlots.length > 0) {
      currentSlot = allSlots.find(s => s.id === targetSlotId)
      if (currentSlot) {
        const currentIndex = allSlots.findIndex(s => s.id === targetSlotId)
        nextSlot = allSlots[currentIndex + 1] || null
      }
    }

    // スロットがない場合
    if (allSlots.length === 0) {
      for (let i = 0; i < insertCount; i++) {
        const sortIndex = 1000000 * (i + 1)
        const tempId = `temp_slot_${Date.now()}_${i}`
        
        newSlots.push({
          id: tempId,
          work_id: workId.value,
          sort_index: sortIndex,
          caption: null,
          note: sourceSlot ? sourceSlot.note : '',
          work_phase_id: sourceSlot ? sourceSlot.work_phase_id : '', // 常にnull（カテゴリーはコピーしない）
          file_id: null, // 常にnull（ファイルIDはコピーしない）
          break_before: null,
          pageNumber: i + 1,
          slotNumberInPage: 1,
          displayIndex: i
        })
      }
    } else {
      if (!currentSlot) {
        // targetSlotIdが見つからない場合、最後のスロットを使用
        currentSlot = allSlots[allSlots.length - 1]
        nextSlot = null
      }

      const A = currentSlot.sort_index
      const B = nextSlot ? nextSlot.sort_index : null
      
      if (B === null) {
        // 次のスロットBが無い場合：A + 1000000刻み
        for (let i = 1; i <= insertCount; i++) {
          const sortIndex = A + 1000000 * i
          const tempId = `temp_slot_${Date.now()}_${i}`
          
          newSlots.push({
            id: tempId,
            work_id: workId.value,
            sort_index: sortIndex,
            caption: null,
            note: sourceSlot ? sourceSlot.note : '',
            work_phase_id: sourceSlot ? sourceSlot.work_phase_id : '', // 常にnull（カテゴリーはコピーしない）
            file_id: null, // 常にnull（ファイルIDはコピーしない）
            break_before: null,
            pageNumber: 1,
            slotNumberInPage: 1,
            displayIndex: allSlots.length + i - 1
          })
        }
      } else {
        // 次のスロットBがある場合：間隔を分割
        const X = Math.floor(B - A)
        const Y = insertCount
        const interval = Math.floor(X / (Y + 1))
        
        for (let i = 1; i <= Y; i++) {
          const sortIndex = A + interval * i
          const tempId = `temp_slot_${Date.now()}_${i}`
          
          newSlots.push({
            id: tempId,
            work_id: workId.value,
            sort_index: sortIndex,
            caption: null,
            note: sourceSlot ? sourceSlot.note : '',
            work_phase_id: sourceSlot ? sourceSlot.work_phase_id : '', // 常にnull（カテゴリーはコピーしない）
            file_id: null, // 常にnull（ファイルIDはコピーしない）
            break_before: null,
            pageNumber: 1,
            slotNumberInPage: 1,
            displayIndex: 0
          })
        }
      }
    }

    // 新しいスロットをslots配列に追加
    const updatedSlots = [...allSlots, ...newSlots].sort((a, b) => a.sort_index - b.sort_index)
    slots.value = updatedSlots

    // 各新しいスロットをダーティ管理に追加（作成として）
    for (const slot of newSlots) {
      // 新規スロットは全フィールドをダーティとして記録
      slotsDirty.value.set(slot.id, {
        id: slot.id,
        work_id: slot.work_id,
        sort_index: slot.sort_index,
        caption: slot.caption,
        note: slot.note,
        work_phase_id: slot.work_phase_id,
        file_id: slot.file_id,
        break_before: slot.break_before,
        _isNew: true // 新規作成フラグ
      })
    }

    // リバランスチェック
    const insertedSlotIds = newSlots.map(s => s.id)
    checkAndRebalanceIfNeeded(insertedSlotIds)
    
    // 🆕 UNDO履歴に追加（バッチとして）
    addToSlotsUndoHistory('slots_insert', {
      insertedSlots: newSlots.map(slot => ({
        id: slot.id,
        data: { ...slot }
      }))
    })
  } catch (err) {
    error.value = `スロットの挿入に失敗しました: ${err.message}`
    console.error(err)
  }
}

// スロットをコピー（矢印ボタン用：スロットの挿入は行わず、既存のスロットに直接コピー）
async function handleCopySlot({ sourceSlotId, targetSlotId, work_phase_id, note, caption }) {
  if (!workId.value) {
    error.value = 'Work IDを入力してください'
    return
  }

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return
  }

  if (!targetSlotId) {
    error.value = 'コピー先のスロットが指定されていません'
    return
  }

  error.value = null

  // ローカル更新のみ: まずローカルのslots配列を直接更新（即座にUI反映）
  const targetSlot = slots.value.find(s => s.id === targetSlotId)
  if (!targetSlot) {
    error.value = 'コピー先のスロットが見つかりません'
    return
  }

  // 🆕 UNDO用に変更前の状態を保存
  const oldValues = {}
  
  // ローカル状態を即座に更新
  const updates = {}
  if (work_phase_id !== undefined) {
    oldValues.work_phase_id = targetSlot.work_phase_id
    targetSlot.work_phase_id = work_phase_id
    updates.work_phase_id = work_phase_id
  }
  if (note !== undefined) {
    oldValues.note = targetSlot.note
    targetSlot.note = note
    updates.note = note
  }
  if (caption !== undefined) {
    oldValues.caption = targetSlot.caption
    targetSlot.caption = caption
    updates.caption = caption
  }

  // ダーティ管理に追加
  if (Object.keys(updates).length > 0) {
    markSlotDirty(targetSlotId, updates)
    
    // 🆕 UNDO履歴に追加
    addToSlotsUndoHistory('slot_copy', {
      targetSlotId,
      updates,
      oldValues
    })
  }
}

// スロットを削除（ダーティ管理）// スロットを削除（ダーティ管理）
function handleDeleteSlot(slotId) {
  if (slotBeforeAfterCompareActive.value) return
  // 確認はSlotItem.vueで既に行われているため、ここでは確認しない
  
  // 🆕 UNDO用に削除前の状態を保存
  const slotIndex = slots.value.findIndex(s => s.id === slotId)
  const deletedSlot = slots.value.find(s => s.id === slotId)
  if (!deletedSlot) {
    console.warn(`Slot ${slotId} not found`)
    return
  }
  
  const wasDirty = slotsDirty.value.has(slotId)
  const dirtyData = slotsDirty.value.get(slotId)
  
  // ローカルでスロットを削除（UIから非表示）
  slots.value = slots.value.filter(s => s.id !== slotId)
  
  // 削除セットに追加
  deletedSlots.value.add(slotId)
  
  // ダーティ状態から削除（既に変更がある場合）
  slotsDirty.value.delete(slotId)
  
  // 🆕 UNDO履歴に追加
  addToSlotsUndoHistory('slot_delete', {
    slotId,
    slotData: { ...deletedSlot },
    slotIndex,
    wasDirty,
    dirtyData
  })
}

// ページを削除（ローカルのみ）
async function handleDeletePage(groupIndex) {
  // displaySlotsはcomputedなので.valueは不要
  const groups = groupSlotsForGrid(displaySlots.value)
  if (!groups || !Array.isArray(groups) || groupIndex < 0 || groupIndex >= groups.length) {
    console.error('Invalid group index:', groupIndex, 'Groups:', groups)
    return
  }

  const firstGroup = groups[groupIndex]
  if (!firstGroup) {
    return
  }

  // ページ内のすべてのスロットを取得（break_beforeから次のbreak_beforeの直前まで）
  const allSlotsInPage = []
  let currentIndex = groupIndex
  
  // 次のページ開始（hasBreakBeforeがtrue）まで、または最後までスロットを収集
  while (currentIndex < groups.length) {
    const group = groups[currentIndex]
    if (!group) break
    
    // 次のページ開始に到達したら終了（最初のグループ以外でhasBreakBeforeがtrue）
    if (currentIndex > groupIndex && group.hasBreakBefore) {
      break
    }
    
    // グループ内のすべてのスロットを追加（leftとrightを結合）
    allSlotsInPage.push(...(group.left || []), ...(group.right || []))
    
    currentIndex++
  }
  
  if (allSlotsInPage.length === 0) {
    return
  }

  if (!await dialogConfirm(`ページ内の${allSlotsInPage.length}個のスロットを削除しますか？\n（保存ボタンを押すまで確定されません）`, { title: '確認' })) {
    return
  }

  // 🆕 UNDO用にページ内のスロット情報を保存（削除前に）
  const deletedSlotsData = allSlotsInPage.map(slot => ({
    slotId: slot.id,
    slotData: { ...slot },
    slotIndex: slots.value.findIndex(s => s.id === slot.id),
    wasDirty: slotsDirty.value.has(slot.id),
    dirtyData: slotsDirty.value.get(slot.id)
  }))

  // ページ内のすべてのスロットをローカルで削除
  for (const slot of allSlotsInPage) {
    // ローカルでスロットを削除（UIから非表示）
    slots.value = slots.value.filter(s => s.id !== slot.id)
    
    // 削除セットに追加
    deletedSlots.value.add(slot.id)
    
    // ダーティ状態から削除（既に変更がある場合）
    slotsDirty.value.delete(slot.id)
  }
  
  // 🆕 UNDO履歴に追加（ページ削除として）
  addToSlotsUndoHistory('page_delete', {
    deletedSlots: deletedSlotsData
  })
}

// スロットを並び替え
async function handleReorderSlots(newOrder) {
  if (!workId.value) {
    error.value = 'Work IDを入力してください'
    return
  }

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return
  }

  loading.value = true
  error.value = null

  try {
    // 🆕 UNDO用に並び替え前の状態を保存
    const oldOrder = slots.value.map(s => ({
      id: s.id,
      sort_index: s.sort_index
    }))
    
    const updates = generateSortIndexUpdates(slots.value, newOrder)
    
    // ローカル状態のみ更新（サーバーへの送信は行わない）
    updates.forEach(update => {
      const slotIndex = slots.value.findIndex(s => s.id === update.id)
      if (slotIndex !== -1) {
        slots.value[slotIndex].sort_index = update.sort_index
        
        // ダーティフラグを立てる
        const existingChanges = slotsDirty.value.get(update.id) || {}
        slotsDirty.value.set(update.id, {
          ...existingChanges,
          sort_index: update.sort_index
        })
      }
    })
    
    // 🆕 UNDO履歴に追加
    addToSlotsUndoHistory('slots_reorder', {
      oldOrder,
      newOrder,
      updates
    })
  } catch (err) {
    error.value = `スロットの並び替えに失敗しました: ${err.message}`
    console.error(err)
  } finally {
    loading.value = false
  }
}

