// テンプレート追加時の処理
async function handleAddTemplate({ templateId, sortIndex, groupIndex }) {
  if (!workId.value || !templateId || sortIndex === null || sortIndex === undefined) {
    return
  }

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return
  }

  error.value = null
  skipSlotsUndoHistory = true

  try {
    // 1. テンプレートアイテムを取得（サーバーからメタデータのみ）
    const result = await supabaseService.getTemplateItems(templateId)
    const templateItems = result.details || []
    
    if (templateItems.length === 0) {
      error.value = 'テンプレートにアイテムがありません'
      return
    }
    
    // 2. ローカルでスロットを作成（1刻み）
    const newSlots = []
    for (let i = 0; i < templateItems.length; i++) {
      const item = templateItems[i]
      const tempId = `temp_slot_${Date.now()}_${i}`  // 仮ID生成
      const newSlot = {
        id: tempId,
        work_id: workId.value,
        file_id: null,
        sort_index: sortIndex + i,  // 1刻みで挿入
        break_before: item.break_before || false,
        caption: item.caption || null,
        note: item.note || null,
        work_phase_id: item.work_phase_id || null,
        deleted_at: null,
        updated_at: new Date().toISOString()
      }
      newSlots.push(newSlot)
      
      // ダーティフラグを設定（新規作成）
      slotsDirty.value.set(tempId, {
        work_id: workId.value,
        file_id: null,
        sort_index: sortIndex + i,
        break_before: item.break_before || false,
        caption: item.caption || null,
        note: item.note || null,
        work_phase_id: item.work_phase_id || null,
        _isNew: true  // 新規作成フラグ
      })
    }
    
    // 3. 既存のスロットに新しいスロットを挿入
    slots.value.push(...newSlots)
    
    // 4. ローカルでリバランス（1000000刻み）
    rebalanceSlotSortIndexes()
    
  } catch (err) {
    error.value = `テンプレートの追加に失敗しました: ${err.message}`
    console.error('[AddTemplate] Error:', err)
  } finally {
    // 🆕 スロット挿入完了後、UNDO履歴記録を再開
    skipSlotsUndoHistory = false
  }
}

