// スロットのソートオーダーをリバランス（1000000スタート、10000刻み）
function rebalanceSlotSortIndexes() {
  // 現在のソート順を維持したまま、新しいsort_indexを割り当て
  const sortedSlots = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
  
  sortedSlots.forEach((slot, index) => {
    const newSortIndex = 1000000 + (index * 10000)
    if (slot.sort_index !== newSortIndex) {
      slot.sort_index = newSortIndex
      markSlotDirty(slot.id, { sort_index: newSortIndex })
    }
  })
  
  slots.value = sortedSlots
}

// ソートオーダーの間隔をチェックし、必要ならリバランス
function checkAndRebalanceIfNeeded(updatedSlotIds) {
  const sortedSlots = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
  
  // 更新されたスロットの周辺をチェック
  for (const slotId of updatedSlotIds) {
    const index = sortedSlots.findIndex(s => s.id === slotId)
    if (index === -1) continue
    
    // 前のスロットとの間隔をチェック
    if (index > 0) {
      const gap = sortedSlots[index].sort_index - sortedSlots[index - 1].sort_index
      if (gap < 100) {
        rebalanceSlotSortIndexes()
        return
      }
    }
    
    // 次のスロットとの間隔をチェック
    if (index < sortedSlots.length - 1) {
      const gap = sortedSlots[index + 1].sort_index - sortedSlots[index].sort_index
      if (gap < 100) {
        rebalanceSlotSortIndexes()
        return
      }
    }
  }
}

// スロット移動（オプティミスティックUI更新）- 複数スロット対応
// ページ並び替え処理
async function handlePageReorder({ sourceSlots, targetSlotId, position }) {
  if (!workId.value || !isAuthenticated.value) return
  
  const targetSlot = slots.value.find(s => s.id === targetSlotId)
  if (!targetSlot) {
    console.error('[PageReorder] Target slot not found')
    return
  }
  
  // ソートオーダーを計算
  const sortedSlots = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
  const targetIndex = sortedSlots.findIndex(s => s.id === targetSlotId)
  
  let newSortIndex
  if (position === 'below') {
    // targetSlotの下
    const nextSlot = sortedSlots[targetIndex + 1]
    if (nextSlot) {
      newSortIndex = (targetSlot.sort_index + nextSlot.sort_index) / 2
    } else {
      newSortIndex = targetSlot.sort_index + 10000
    }
  } else {
    // targetSlotの上
    const prevSlot = sortedSlots[targetIndex - 1]
    if (prevSlot) {
      newSortIndex = (prevSlot.sort_index + targetSlot.sort_index) / 2
    } else {
      newSortIndex = Math.max(0, targetSlot.sort_index - 10000)
    }
  }
  
  // ソースページの各スロットに新しいsort_indexを割り当て
  const sortedSourceSlots = sourceSlots.sort((a, b) => a.sort_index - b.sort_index)
  const increment = 100 // スロット間の間隔
  
  sortedSourceSlots.forEach((slot, index) => {
    const updatedSortIndex = newSortIndex + (index * increment)
    
    // ローカルのslotsを更新
    const localSlot = slots.value.find(s => s.id === slot.id)
    if (localSlot) {
      localSlot.sort_index = updatedSortIndex
    }
    
    // ダーティ管理に追加
    const changes = slotsDirty.value.get(slot.id) || {}
    slotsDirty.value.set(slot.id, {
      ...changes,
      sort_index: updatedSortIndex
    })
  })
  
  // スロットを再ソート
  slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
}

const SLOT_LOCAL_REINDEX_STEP = 1000
const SLOT_LOCAL_REINDEX_MIN_INTERVAL = 10
const SLOT_FULL_REINDEX_BASE = 1000000
const SLOT_FULL_REINDEX_STEP = 10000

function getSortedSlotsBySortIndex() {
  return [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
}

function buildSlotsToMove(fromSlotId, selectedSlotIds = [], sortedSlots = null) {
  const orderedSlots = sortedSlots || getSortedSlotsBySortIndex()
  const movingSet = new Set([fromSlotId])
  if (selectedSlotIds && selectedSlotIds.length > 0) {
    selectedSlotIds.forEach((slotId) => {
      if (slotId !== fromSlotId) movingSet.add(slotId)
    })
  }
  return orderedSlots.map(s => s.id).filter(id => movingSet.has(id))
}

function buildNormalMoveOrderIds(oldOrderIds, slotsToMove, toSlotId, zone) {
  const movingSet = new Set(slotsToMove)
  if (movingSet.has(toSlotId)) return null

  const remainingIds = oldOrderIds.filter(id => !movingSet.has(id))
  const targetIndex = remainingIds.findIndex(id => id === toSlotId)
  if (targetIndex === -1) return null

  const insertIndex = zone === 'left' ? targetIndex : targetIndex + 1
  return [
    ...remainingIds.slice(0, insertIndex),
    ...slotsToMove,
    ...remainingIds.slice(insertIndex)
  ]
}

function buildDisplayRowsFromSortedSlots(sortedSlots) {
  const displaySlots = prepareSlotsForDisplay(sortedSlots)
  const groups = groupSlotsForGrid(displaySlots)
  const displaySlotMap = new Map(displaySlots.map(slot => [slot.id, slot]))
  const rows = []

  groups.forEach((group) => {
    for (let row = 0; row < 3; row++) {
      const leftId = group.left[row]?.id || null
      const rightId = group.right[row]?.id || null
      if (leftId || rightId) {
        const leftPageNumber = leftId ? displaySlotMap.get(leftId)?.pageNumber : null
        const rightPageNumber = rightId ? displaySlotMap.get(rightId)?.pageNumber : null
        rows.push({
          leftId,
          rightId,
          pageNumber: leftPageNumber ?? rightPageNumber ?? null,
          isPageStart: row === 0 && !!group.hasBreakBefore
        })
      }
    }
  })

  return rows
}

function analyzeFullWidthRectSelection(rows, slotsToMove) {
  if (!slotsToMove || slotsToMove.length < 2) return null

  const movingSet = new Set(slotsToMove)
  const coordById = new Map()
  const coords = []

  rows.forEach((row, rowIndex) => {
    if (row.leftId) coordById.set(row.leftId, { row: rowIndex, col: 0 })
    if (row.rightId) coordById.set(row.rightId, { row: rowIndex, col: 1 })
  })

  for (const id of movingSet) {
    const coord = coordById.get(id)
    if (!coord) return null
    coords.push(coord)
  }

  const getCellId = (row, col) => {
    const rowData = rows[row]
    if (!rowData) return null
    return col === 0 ? rowData.leftId : rowData.rightId
  }

  // 4近傍で連結判定
  const first = coords[0]
  const queue = [first]
  const visited = new Set([`${first.row},${first.col}`])
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]]

  while (queue.length > 0) {
    const current = queue.shift()
    for (const [dr, dc] of dirs) {
      const nr = current.row + dr
      const nc = current.col + dc
      if (nc < 0 || nc > 1) continue
      const neighborId = getCellId(nr, nc)
      if (!neighborId || !movingSet.has(neighborId)) continue
      const key = `${nr},${nc}`
      if (!visited.has(key)) {
        visited.add(key)
        queue.push({ row: nr, col: nc })
      }
    }
  }

  if (visited.size !== movingSet.size) return null

  const minRow = Math.min(...coords.map(c => c.row))
  const maxRow = Math.max(...coords.map(c => c.row))
  const minCol = Math.min(...coords.map(c => c.col))
  const maxCol = Math.max(...coords.map(c => c.col))

  // 欠けなしの矩形判定
  for (let row = minRow; row <= maxRow; row++) {
    for (let col = minCol; col <= maxCol; col++) {
      const id = getCellId(row, col)
      if (!id || !movingSet.has(id)) return null
    }
  }

  // 矩形移動は左右2列をフルで選択している場合のみ有効化
  if (minCol !== 0 || maxCol !== 1) return null

  return {
    startRow: minRow,
    endRow: maxRow
  }
}

function buildRectMoveOrderIds(sortedSlots, slotsToMove, toSlotId, zone) {
  if (zone !== 'left' && zone !== 'right') return null
  const movingSet = new Set(slotsToMove)
  if (movingSet.has(toSlotId)) return null

  const rows = buildDisplayRowsFromSortedSlots(sortedSlots)
  const rectInfo = analyzeFullWidthRectSelection(rows, slotsToMove)
  if (!rectInfo) return null

  const blockRows = rows.slice(rectInfo.startRow, rectInfo.endRow + 1)
  const blockPageNumbers = new Set(blockRows.map(row => row.pageNumber).filter(n => n !== null))
  // break_before を跨ぐ移動で崩れないよう、矩形移動は同一ページ内のみ許可
  if (blockPageNumbers.size !== 1) return null

  const remainingRows = [
    ...rows.slice(0, rectInfo.startRow),
    ...rows.slice(rectInfo.endRow + 1)
  ]

  const targetRowIndex = remainingRows.findIndex(
    row => (row.leftId === toSlotId || row.rightId === toSlotId)
  )
  if (targetRowIndex === -1) return null

  const insertRowIndex = zone === 'left' ? targetRowIndex : targetRowIndex + 1
  const newRows = [
    ...remainingRows.slice(0, insertRowIndex),
    ...blockRows,
    ...remainingRows.slice(insertRowIndex)
  ]

  // 表示行（left/right）を内部順序へ戻す
  // ページ境界は旧pageNumberではなく、行に付随する改ページ開始マーカーで判定する
  const newOrderIds = []
  let pageRows = []
  for (let i = 0; i < newRows.length; i++) {
    const row = newRows[i]
    const prevRow = i > 0 ? newRows[i - 1] : null
    // 旧isPageStartだけで分割すると、同一ページ内の先頭上挿入で誤分割するため、
    // ページ番号が切り替わる地点のみページ境界として扱う。
    if (i > 0 && row.isPageStart && prevRow && prevRow.pageNumber !== row.pageNumber) {
      for (let j = 0; j < pageRows.length; j += 3) {
        const chunk = pageRows.slice(j, j + 3)
        chunk.forEach((chunkRow) => {
          if (chunkRow.leftId) newOrderIds.push(chunkRow.leftId)
        })
        chunk.forEach((chunkRow) => {
          if (chunkRow.rightId) newOrderIds.push(chunkRow.rightId)
        })
      }
      pageRows = []
    }
    pageRows.push(row)
  }

  if (pageRows.length > 0) {
    for (let j = 0; j < pageRows.length; j += 3) {
      const chunk = pageRows.slice(j, j + 3)
      chunk.forEach((row) => {
        if (row.leftId) newOrderIds.push(row.leftId)
      })
      chunk.forEach((row) => {
        if (row.rightId) newOrderIds.push(row.rightId)
      })
    }
  }

  return newOrderIds
}

function canOfferRectMoveOption(sortedSlots, slotsToMove) {
  if (!slotsToMove || slotsToMove.length < 2) return false
  const rows = buildDisplayRowsFromSortedSlots(sortedSlots)
  const rectInfo = analyzeFullWidthRectSelection(rows, slotsToMove)
  if (!rectInfo) return false

  const blockRows = rows.slice(rectInfo.startRow, rectInfo.endRow + 1)
  const blockPageNumbers = new Set(blockRows.map(row => row.pageNumber).filter(n => n !== null))
  // 選択ブロックは同一ページ内のみ行挿入候補とする
  return blockPageNumbers.size === 1
}

function getRectTopLeftSlotId(sortedSlots, slotsToMove) {
  const rows = buildDisplayRowsFromSortedSlots(sortedSlots)
  const movingSet = new Set(slotsToMove || [])
  if (movingSet.size === 0) return null

  const coords = []
  rows.forEach((row, rowIndex) => {
    if (row.leftId && movingSet.has(row.leftId)) {
      coords.push({ id: row.leftId, row: rowIndex, col: 0 })
    }
    if (row.rightId && movingSet.has(row.rightId)) {
      coords.push({ id: row.rightId, row: rowIndex, col: 1 })
    }
  })

  if (coords.length === 0) return null

  // 厳密矩形判定には依存せず、選択集合の中で最も左上のセルを起点とする
  coords.sort((a, b) => (a.row - b.row) || (a.col - b.col))
  return coords[0].id
}

function getPageStartSlotIdForDrop(sortedSlots, toSlotId) {
  const rows = buildDisplayRowsFromSortedSlots(sortedSlots)
  const targetRow = rows.find(row => row.leftId === toSlotId || row.rightId === toSlotId)
  if (!targetRow || !targetRow.isPageStart) return null
  return targetRow.leftId || toSlotId
}

function getDropRowLeftSlotId(sortedSlots, toSlotId) {
  const rows = buildDisplayRowsFromSortedSlots(sortedSlots)
  const targetRow = rows.find(row => row.leftId === toSlotId || row.rightId === toSlotId)
  return targetRow?.leftId || null
}

function isStrictlyIncreasingSortIndexes(sortedSlots) {
  for (let i = 0; i < sortedSlots.length; i++) {
    const value = sortedSlots[i].sort_index
    if (!Number.isFinite(value)) return false
    if (i > 0 && sortedSlots[i - 1].sort_index >= value) return false
  }
  return true
}

function buildFullReindexSortUpdates(sortedSlots, newOrderIds) {
  const oldSortMap = new Map(sortedSlots.map(slot => [slot.id, slot.sort_index]))
  return newOrderIds.map((id, index) => {
    const newSortIndex = SLOT_FULL_REINDEX_BASE + (index * SLOT_FULL_REINDEX_STEP)
    return {
      id,
      oldSortIndex: oldSortMap.get(id),
      newSortIndex
    }
  }).filter(item => item.oldSortIndex !== item.newSortIndex)
}

function buildLocalizedSortUpdates(sortedSlots, newOrderIds) {
  const oldOrderIds = sortedSlots.map(s => s.id)
  const oldSortMap = new Map(sortedSlots.map(slot => [slot.id, slot.sort_index]))

  const changedPositions = []
  for (let i = 0; i < oldOrderIds.length; i++) {
    if (oldOrderIds[i] !== newOrderIds[i]) changedPositions.push(i)
  }
  if (changedPositions.length === 0) return []

  if (!isStrictlyIncreasingSortIndexes(sortedSlots)) {
    return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
  }

  const changedPosSet = new Set(changedPositions)
  const runs = []
  let runStart = null

  for (let i = 0; i < newOrderIds.length; i++) {
    if (changedPosSet.has(i)) {
      if (runStart === null) runStart = i
    } else if (runStart !== null) {
      runs.push([runStart, i - 1])
      runStart = null
    }
  }
  if (runStart !== null) runs.push([runStart, newOrderIds.length - 1])

  const updates = []
  for (const [start, end] of runs) {
    const runLen = end - start + 1
    const leftId = start > 0 ? newOrderIds[start - 1] : null
    const rightId = end < newOrderIds.length - 1 ? newOrderIds[end + 1] : null

    let interval = SLOT_LOCAL_REINDEX_STEP
    let startSortIndex = SLOT_FULL_REINDEX_BASE

    if (leftId && rightId) {
      const leftSort = oldSortMap.get(leftId)
      const rightSort = oldSortMap.get(rightId)
      const gap = rightSort - leftSort

      if (!Number.isFinite(leftSort) || !Number.isFinite(rightSort) || gap <= 0) {
        return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
      }

      interval = Math.floor(gap / (runLen + 1))
      if (interval < SLOT_LOCAL_REINDEX_MIN_INTERVAL) {
        return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
      }
      startSortIndex = leftSort + interval
    } else if (leftId) {
      const leftSort = oldSortMap.get(leftId)
      if (!Number.isFinite(leftSort)) {
        return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
      }
      startSortIndex = leftSort + interval
    } else if (rightId) {
      const rightSort = oldSortMap.get(rightId)
      if (!Number.isFinite(rightSort)) {
        return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
      }
      startSortIndex = rightSort - (interval * runLen)
      if (startSortIndex <= 0) {
        return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
      }
    }

    for (let offset = 0; offset < runLen; offset++) {
      const id = newOrderIds[start + offset]
      const oldSortIndex = oldSortMap.get(id)
      const newSortIndex = Math.round(startSortIndex + (interval * offset))
      if (oldSortIndex !== newSortIndex) {
        updates.push({ id, oldSortIndex, newSortIndex })
      }
    }
  }

  // 更新後も昇順が維持されることを最終確認
  const mergedSortMap = new Map(oldSortMap)
  updates.forEach(({ id, newSortIndex }) => mergedSortMap.set(id, newSortIndex))
  for (let i = 1; i < newOrderIds.length; i++) {
    const prev = mergedSortMap.get(newOrderIds[i - 1])
    const current = mergedSortMap.get(newOrderIds[i])
    if (!Number.isFinite(prev) || !Number.isFinite(current) || prev >= current) {
      return buildFullReindexSortUpdates(sortedSlots, newOrderIds)
    }
  }

  return updates
}

function applySortUpdates(sortUpdates) {
  if (!sortUpdates || sortUpdates.length === 0) return

  const updateMap = new Map(sortUpdates.map(item => [item.id, item.newSortIndex]))
  slots.value.forEach((slot) => {
    if (updateMap.has(slot.id)) {
      const nextSortIndex = updateMap.get(slot.id)
      slot.sort_index = nextSortIndex
      markSlotDirty(slot.id, { sort_index: nextSortIndex })
    }
  })

  slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
}

function logSlotMoveDirtyDebug(sortedSlots, oldOrderIds, newOrderIds, sortUpdates, moveMode) {
  const oldSortMap = new Map(sortedSlots.map(slot => [slot.id, slot.sort_index]))
  const oldPosMap = new Map(oldOrderIds.map((id, index) => [id, index + 1]))
  const newPosMap = new Map(newOrderIds.map((id, index) => [id, index + 1]))

  const debugRows = sortUpdates.map((item) => ({
    id: item.id,
    oldPosition: oldPosMap.get(item.id),
    oldSortIndex: oldSortMap.get(item.id),
    newPosition: newPosMap.get(item.id),
    newSortIndex: item.newSortIndex
  }))

  console.groupCollapsed(`[SlotMoveDebug] mode=${moveMode} dirty=${debugRows.length}`)
  console.table(debugRows)
  console.groupEnd()
}

function executeSlotMove(action, moveMode = 'normal', triggerPostMoveGlow = false) {
  if (!action) return
  if (!workId.value || !isAuthenticated.value) return

  const { fromSlotId, toSlotId, zone, selectedSlotIds = [] } = action
  if (zone !== 'left' && zone !== 'right') return

  const sortedSlots = getSortedSlotsBySortIndex()
  const oldOrderIds = sortedSlots.map(s => s.id)
  const slotsToMove = buildSlotsToMove(fromSlotId, selectedSlotIds, sortedSlots)
  if (slotsToMove.length === 0 || slotsToMove.includes(toSlotId)) return

  if (moveMode === 'rect') {
    const displaySlots = prepareSlotsForDisplay(sortedSlots)
    const displayMap = new Map(displaySlots.map(slot => [slot.id, slot]))

    const sourceTopLeftSlotId = getRectTopLeftSlotId(sortedSlots, slotsToMove)
    const sourceTopLeftSlot = sourceTopLeftSlotId
      ? slots.value.find(s => s.id === sourceTopLeftSlotId)
      : null
    const sourcePageNumber = sourceTopLeftSlotId ? displayMap.get(sourceTopLeftSlotId)?.pageNumber : null

    const targetLeftSlotId = getDropRowLeftSlotId(sortedSlots, toSlotId)
    const targetLeftSlot = targetLeftSlotId
      ? slots.value.find(s => s.id === targetLeftSlotId)
      : null
    const targetPageNumber = targetLeftSlotId ? displayMap.get(targetLeftSlotId)?.pageNumber : null

    const sourceIsPageStart = !!sourceTopLeftSlot?.break_before
    const targetIsPageStartAndDifferentPageOnUpMove = zone === 'left' &&
      !!targetLeftSlot?.break_before &&
      sourcePageNumber !== null &&
      targetPageNumber !== null &&
      sourcePageNumber !== targetPageNumber

    if (sourceIsPageStart || targetIsPageStartAndDifferentPageOnUpMove) {
      void dialogAlert('ページの先頭がずれるため挿入できませんでした。', { title: 'エラー' })
      return
    }
  }

  let newOrderIds = null
  if (moveMode === 'rect') {
    newOrderIds = buildRectMoveOrderIds(sortedSlots, slotsToMove, toSlotId, zone)
    if (!newOrderIds) {
      // 行挿入を選択した場合は通常移動へフォールバックしない
      // （通常移動と同じ結果になって意図が伝わらないため）
      console.warn('[RowInsert] 行挿入の順序生成に失敗したため処理を中断しました', {
        fromSlotId,
        toSlotId,
        zone,
        slotsToMove
      })
      void dialogAlert('行挿入を適用できませんでした。\n選択範囲またはドロップ位置を確認してください。', { title: 'エラー' })
      return
    }
  } else {
    newOrderIds = buildNormalMoveOrderIds(oldOrderIds, slotsToMove, toSlotId, zone)
  }
  if (!newOrderIds || newOrderIds.length !== oldOrderIds.length) return

  const hasOrderChange = newOrderIds.some((id, index) => id !== oldOrderIds[index])
  if (!hasOrderChange) return

  const sortUpdates = buildLocalizedSortUpdates(sortedSlots, newOrderIds)
  if (!sortUpdates || sortUpdates.length === 0) return

  // テスト用: ダーティ対象スロットの変更前順番/ソートオーダーを出力
  logSlotMoveDirtyDebug(sortedSlots, oldOrderIds, newOrderIds, sortUpdates, moveMode)

  applySortUpdates(sortUpdates)

  const additionalFieldChanges = []
  // 行挿入(矩形) + ↑移動 + ドロップ先が改ページ開始の場合:
  // 移動元ブロック左上を改ページ開始にし、カテゴリー(caption)をドロップ先から引き継ぐ。
  // ドロップ先の改ページ開始は解除する。
  // ただし、移動元左上が既にbreak_beforeの場合は移動元側の改ページを維持する。
  if (moveMode === 'rect' && zone === 'left') {
    const pageStartTargetSlotId = getPageStartSlotIdForDrop(sortedSlots, toSlotId)
    const targetSlot = pageStartTargetSlotId
      ? slots.value.find(s => s.id === pageStartTargetSlotId)
      : null
    const sourceTopLeftSlotId = getRectTopLeftSlotId(sortedSlots, slotsToMove)
    const sourceTopLeftSlot = sourceTopLeftSlotId
      ? slots.value.find(s => s.id === sourceTopLeftSlotId)
      : null

    if (targetSlot?.break_before && sourceTopLeftSlot && sourceTopLeftSlot.id !== targetSlot.id && !sourceTopLeftSlot.break_before) {
      const sourceOldValues = {
        break_before: !!sourceTopLeftSlot.break_before,
        caption: sourceTopLeftSlot.caption ?? null
      }
      const sourceNewValues = {
        break_before: true,
        caption: targetSlot.caption ?? null
      }

      const targetOldValues = {
        break_before: !!targetSlot.break_before
      }
      const targetNewValues = {
        break_before: false
      }

      const sourceChanged = sourceOldValues.break_before !== sourceNewValues.break_before ||
        sourceOldValues.caption !== sourceNewValues.caption
      if (sourceChanged) {
        Object.assign(sourceTopLeftSlot, sourceNewValues)
        markSlotDirty(sourceTopLeftSlot.id, sourceNewValues)
        additionalFieldChanges.push({
          id: sourceTopLeftSlot.id,
          oldValues: sourceOldValues,
          newValues: sourceNewValues
        })
      }

      const targetChanged = targetOldValues.break_before !== targetNewValues.break_before
      if (targetChanged) {
        Object.assign(targetSlot, targetNewValues)
        markSlotDirty(targetSlot.id, targetNewValues)
        additionalFieldChanges.push({
          id: targetSlot.id,
          oldValues: targetOldValues,
          newValues: targetNewValues
        })
      }
    }
    else {
      console.debug('[RowInsertBreakBefore] skipped', {
        pageStartTargetSlotId,
        targetBreakBefore: targetSlot?.break_before ?? null,
        sourceTopLeftSlotId
      })
    }
  }

  addToSlotsUndoHistory('slot_move', {
    movedSlotIds: slotsToMove,
    moveMode,
    oldOrder: sortUpdates.map(item => ({
      id: item.id,
      sort_index: item.oldSortIndex
    })),
    newOrder: sortUpdates.map(item => ({
      id: item.id,
      sort_index: item.newSortIndex
    })),
    additionalFieldChanges
  })

  // モーダル確定後は移動後の位置で再点滅させる
  if (triggerPostMoveGlow && slotGridRef.value?.triggerMoveGlow) {
    slotGridRef.value.triggerMoveGlow(slotsToMove)
  }
}

// スロット移動処理
async function handleSlotMove(fromSlotId, toSlotId, zone, selectedSlotIds = []) {
  if (!workId.value || !isAuthenticated.value) return
  if (zone !== 'left' && zone !== 'right') return

  const sortedSlots = getSortedSlotsBySortIndex()
  const slotsToMove = buildSlotsToMove(fromSlotId, selectedSlotIds, sortedSlots)
  if (slotsToMove.length === 0 || slotsToMove.includes(toSlotId)) return

  const canOfferRectMove = canOfferRectMoveOption(sortedSlots, slotsToMove)
  if (canOfferRectMove) {
    if (slotGridRef.value?.setSuppressNextDropGlow) {
      slotGridRef.value.setSuppressNextDropGlow(true)
    }
    pendingSlotMoveAction.value = {
      fromSlotId,
      toSlotId,
      zone,
      selectedSlotIds: [...slotsToMove]
    }
    showSlotMoveModeModal.value = true
    return
  }

  executeSlotMove({
    fromSlotId,
    toSlotId,
    zone,
    selectedSlotIds
  }, 'normal')
}

// スロット入替（オプティミスティックUI更新）- 複数スロット対応
async function handleSlotSwap(slotId1, slotId2, selectedSlotIds = []) {
  // ↓移動もslot-move(right)と同一経路に統一し、
  // 行挿入（矩形）モーダル・局所再採番・UNDOを共通化する
  await handleSlotMove(slotId1, slotId2, 'right', selectedSlotIds)
}

function buildRangeCopyPlan(sortedSlots, sourceSlotIds, targetSlotId) {
  const rows = buildDisplayRowsFromSortedSlots(sortedSlots)
  const movingSet = new Set(sourceSlotIds || [])
  if (movingSet.size === 0) return null

  const coordById = new Map()
  const coords = []
  rows.forEach((row, rowIndex) => {
    if (row.leftId) coordById.set(row.leftId, { row: rowIndex, col: 0 })
    if (row.rightId) coordById.set(row.rightId, { row: rowIndex, col: 1 })
  })

  for (const id of movingSet) {
    const coord = coordById.get(id)
    if (!coord) return null
    coords.push(coord)
  }
  if (coords.length === 0) return null

  const getCellId = (rowIndex, col) => {
    const row = rows[rowIndex]
    if (!row) return null
    return col === 0 ? row.leftId : row.rightId
  }

  // 4近傍の連結判定
  const first = coords[0]
  const queue = [first]
  const visited = new Set([`${first.row},${first.col}`])
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]]
  while (queue.length > 0) {
    const current = queue.shift()
    for (const [dr, dc] of dirs) {
      const nr = current.row + dr
      const nc = current.col + dc
      if (nc < 0 || nc > 1) continue
      const id = getCellId(nr, nc)
      if (!id || !movingSet.has(id)) continue
      const key = `${nr},${nc}`
      if (!visited.has(key)) {
        visited.add(key)
        queue.push({ row: nr, col: nc })
      }
    }
  }
  if (visited.size !== movingSet.size) return null

  const minRow = Math.min(...coords.map(c => c.row))
  const maxRow = Math.max(...coords.map(c => c.row))
  const minCol = Math.min(...coords.map(c => c.col))
  const maxCol = Math.max(...coords.map(c => c.col))
  const height = maxRow - minRow + 1
  const width = maxCol - minCol + 1
  if (height <= 0 || (width !== 1 && width !== 2)) return null

  // 欠けなし矩形（縦1列 or 左右2列）
  for (let r = minRow; r <= maxRow; r++) {
    for (let c = minCol; c <= maxCol; c++) {
      const id = getCellId(r, c)
      if (!id || !movingSet.has(id)) return null
    }
  }

  const sourceRows = rows.slice(minRow, maxRow + 1)
  const sourcePageNumbers = new Set(sourceRows.map(row => row.pageNumber).filter(n => n !== null))
  if (sourcePageNumbers.size !== 1) return null

  const targetStartRow = rows.findIndex(row => row.leftId === targetSlotId || row.rightId === targetSlotId)
  if (targetStartRow === -1) return null

  const targetRows = rows.slice(targetStartRow, targetStartRow + height)
  if (targetRows.length !== height) return null

  const targetPageNumber = targetRows[0]?.pageNumber ?? null
  if (targetPageNumber === null) return null
  if (targetRows.some(row => row.pageNumber !== targetPageNumber)) return null

  const targetStartCol = targetRows[0]?.leftId === targetSlotId ? 0 : 1
  const mappings = []

  if (width === 2) {
    // 従来: 左右の列をそのまま対応させる
    if (targetRows.some(row => !row.leftId || !row.rightId)) return null
    for (let i = 0; i < height; i++) {
      mappings.push({ sourceId: sourceRows[i].leftId, targetId: targetRows[i].leftId })
      mappings.push({ sourceId: sourceRows[i].rightId, targetId: targetRows[i].rightId })
    }
  } else {
    // 追加: 縦1列連続。ドロップ先の列（左/右）に縦方向でコピーする
    for (let i = 0; i < height; i++) {
      const sourceId = minCol === 0 ? sourceRows[i].leftId : sourceRows[i].rightId
      const targetId = targetStartCol === 0 ? targetRows[i].leftId : targetRows[i].rightId
      if (!sourceId || !targetId) return null
      mappings.push({ sourceId, targetId })
    }
  }

  return {
    sourceRows,
    targetRows,
    mappings: mappings.filter(pair => pair.sourceId && pair.targetId)
  }
}

function buildPageRows(pageSlots) {
  const rows = []
  for (let i = 0; i < pageSlots.length; i += 6) {
    const chunk = pageSlots.slice(i, i + 6)
    for (let row = 0; row < 3; row++) {
      const leftSlot = chunk[row] || null
      const rightSlot = chunk[row + 3] || null
      if (leftSlot || rightSlot) {
        rows.push({
          leftId: leftSlot?.id || null,
          rightId: rightSlot?.id || null
        })
      }
    }
  }
  return rows
}

function flattenRowsToLinearOrder(rows) {
  const order = []
  for (let i = 0; i < rows.length; i += 3) {
    const chunk = rows.slice(i, i + 3)
    chunk.forEach((row) => {
      if (row.leftId) order.push(row.leftId)
    })
    chunk.forEach((row) => {
      if (row.rightId) order.push(row.rightId)
    })
  }
  return order
}

async function handleRowInsertAtSlot(targetSlotId) {
  if (!workId.value || !isAuthenticated.value) return

  const sortedSlots = getSortedSlotsBySortIndex()
  const displaySlots = prepareSlotsForDisplay(sortedSlots)
  const targetDisplaySlot = displaySlots.find(s => s.id === targetSlotId)
  if (!targetDisplaySlot) return

  const targetPageNumber = targetDisplaySlot.pageNumber
  const pageSlots = displaySlots.filter(s => s.pageNumber === targetPageNumber)
  if (pageSlots.length === 0) return

  const pageRows = buildPageRows(pageSlots)
  const targetRowIndex = pageRows.findIndex(row => row.leftId === targetSlotId || row.rightId === targetSlotId)
  if (targetRowIndex === -1) return

  const tempLeftId = `temp_slot_row_insert_${Date.now()}_l`
  const tempRightId = `temp_slot_row_insert_${Date.now()}_r`
  const additionalFieldChanges = []
  const insertedRow = { leftId: tempLeftId, rightId: tempRightId }
  const newPageRows = [
    ...pageRows.slice(0, targetRowIndex + 1),
    insertedRow,
    ...pageRows.slice(targetRowIndex + 1)
  ]
  const newPageOrderIds = flattenRowsToLinearOrder(newPageRows)

  const oldOrderIds = sortedSlots.map(s => s.id)
  const firstPageIdx = oldOrderIds.findIndex(id => id === pageSlots[0].id)
  const lastPageIdx = oldOrderIds.findIndex(id => id === pageSlots[pageSlots.length - 1].id)
  if (firstPageIdx === -1 || lastPageIdx === -1) return

  const sortMap = new Map(sortedSlots.map(slot => [slot.id, slot.sort_index]))
  const leftAnchorId = firstPageIdx > 0 ? oldOrderIds[firstPageIdx - 1] : null
  const rightAnchorId = lastPageIdx < oldOrderIds.length - 1 ? oldOrderIds[lastPageIdx + 1] : null
  const leftAnchorSort = leftAnchorId ? sortMap.get(leftAnchorId) : null
  const rightAnchorSort = rightAnchorId ? sortMap.get(rightAnchorId) : null

  let interval = SLOT_LOCAL_REINDEX_STEP
  let startSortIndex = null
  const segmentLen = newPageOrderIds.length

  if (Number.isFinite(leftAnchorSort) && Number.isFinite(rightAnchorSort)) {
    const gap = rightAnchorSort - leftAnchorSort
    interval = Math.floor(gap / (segmentLen + 1))
    if (!Number.isFinite(interval) || interval < SLOT_LOCAL_REINDEX_MIN_INTERVAL) {
      interval = SLOT_FULL_REINDEX_STEP
      startSortIndex = SLOT_FULL_REINDEX_BASE
    } else {
      startSortIndex = leftAnchorSort + interval
    }
  } else if (Number.isFinite(leftAnchorSort)) {
    startSortIndex = leftAnchorSort + interval
  } else if (Number.isFinite(rightAnchorSort)) {
    startSortIndex = rightAnchorSort - (interval * segmentLen)
    if (!Number.isFinite(startSortIndex) || startSortIndex <= 0) {
      startSortIndex = SLOT_FULL_REINDEX_BASE
    }
  } else {
    startSortIndex = SLOT_FULL_REINDEX_BASE
  }

  const nowIso = new Date().toISOString()
  // 行挿入ボタンは「↓基準」なので、ページ開始フラグは既存スロットを維持
  const insertedLeftBreakBefore = false

  const newSlotBase = {
    work_id: workId.value,
    file_id: null,
    caption: null,
    note: '',
    work_phase_id: '',
    break_before: false,
    deleted_at: null,
    updated_at: nowIso
  }

  const newSlots = [
    { id: tempLeftId, ...newSlotBase, break_before: insertedLeftBreakBefore },
    { id: tempRightId, ...newSlotBase }
  ]
  slots.value.push(...newSlots)

  const oldOrderForUndo = []
  const segmentIds = new Set(newPageOrderIds)
  sortedSlots.forEach((slot) => {
    if (segmentIds.has(slot.id)) {
      oldOrderForUndo.push({ id: slot.id, sort_index: slot.sort_index })
    }
  })

  newPageOrderIds.forEach((id, index) => {
    const nextSortIndex = Math.round(startSortIndex + (interval * index))
    const slot = slots.value.find(s => s.id === id)
    if (!slot) return
    slot.sort_index = nextSortIndex
    markSlotDirty(id, { sort_index: nextSortIndex })
  })

  // 新規スロットは作成ダーティを付与
  newSlots.forEach((slot) => {
    const dirtyData = slotsDirty.value.get(slot.id) || {}
    slotsDirty.value.set(slot.id, {
      ...dirtyData,
      work_id: slot.work_id,
      file_id: slot.file_id,
      sort_index: slot.sort_index,
      caption: slot.caption,
      note: slot.note,
      work_phase_id: slot.work_phase_id,
      break_before: slot.break_before,
      _isNew: true
    })
  })

  slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)

  addToSlotsUndoHistory('slot_row_insert', {
    targetSlotId,
    insertedSlotIds: [tempLeftId, tempRightId],
    oldOrder: oldOrderForUndo,
    additionalFieldChanges,
    newOrder: newPageOrderIds.map((id) => {
      const slot = slots.value.find(s => s.id === id)
      return { id, sort_index: slot?.sort_index }
    })
  })

  if (slotGridRef.value?.triggerMoveGlow) {
    slotGridRef.value.triggerMoveGlow([tempLeftId, tempRightId])
  }
}

function handleDeleteColumnAtSlot(targetSlotId) {
  if (!workId.value || !isAuthenticated.value) return

  const sortedSlots = getSortedSlotsBySortIndex()
  const displaySlots = prepareSlotsForDisplay(sortedSlots)
  const targetDisplaySlot = displaySlots.find(s => s.id === targetSlotId)
  if (!targetDisplaySlot) return

  // 左列のみ有効（各6枠ごとの 1,2,3 / 7,8,9 / ...）
  const targetSlotNumber = targetDisplaySlot.slotNumberInPage || 0
  const slotPositionInBlock = ((targetSlotNumber - 1) % 6) + 1
  if (targetSlotNumber < 1 || slotPositionInBlock > 3) return

  const targetPageNumber = targetDisplaySlot.pageNumber
  const pageSlots = displaySlots.filter(s => s.pageNumber === targetPageNumber)
  if (pageSlots.length === 0) return

  const pageRows = buildPageRows(pageSlots)
  const targetRowIndex = pageRows.findIndex(row => row.leftId === targetSlotId)
  if (targetRowIndex === -1) return

  const targetRow = pageRows[targetRowIndex]
  const deleteIds = [targetRow.leftId, targetRow.rightId].filter(Boolean)
  if (deleteIds.length === 0) return

  const newPageRows = pageRows.filter((_, index) => index !== targetRowIndex)
  const newPageOrderIds = flattenRowsToLinearOrder(newPageRows)

  const oldOrderIds = sortedSlots.map(s => s.id)
  const firstPageIdx = oldOrderIds.findIndex(id => id === pageSlots[0].id)
  const lastPageIdx = oldOrderIds.findIndex(id => id === pageSlots[pageSlots.length - 1].id)
  if (firstPageIdx === -1 || lastPageIdx === -1) return

  const sortMap = new Map(sortedSlots.map(slot => [slot.id, slot.sort_index]))
  const leftAnchorId = firstPageIdx > 0 ? oldOrderIds[firstPageIdx - 1] : null
  const rightAnchorId = lastPageIdx < oldOrderIds.length - 1 ? oldOrderIds[lastPageIdx + 1] : null
  const leftAnchorSort = leftAnchorId ? sortMap.get(leftAnchorId) : null
  const rightAnchorSort = rightAnchorId ? sortMap.get(rightAnchorId) : null

  let interval = SLOT_LOCAL_REINDEX_STEP
  let startSortIndex = null
  const segmentLen = newPageOrderIds.length

  if (segmentLen > 0) {
    if (Number.isFinite(leftAnchorSort) && Number.isFinite(rightAnchorSort)) {
      const gap = rightAnchorSort - leftAnchorSort
      interval = Math.floor(gap / (segmentLen + 1))
      if (!Number.isFinite(interval) || interval < SLOT_LOCAL_REINDEX_MIN_INTERVAL) {
        interval = SLOT_FULL_REINDEX_STEP
        startSortIndex = SLOT_FULL_REINDEX_BASE
      } else {
        startSortIndex = leftAnchorSort + interval
      }
    } else if (Number.isFinite(leftAnchorSort)) {
      startSortIndex = leftAnchorSort + interval
    } else if (Number.isFinite(rightAnchorSort)) {
      startSortIndex = rightAnchorSort - (interval * segmentLen)
      if (!Number.isFinite(startSortIndex) || startSortIndex <= 0) {
        startSortIndex = SLOT_FULL_REINDEX_BASE
      }
    } else {
      startSortIndex = SLOT_FULL_REINDEX_BASE
    }
  }

  const deletedSlotsData = deleteIds.map((id) => {
    const slot = slots.value.find(s => s.id === id)
    if (!slot) return null
    return {
      slotId: slot.id,
      slotData: { ...slot },
      slotIndex: slots.value.findIndex(s => s.id === slot.id),
      wasDirty: slotsDirty.value.has(slot.id),
      dirtyData: slotsDirty.value.get(slot.id)
    }
  }).filter(Boolean)

  const oldOrderForUndo = []
  const segmentIds = new Set(newPageOrderIds)
  sortedSlots.forEach((slot) => {
    if (segmentIds.has(slot.id)) {
      oldOrderForUndo.push({ id: slot.id, sort_index: slot.sort_index })
    }
  })

  newPageOrderIds.forEach((id, index) => {
    if (!Number.isFinite(startSortIndex)) return
    const nextSortIndex = Math.round(startSortIndex + (interval * index))
    const slot = slots.value.find(s => s.id === id)
    if (!slot) return
    slot.sort_index = nextSortIndex
    markSlotDirty(id, { sort_index: nextSortIndex })
  })

  const slotsToDelete = deleteIds.map((id) => slots.value.find(s => s.id === id)).filter(Boolean)
  if (slotsToDelete.length === 0) return

  slotsToDelete.forEach((slot) => {
    slots.value = slots.value.filter(s => s.id !== slot.id)
    deletedSlots.value.add(slot.id)
    slotsDirty.value.delete(slot.id)
  })

  slots.value = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)

  addToSlotsUndoHistory('slot_column_delete', {
    targetSlotId,
    deletedSlotsData,
    oldOrder: oldOrderForUndo,
    newOrder: newPageOrderIds.map((id) => {
      const slot = slots.value.find(s => s.id === id)
      return { id, sort_index: slot?.sort_index }
    })
  })
}

function executeSlotCopy(action, copyMode = 'head', triggerPostCopyGlow = false) {
  if (!action) return
  if (!workId.value || !isAuthenticated.value) return

  const { sourceSlotId, targetSlotId, selectedSlotIds = [] } = action
  const sortedSlots = getSortedSlotsBySortIndex()
  const sourceSlotIds = buildSlotsToMove(sourceSlotId, selectedSlotIds, sortedSlots)

  if (copyMode === 'range') {
    const plan = buildRangeCopyPlan(sortedSlots, sourceSlotIds, targetSlotId)
    if (!plan || plan.mappings.length === 0) {
      void dialogAlert('範囲コピーを適用できませんでした。選択範囲またはドロップ位置を確認してください。', { title: 'エラー' })
      return
    }

    const copyItems = []
    const glowingTargetIds = []
    plan.mappings.forEach(({ sourceId, targetId }) => {
      const sourceSlot = slots.value.find(s => s.id === sourceId)
      const targetSlot = slots.value.find(s => s.id === targetId)
      if (!sourceSlot || !targetSlot) return

      const oldValues = {
        file_id: targetSlot.file_id,
        work_phase_id: targetSlot.work_phase_id,
        note: targetSlot.note,
        caption: targetSlot.caption
      }
      const newValues = {
        file_id: sourceSlot.file_id,
        work_phase_id: sourceSlot.work_phase_id,
        note: sourceSlot.note,
        caption: sourceSlot.caption
      }

      targetSlot.file_id = newValues.file_id
      targetSlot.work_phase_id = newValues.work_phase_id
      targetSlot.note = newValues.note
      targetSlot.caption = newValues.caption
      markSlotDirty(targetId, newValues)

      copyItems.push({
        targetSlotId: targetId,
        oldValues,
        newValues
      })
      glowingTargetIds.push(targetId)
    })

    if (copyItems.length === 0) return

    addToSlotsUndoHistory('slot_drag_copy_range', {
      copyItems
    })

    if (triggerPostCopyGlow && slotGridRef.value?.triggerMoveGlow) {
      slotGridRef.value.triggerMoveGlow(glowingTargetIds)
    }
    return
  }

  const sourceSlot = slots.value.find(s => s.id === sourceSlotId)
  const targetSlot = slots.value.find(s => s.id === targetSlotId)
  if (!sourceSlot || !targetSlot) return

  const oldValues = {
    file_id: targetSlot.file_id,
    work_phase_id: targetSlot.work_phase_id,
    note: targetSlot.note,
    caption: targetSlot.caption
  }
  const newValues = {
    file_id: sourceSlot.file_id,
    work_phase_id: sourceSlot.work_phase_id,
    note: sourceSlot.note,
    caption: sourceSlot.caption
  }

  targetSlot.file_id = newValues.file_id
  targetSlot.work_phase_id = newValues.work_phase_id
  targetSlot.note = newValues.note
  targetSlot.caption = newValues.caption
  markSlotDirty(targetSlotId, newValues)

  addToSlotsUndoHistory('slot_drag_copy', {
    targetSlotId,
    oldValues,
    newValues
  })

  if (triggerPostCopyGlow && slotGridRef.value?.triggerMoveGlow) {
    slotGridRef.value.triggerMoveGlow([targetSlotId])
  }
}

// スロットコピー（ローカル更新のみ、保存時に一括送信）
async function handleSlotCopy(sourceSlotId, targetSlotId, selectedSlotIds = []) {
  if (!workId.value || !isAuthenticated.value) return

  const sortedSlots = getSortedSlotsBySortIndex()
  const sourceSlotIds = buildSlotsToMove(sourceSlotId, selectedSlotIds, sortedSlots)
  // 1スロット選択時は実質「先頭のみコピー」と同義なので、範囲コピー選択モーダルは出さない
  const canOfferRangeCopy = sourceSlotIds.length > 1 && !!buildRangeCopyPlan(sortedSlots, sourceSlotIds, targetSlotId)

  if (canOfferRangeCopy) {
    if (slotGridRef.value?.setSuppressNextDropGlow) {
      slotGridRef.value.setSuppressNextDropGlow(true)
    }
    pendingSlotCopyAction.value = {
      sourceSlotId,
      targetSlotId,
      selectedSlotIds: [...sourceSlotIds]
    }
    showSlotCopyModeModal.value = true
    return
  }

  executeSlotCopy({
    sourceSlotId,
    targetSlotId,
    selectedSlotIds
  }, 'head')
}

// ファイルID入替（ローカル更新のみ、保存時に一括送信）
async function handleFileSwap(slotId1, slotId2) {
  if (!workId.value || !isAuthenticated.value) return

  const slot1 = slots.value.find(s => s.id === slotId1)
  const slot2 = slots.value.find(s => s.id === slotId2)
  
  if (!slot1 || !slot2) return

  // ローカル更新
  const tempFileId = slot1.file_id
  slot1.file_id = slot2.file_id
  slot2.file_id = tempFileId

  // ダーティ管理に追加
  markSlotDirty(slotId1, { file_id: slot2.file_id })
  markSlotDirty(slotId2, { file_id: tempFileId })
}

// ファイルIDコピー（ローカル更新のみ、保存時に一括送信）
async function handleFileCopy(sourceSlotId, targetSlotId) {
  if (!workId.value || !isAuthenticated.value) return

  const sourceSlot = slots.value.find(s => s.id === sourceSlotId)
  const targetSlot = slots.value.find(s => s.id === targetSlotId)
  
  if (!sourceSlot || !targetSlot || !sourceSlot.file_id) return

  // ローカル更新
  targetSlot.file_id = sourceSlot.file_id

  // ダーティ管理に追加
  markSlotDirty(targetSlotId, { file_id: sourceSlot.file_id })
}

const currentModalNavIndex = computed(() => modalNavCursorIndex.value)

const canNavigateModalPrev = computed(() => currentModalNavIndex.value > 0)
const canNavigateModalNext = computed(() => {
  const ix = currentModalNavIndex.value
  return ix >= 0 && ix + 1 < modalNavFileIds.value.length
})

function normalizeFileClickPayload(payload) {
  if (payload?.file) {
    return {
      file: payload.file,
      source: payload.source,
      navFileIds: payload.navFileIds,
      slotId: payload.slotId
    }
  }
  return { file: payload, source: undefined, navFileIds: undefined, slotId: undefined }
}

function getSlotPanelModalNavEntries() {
  if (slotBeforeAfterCompareActive.value) {
    const entries = []
    for (const row of beforeAfterCompareRows.value || []) {
      const sid = String(row.id)
      const beforeId = row?.beforeFileId
      const afterId = beforeAfterCompareAfterFileByRowId.value?.[sid]
      if (beforeId != null && String(beforeId).trim() !== '') {
        entries.push({ fileId: String(beforeId), slotId: sid })
      }
      if (afterId != null && String(afterId).trim() !== '') {
        entries.push({ fileId: String(afterId), slotId: `${sid}:after` })
      }
    }
    return entries
  }
  const entries = []
  for (const slot of gridSlotsForView.value || []) {
    const fid = slot?.file_id
    if (fid != null && String(fid).trim() !== '') {
      entries.push({ fileId: String(fid), slotId: String(slot.id) })
    }
  }
  return entries
}

function getSlotPanelModalNavFileIds() {
  return getSlotPanelModalNavEntries().map((e) => e.fileId)
}

function resolveModalNavIds(file, context = {}) {
  if (Array.isArray(context.navFileIds) && context.navFileIds.length > 0) {
    return context.navFileIds.map((id) => String(id))
  }
  if (context.source === 'slot') {
    return getSlotPanelModalNavFileIds()
  }
  return file?.id != null ? [String(file.id)] : []
}

function resolveModalNavStartIndex(file, context = {}) {
  if (context.source === 'slot' && context.slotId != null) {
    const ix = getSlotPanelModalNavEntries().findIndex(
      (e) => String(e.slotId) === String(context.slotId)
    )
    if (ix >= 0) return ix
  }
  const ids = resolveModalNavIds(file, context)
  return ids.findIndex((id) => String(id) === String(file?.id))
}

async function openFileInModal(file, navFileIds = null, startIndex = null) {
  if (!file) return
  if (Array.isArray(navFileIds)) {
    modalNavFileIds.value = navFileIds.map((id) => String(id))
  }
  if (Number.isInteger(startIndex) && startIndex >= 0) {
    modalNavCursorIndex.value = startIndex
  } else {
    modalNavCursorIndex.value = modalNavFileIds.value.findIndex(
      (x) => String(x) === String(file.id)
    )
  }
  const targetId = String(file.id)
  selectedFileForModal.value = {
    ...file,
    fullImageUrl: null,
    isLoading: true
  }

  try {
    // パブリックURLを直接使用（ブラウザキャッシュに任せる）
    const publicUrl = supabaseService.getPublicUrlFromFileInfo(file, false)
    if (!publicUrl) {
      throw new Error(`Failed to generate public URL for ${file.id}`)
    }
    
    if (selectedFileForModal.value && String(selectedFileForModal.value.id) === targetId) {
      selectedFileForModal.value.fullImageUrl = publicUrl
      selectedFileForModal.value.isLoading = false
    }
  } catch (err) {
    if (selectedFileForModal.value && String(selectedFileForModal.value.id) === targetId) {
      selectedFileForModal.value.isLoading = false
    }
    error.value = '画像の読み込みに失敗しました'
  }
}

function getFileAssignmentEntries(fileId) {
  const fid = String(fileId ?? '')
  if (!fid) return []

  const entries = []
  if (slotBeforeAfterCompareActive.value) {
    for (const row of beforeAfterCompareRows.value || []) {
      const sid = String(row.id)
      const beforeId = row?.beforeFileId != null ? String(row.beforeFileId) : ''
      const afterRaw = beforeAfterCompareAfterFileByRowId.value?.[sid]
      const afterId = afterRaw != null ? String(afterRaw) : ''
      if (beforeId === fid || afterId === fid) {
        entries.push({ slotId: sid })
      }
    }
  } else {
    const prepared = prepareSlotsForDisplay(slots.value || [])
    for (const slot of prepared) {
      if (slot.file_id != null && String(slot.file_id) === fid) {
        entries.push({ slotId: String(slot.id) })
      }
    }
  }

  return entries.slice(0, 5).map((entry, index) => ({
    slotId: entry.slotId,
    label: index + 1
  }))
}

const modalAssignmentEntries = computed(() => {
