function applySlotFieldsWithoutUndo(slotId, updates) {
  const slotIndex = slots.value.findIndex((s) => s.id === slotId)
  if (slotIndex === -1) return null

  const oldValues = {}
  for (const key of Object.keys(updates)) {
    oldValues[key] = slots.value[slotIndex][key]
  }

  slots.value[slotIndex] = {
    ...slots.value[slotIndex],
    ...updates
  }

  const existingChanges = slotsDirty.value.get(slotId) || {}
  slotsDirty.value.set(slotId, {
    ...existingChanges,
    ...updates
  })

  return oldValues
}

async function handleNoteClipboardAction({ slotId, action, note }) {
  const slot = slots.value.find((s) => s.id === slotId)
  if (!slot) return

  const oldNote = slot.note ?? ''

  if (action === 'copy') {
    try {
      await navigator.clipboard.writeText(oldNote)
    } catch (err) {
      console.error('備考コピーに失敗しました:', err)
    }
    return
  }

  let newNote = null

  if (action === 'cut') {
    try {
      await navigator.clipboard.writeText(oldNote)
    } catch (err) {
      console.error('備考切り取りに失敗しました:', err)
    }
    newNote = ''
  } else if (action === 'overwrite') {
    let clipboardText = ''
    try {
      clipboardText = await navigator.clipboard.readText()
    } catch (err) {
      console.error('クリップボード読み取りに失敗しました:', err)
    }
    newNote = clipboardText ?? ''
  } else {
    return
  }

  skipSlotsUndoHistory = true
  try {
    applySlotFieldsWithoutUndo(slotId, { note: newNote })
  } finally {
    skipSlotsUndoHistory = false
  }

  addToSlotsUndoHistory('slot_update', {
    slotId,
    updates: { note: newNote },
    oldValues: { note: oldNote }
  })
}

function handleSlotNoteEditRequest(targetSlotId) {
