async function handleInsertTemplateBelowSlot({ targetSlotId, templateId }) {
  if (!workId.value || !targetSlotId || !templateId) return

  if (!isAuthenticated.value) {
    error.value = 'ログインが必要です'
    return
  }

  error.value = null
  slotTemplateInserting.value = true

  try {
    const result = await supabaseService.getTemplateItems(templateId)
    const templateItems = result.details || []
    if (templateItems.length === 0) {
      error.value = 'テンプレートにアイテムがありません'
      return
    }

    const allSlots = [...slots.value].sort((a, b) => a.sort_index - b.sort_index)
    const currentSlot = allSlots.find((s) => s.id === targetSlotId)
    if (!currentSlot) {
      error.value = '挿入先のスロットが見つかりません'
      return
    }

    const currentIndex = allSlots.findIndex((s) => s.id === targetSlotId)
    const nextSlot = allSlots[currentIndex + 1] || null
    const A = currentSlot.sort_index
    const B = nextSlot ? nextSlot.sort_index : null
    const insertCount = templateItems.length

    const newSlots = []
    const baseTs = Date.now()

    for (let i = 0; i < insertCount; i++) {
      const item = templateItems[i]
      let sortIndex
      if (B === null) {
        sortIndex = A + 1000000 * (i + 1)
      } else {
        const X = Math.floor(B - A)
        const interval = Math.floor(X / (insertCount + 1))
        sortIndex = A + interval * (i + 1)
      }

      const tempId = `temp_slot_${baseTs}_${i}`
      const newSlot = {
        id: tempId,
        work_id: workId.value,
        sort_index: sortIndex,
        caption: item.caption || null,
        note: item.note || null,
        work_phase_id: item.work_phase_id || null,
        file_id: null,
        break_before: false,
        deleted_at: null,
        updated_at: new Date().toISOString()
      }
      newSlots.push(newSlot)

      slotsDirty.value.set(tempId, {
        work_id: workId.value,
        file_id: null,
        sort_index: sortIndex,
        break_before: false,
        caption: item.caption || null,
        note: item.note || null,
        work_phase_id: item.work_phase_id || null,
        _isNew: true
      })
    }

    slots.value = [...allSlots, ...newSlots].sort((a, b) => a.sort_index - b.sort_index)

    const insertedSlotIds = newSlots.map((s) => s.id)
    checkAndRebalanceIfNeeded(insertedSlotIds)

    addToSlotsUndoHistory('slots_insert', {
      insertedSlots: newSlots.map((slot) => ({
        id: slot.id,
        data: { ...slot }
      }))
    })

    const firstId = newSlots[0]?.id
    if (firstId) {
      slotGridRef.value?.ensurePageExpandedForSlot?.(firstId)
      await nextTick()
      await nextTick()
      requestAnimationFrame(() => {
        slotGridRef.value?.scrollToSlot?.(firstId, { behavior: 'auto' })
        slotGridRef.value?.triggerMoveGlow?.(insertedSlotIds)
      })
    }
  } catch (err) {
    error.value = `テンプレートの挿入に失敗しました: ${err.message}`
    console.error('[InsertTemplateBelowSlot] Error:', err)
  } finally {
    slotTemplateInserting.value = false
  }
}

