async function navigateFileModal(delta) {
  const ix = modalNavCursorIndex.value
  const nextIx = ix + delta
  if (nextIx < 0 || nextIx >= modalNavFileIds.value.length) return
  const nextId = modalNavFileIds.value[nextIx]
  if (nextId == null) return
  const nextFile = files.value.find((f) => String(f.id) === String(nextId))
  if (!nextFile) return
