async function handleGeneratePDF(initialPdfWindow = null) {
  let pdfWindow = initialPdfWindow
  const abortPdfTab = () => closePdfTab(pdfWindow)

  if (!workId.value) {
    abortPdfTab()
    error.value = 'Work IDを入力してください'
    return
  }
  
  // 未保存の変更がある場合は警告
  if (hasUnsavedChanges.value) {
    await dialogAlert('未保存の変更があります。\n先に保存ボタンを押してください。', { title: '中断' })
    abortPdfTab()
    return
  }
  
  pdfGenerating.value = true
  error.value = null
  
  try {
    // display_textを保存
    await saveDisplayText()
    
    // スロットデータをprepareSlotsForDisplayで整形（pageNumber, slotNumberInPageを付与）
    const preparedSlots = prepareSlotsForDisplay(slots.value || [])
    
    // 指示モードONの場合、noteを変換
    const slotsForPDF = preparedSlots.map(slot => {
      if (isInstructionMode.value && slot.note) {
        return {
          ...slot,
          note: convertNoteForPDF(slot.note, slot.slotNumberInPage)
        }
      }
      return slot
    })
    
    const sortedSlots = [...slotsForPDF].sort((a, b) => {
      const pageA = a.pageNumber || 1
      const pageB = b.pageNumber || 1
      if (pageA !== pageB) {
        return pageA - pageB
      }
      return (a.slotNumberInPage || 0) - (b.slotNumberInPage || 0)
    })
    
    // フェーズ名のマップを作成
    const phaseLabelMap = new Map(
      (workPhases.value || []).map(phase => [phase.id, phase.label || phase.name || ''])
    )
    
    // ファイルIDごとの元画像URLを取得
    const imageUrlMap = {}
    const fileIds = [...new Set(sortedSlots.map(slot => slot.file_id).filter(Boolean))]
    if (fileIds.length > 0) {
      await Promise.all(
        fileIds.map(async fileId => {
          try {
            // filesから(正しい変数名)ファイル情報を取得してパブリックURL生成
            const file = files.value.find(f => f.id === fileId)
            if (!file) {
              console.error(`File not found for file_id=${fileId}`)
              return
            }
            const url = supabaseService.getPublicUrlFromFileInfo(file, false)
            if (url) {
              imageUrlMap[fileId] = url
            }
          } catch (err) {
            console.error(`Failed to get image URL for file_id=${fileId}:`, err)
          }
        })
      )
    }
    
    const values = [{ page: 0 }] // 表紙
    
    // order_yearから2018を引いて左0埋め2桁に変換してslice_order_yearとして追加
    if (workDataForPDF.value?.order_year) {
      const orderYear = Number(workDataForPDF.value.order_year)
      const sliceOrderYear = String(orderYear - 2018).padStart(2, '0')
      values[0].slice_order_year = sliceOrderYear
    }
    
    // ディスプレイテキストを3行に分割して表紙に追加（下から順番に割り当て）
    if (repairItemInput.value) {
      const lines = repairItemInput.value.split(/\r?\n/).filter(line => line.trim().length > 0)
      
      if (lines.length === 1) {
        // 1行の場合: 1行目 → displaytext1
        values[0].displaytext1 = lines[0].trim()
        values[0].displaytext2 = ''
        values[0].displaytext3 = ''
      } else if (lines.length === 2) {
        // 2行の場合: 1行目 → displaytext2, 2行目 → displaytext1
        values[0].displaytext1 = lines[1].trim()
        values[0].displaytext2 = lines[0].trim()
        values[0].displaytext3 = ''
      } else if (lines.length >= 3) {
        // 3行以上の場合: 1行目 → displaytext3, 2行目 → displaytext2, 3行目 → displaytext1
        values[0].displaytext1 = lines[2].trim()
        values[0].displaytext2 = lines[1].trim()
        values[0].displaytext3 = lines[0].trim()
      }
    }
    
    const pageValueMap = new Map()
    let maxPhysicalPageNumber = 0
    
    const getPageValues = (pageNumber) => {
      if (!pageValueMap.has(pageNumber)) {
        pageValueMap.set(pageNumber, { page: pageNumber })
      }
      return pageValueMap.get(pageNumber)
    }
    
    const splitNotes = (text) => {
      if (!text) return []
      return text.split(/\r?\n/).map((line) => line.trim())
    }

    // ページに「実データ（スロット由来）」がある最終物理ページ番号を返す
    // - page フィールド以外に、空文字でない値が1つでもあれば「データあり」とみなす
    const detectLastContentPhysicalPage = (map) => {
      let last = 0
      for (const [pageNum, v] of map.entries()) {
        if (!pageNum || pageNum <= 0 || !v) continue
        const hasContent = Object.entries(v).some(([k, val]) => {
          if (k === 'page') return false
          if (val === null || val === undefined) return false
          return String(val).trim().length > 0
        })
        if (hasContent) last = Math.max(last, pageNum)
      }
      return last
    }

    // 表紙込みで総ページ数を偶数にそろえるための pageCount 補正
    // - 表紙は常に1枚なので、(1 + pageCount) が偶数になるように調整する
    const normalizePageCountForDuplex = (pageCount) => {
      const n = Math.max(Number(pageCount) || 1, 1)
      return ((1 + n) % 2 === 0) ? n : (n + 1)
    }
    
    // 各UIページ番号ごとのスロット数を集計
    const slotsPerUIPage = new Map()
    for (const slot of sortedSlots) {
      const uiPageNumber = slot.pageNumber || 1
      slotsPerUIPage.set(uiPageNumber, (slotsPerUIPage.get(uiPageNumber) || 0) + 1)
    }
    
    // 各UIページ番号の開始物理ページ番号を計算
    const uiPageStartPhysicalPage = new Map()
    let currentPhysicalPage = 1 // 表紙の次から開始
    for (const [uiPageNumber, slotCount] of Array.from(slotsPerUIPage.entries()).sort((a, b) => a[0] - b[0])) {
      uiPageStartPhysicalPage.set(uiPageNumber, currentPhysicalPage)
      // 6スロットごとに2ページ（A/B）が作成される
      const physicalPagesNeeded = Math.ceil(slotCount / 6) * 2
      currentPhysicalPage += physicalPagesNeeded
    }
    
    for (const slot of sortedSlots) {
      const uiPageNumber = slot.pageNumber || 1
      const slotNumberInPage = slot.slotNumberInPage || 1
      
      // スロット番号からページ内の位置を計算（1-indexed → 0-indexed）
      const slotIndex = slotNumberInPage - 1 // 0-indexed
      
      // 6スロットごとに2ページ（A/B）に分かれる
      const pageGroupIndex = Math.floor(slotIndex / 6) // 0, 1, 2, ...
      const positionInGroup = slotIndex % 6 // 0-5
      
      // ページA/Bの判定（0-2はA、3-5はB）
      const isLayoutA = positionInGroup < 3
      const blockPosition = (positionInGroup % 3) + 1 // 1, 2, 3
      
      // 物理ページ番号を計算
      // 各UIページ番号の開始物理ページ番号 + そのページ内でのグループインデックス * 2 + レイアウトA/Bのオフセット
      const startPhysicalPage = uiPageStartPhysicalPage.get(uiPageNumber) || 1
      const physicalPageNumber = startPhysicalPage + pageGroupIndex * 2 + (isLayoutA ? 0 : 1)
      
      maxPhysicalPageNumber = Math.max(maxPhysicalPageNumber, physicalPageNumber)
      const pageValues = getPageValues(physicalPageNumber)

      pageValues[`caption${blockPosition}`] = slot.caption || ''
      const phaseLabel = phaseLabelMap.get(slot.work_phase_id)
      if (phaseLabel) {
        pageValues[`phase${blockPosition}`] = phaseLabel
      }
      
      const noteLines = splitNotes(slot.note)
      for (let i = 0; i < Math.min(noteLines.length, 10); i++) {
        const key = `note${blockPosition}-${i + 1}`
        pageValues[key] = noteLines[i]
      }
      
      const imageUrl = slot.file_id ? imageUrlMap[slot.file_id] : null
      if (imageUrl) {
        pageValues[`imgurl${blockPosition}`] = imageUrl
        // ファイルのrotation情報を追加
        const file = files.value.find(f => f.id === slot.file_id)
        const rotation = file?.rotation || 0
        pageValues[`rotation${blockPosition}`] = rotation
      }
    }
    
    const sortedPageNumbers = Array.from(pageValueMap.keys()).sort((a, b) => a - b)
    if (sortedPageNumbers.length === 0) {
      maxPhysicalPageNumber = 1
      values.push({ page: 1 })
    } else {
      for (const pageNum of sortedPageNumbers) {
        values.push(pageValueMap.get(pageNum))
      }
    }
    
    // 末尾の「スロット無しページ」を切り落とし、両面印刷向けに偶数終端へ補正
    // - maxPhysicalPageNumber ではなく、実データが入っている最終ページを基準にする
    let pageCount = detectLastContentPhysicalPage(pageValueMap)
    if (!pageCount) pageCount = Math.max(maxPhysicalPageNumber, 1)
    pageCount = normalizePageCountForDuplex(pageCount)

    // 今日の日付をYYYYMMDD形式で取得
    const today = new Date()
    const dateStr = today.getFullYear() + 
                    String(today.getMonth() + 1).padStart(2, '0') + 
                    String(today.getDate()).padStart(2, '0')

    if (isInspectionMode.value) {
      // 検査モード: applications_codes ['11']、ページ分割、検査_物件名(caption1)-日付.pdf
      const applicationsCodes = ['11']
      // 一番最初のスロット1のキャプションをペイロードの表紙に caption として含める
      const firstSlotCaption = (sortedSlots[0]?.caption ?? '').trim()

      // ファイル名に使えない文字を除去
      const sanitizeFileName = (s) => (s ?? '').replace(/[\s\\/:*?"<>|]+/g, '_').trim() || '無題'

      // pageNumber（break-before で区切られたページ）ごとにグループ化
      const slotsByUIPage = new Map()
    for (const slot of sortedSlots) {
      const p = slot.pageNumber || 1
      if (!slotsByUIPage.has(p)) slotsByUIPage.set(p, [])
      slotsByUIPage.get(p).push(slot)
    }

    const uiPageNumbers = Array.from(slotsByUIPage.keys()).sort((a, b) => a - b)
    const hasMultiplePages = uiPageNumbers.length > 0

    if (!hasMultiplePages) {
      // スロットが0件の場合は表紙のみ1PDF
      values[0].caption = firstSlotCaption
      values[0].title = firstSlotCaption
      const pageCount = Math.max(maxPhysicalPageNumber, 1)
      const layoutData = await supabaseService.getPdfLayout(applicationsCodes, workId.value, pageCount, values)
      const pdfBytes = await generatePDFFromLayout(layoutData, values, getPdfGenerateOptions())
      const captionPart = sanitizeFileName(firstSlotCaption) || ''
      const fileName = `検査1-${sanitizeFileName(workDisplayName.value)}(${captionPart}).pdf`
      const blob = new Blob([pdfBytes], { type: 'application/pdf' })
      openGeneratedPdf(blob, { fileName, pdfWindow })
      pdfWindow = null
      try {
        await supabaseService.deleteExistingPdf(workId.value)
        await supabaseService.uploadPdfFile(workId.value, new File([blob], fileName, { type: 'application/pdf' }))
        await loadPdfFile()
      } catch (uploadErr) {
        console.error('PDFアップロードエラー:', uploadErr)
        error.value = `PDF生成は成功しましたが、サーバーへのアップロードに失敗しました: ${uploadErr.message}`
      }
    } else {
      try {
        await supabaseService.deleteExistingPdf(workId.value)
      } catch (delErr) {
        console.warn('既存PDF削除エラー（続行）:', delErr)
      }

      for (let i = 0; i < uiPageNumbers.length; i++) {
        const uiPageNum = uiPageNumbers[i]
        const pageSlots = slotsByUIPage.get(uiPageNum) || []
        const slotCount = pageSlots.length
        const physicalPagesNeeded = Math.ceil(slotCount / 6) * 2
        // いったん見積もり（後で実データに基づいて補正）
        let pageCount = Math.max(physicalPagesNeeded, 1)

        const pageValueMap = new Map()
        const getPageValues = (pageNumber) => {
          if (!pageValueMap.has(pageNumber)) {
            pageValueMap.set(pageNumber, { page: pageNumber })
          }
          return pageValueMap.get(pageNumber)
        }

        for (const slot of pageSlots) {
          const slotNumberInPage = slot.slotNumberInPage || 1
          const slotIndex = slotNumberInPage - 1
          const pageGroupIndex = Math.floor(slotIndex / 6)
          const positionInGroup = slotIndex % 6
          const isLayoutA = positionInGroup < 3
          const blockPosition = (positionInGroup % 3) + 1
          const physicalPageNumber = 1 + pageGroupIndex * 2 + (isLayoutA ? 0 : 1)
          const pageValues = getPageValues(physicalPageNumber)

          pageValues[`caption${blockPosition}`] = slot.caption || ''
          const phaseLabel = phaseLabelMap.get(slot.work_phase_id)
          if (phaseLabel) pageValues[`phase${blockPosition}`] = phaseLabel
          const noteLines = splitNotes(slot.note)
          for (let j = 0; j < Math.min(noteLines.length, 10); j++) {
            pageValues[`note${blockPosition}-${j + 1}`] = noteLines[j]
          }
          const imageUrl = slot.file_id ? imageUrlMap[slot.file_id] : null
          if (imageUrl) {
            pageValues[`imgurl${blockPosition}`] = imageUrl
            const file = files.value.find(f => f.id === slot.file_id)
            pageValues[`rotation${blockPosition}`] = file?.rotation || 0
          }
        }

        const sortedPhys = Array.from(pageValueMap.keys()).sort((a, b) => a - b)
        const pageValues = [{ page: 0 }]
        const pageTitle = (pageSlots[0]?.caption ?? '').trim()
        pageValues[0].caption = firstSlotCaption
        pageValues[0].title = pageTitle
        if (workDataForPDF.value?.order_year) {
          const orderYear = Number(workDataForPDF.value.order_year)
          pageValues[0].slice_order_year = String(orderYear - 2018).padStart(2, '0')
        }
        if (repairItemInput.value) {
          const lines = repairItemInput.value.split(/\r?\n/).filter(line => line.trim().length > 0)
          if (lines.length === 1) {
            pageValues[0].displaytext1 = lines[0].trim()
            pageValues[0].displaytext2 = ''
            pageValues[0].displaytext3 = ''
          } else if (lines.length === 2) {
            pageValues[0].displaytext1 = lines[1].trim()
            pageValues[0].displaytext2 = lines[0].trim()
            pageValues[0].displaytext3 = ''
          } else if (lines.length >= 3) {
            pageValues[0].displaytext1 = lines[2].trim()
            pageValues[0].displaytext2 = lines[1].trim()
            pageValues[0].displaytext3 = lines[0].trim()
          }
        }
        if (sortedPhys.length === 0) {
          pageValues.push({ page: 1 })
        } else {
          for (const pn of sortedPhys) pageValues.push(pageValueMap.get(pn))
        }

        // 末尾の「スロット無しページ」を切り落とし、表紙込み偶数終端へ補正
        const lastContent = detectLastContentPhysicalPage(pageValueMap) || 1
        pageCount = normalizePageCountForDuplex(lastContent)

        const layoutData = await supabaseService.getPdfLayout(applicationsCodes, workId.value, pageCount, pageValues)
        const pdfBytes = await generatePDFFromLayout(layoutData, pageValues, getPdfGenerateOptions())
        const n = i + 1 // 1-based ページ番号
        const caption1 = (pageSlots[0]?.caption ?? '').trim()
        const captionPart = sanitizeFileName(caption1) || ''
        const fileName = `検査${n}-${sanitizeFileName(workDisplayName.value)}(${captionPart}).pdf`
        const blob = new Blob([pdfBytes], { type: 'application/pdf' })
        openGeneratedPdf(blob, { fileName })

        try {
          await supabaseService.uploadPdfFile(workId.value, new File([blob], fileName, { type: 'application/pdf' }))
        } catch (uploadErr) {
          console.error(`PDFアップロードエラー (${fileName}):`, uploadErr)
          error.value = `PDF生成は成功しましたが、一部アップロードに失敗しました: ${uploadErr.message}`
        }

        if (i < uiPageNumbers.length - 1) {
          await new Promise(r => setTimeout(r, 300))
        }
      }

      await loadPdfFile()
    }
    } else {
      // 通常モード: 1PDF、applications_codes ['1']、物件名-日付.pdf
      const applicationsCodes = ['1']
      const layoutData = await supabaseService.getPdfLayout(applicationsCodes, workId.value, pageCount, values)
      const pdfBytes = await generatePDFFromLayout(layoutData, values, getPdfGenerateOptions())
      const fileName = `${workDisplayName.value}-${dateStr}.pdf`
      const blob = new Blob([pdfBytes], { type: 'application/pdf' })
      openGeneratedPdf(blob, { fileName, pdfWindow })
      pdfWindow = null
      try {
        await supabaseService.deleteExistingPdf(workId.value)
        await supabaseService.uploadPdfFile(workId.value, new File([blob], fileName, { type: 'application/pdf' }))
        await loadPdfFile()
      } catch (uploadErr) {
        console.error('PDFアップロードエラー:', uploadErr)
        error.value = `PDF生成は成功しましたが、サーバーへのアップロードに失敗しました: ${uploadErr.message}`
      }
    }
  } catch (err) {
    console.error('PDF生成エラー:', err)
    error.value = `PDF生成に失敗しました: ${err.message}`
    abortPdfTab()
  } finally {
    pdfGenerating.value = false
  }
}

// 検査モードのページ選択状態に応じて、生成/再UPを切り替え
async function handleGenerateOrReupload() {
  const pdfWindow = openPdfBlankTabForAsyncGenerate()
  try {
    if (isInspectionReuploadMode.value) {
      await handleReuploadInspectionPage(pdfWindow)
      return
    }
    await handleGeneratePDF(pdfWindow)
  } catch (err) {
    closePdfTab(pdfWindow)
    throw err
  }
}

// 検査n のPDFのみ削除してそのページを再生成・再アップロード（検査モード・ページ番号選択時のみ）
async function handleReuploadInspectionPage(initialPdfWindow = null) {
  let pdfWindow = initialPdfWindow
  const abortPdfTab = () => closePdfTab(pdfWindow)

  const n = selectedInspectionPageNumber.value
  if (!workId.value || n == null || !isInspectionMode.value) {
    abortPdfTab()
    return
  }
  if (hasUnsavedChanges.value) {
    await dialogAlert('未保存の変更があります。先に保存ボタンを押して変更を保存してください。', { title: '中断' })
    abortPdfTab()
    return
  }
  pdfGenerating.value = true
  error.value = null
  const sanitizeFileName = (s) => (s ?? '').replace(/[\s\\/:*?"<>|]+/g, '_').trim() || '無題'
  try {
    await saveDisplayText()
    const preparedSlots = prepareSlotsForDisplay(slots.value || [])
    const slotsForPDF = preparedSlots.map(slot => {
      if (isInstructionMode.value && slot.note) {
        return { ...slot, note: convertNoteForPDF(slot.note, slot.slotNumberInPage) }
      }
      return slot
    })
    const sortedSlots = [...slotsForPDF].sort((a, b) => {
      const pageA = a.pageNumber || 1
      const pageB = b.pageNumber || 1
      if (pageA !== pageB) return pageA - pageB
      return (a.slotNumberInPage || 0) - (b.slotNumberInPage || 0)
    })
    const phaseLabelMap = new Map((workPhases.value || []).map(phase => [phase.id, phase.label || phase.name || '']))
    const imageUrlMap = {}
    const fileIds = [...new Set(sortedSlots.map(slot => slot.file_id).filter(Boolean))]
    if (fileIds.length > 0) {
      await Promise.all(
        fileIds.map(async fileId => {
          const file = files.value.find(f => f.id === fileId)
          if (!file) return
          const url = supabaseService.getPublicUrlFromFileInfo(file, false)
          if (url) imageUrlMap[fileId] = url
        })
      )
    }
    const slotsByUIPage = new Map()
    for (const slot of sortedSlots) {
      const p = slot.pageNumber || 1
      if (!slotsByUIPage.has(p)) slotsByUIPage.set(p, [])
      slotsByUIPage.get(p).push(slot)
    }
    const uiPageNumbers = Array.from(slotsByUIPage.keys()).sort((a, b) => a - b)
    const pageIndex = n - 1
    if (pageIndex < 0 || pageIndex >= uiPageNumbers.length) {
      error.value = `ページ ${n} は存在しません`
      return
    }
    const uiPageNum = uiPageNumbers[pageIndex]
    const pageSlots = slotsByUIPage.get(uiPageNum) || []
    const physicalPagesNeeded = Math.ceil(pageSlots.length / 6) * 2
    // いったん見積もり（後で実データに基づいて補正）
    let pageCount = Math.max(physicalPagesNeeded, 1)
    const pageValueMap = new Map()
    const getPageValues = (pageNumber) => {
      if (!pageValueMap.has(pageNumber)) pageValueMap.set(pageNumber, { page: pageNumber })
      return pageValueMap.get(pageNumber)
    }
    const splitNotes = (text) => {
      if (!text) return []
      return text.split(/\r?\n/).map((l) => l.trim())
    }
    for (const slot of pageSlots) {
      const slotNumberInPage = slot.slotNumberInPage || 1
      const slotIndex = slotNumberInPage - 1
      const pageGroupIndex = Math.floor(slotIndex / 6)
      const positionInGroup = slotIndex % 6
      const isLayoutA = positionInGroup < 3
      const blockPosition = (positionInGroup % 3) + 1
      const physicalPageNumber = 1 + pageGroupIndex * 2 + (isLayoutA ? 0 : 1)
      const pageValues = getPageValues(physicalPageNumber)
      pageValues[`caption${blockPosition}`] = slot.caption || ''
      const phaseLabel = phaseLabelMap.get(slot.work_phase_id)
      if (phaseLabel) pageValues[`phase${blockPosition}`] = phaseLabel
      const noteLines = splitNotes(slot.note)
      for (let j = 0; j < Math.min(noteLines.length, 10); j++) pageValues[`note${blockPosition}-${j + 1}`] = noteLines[j]
      const imageUrl = slot.file_id ? imageUrlMap[slot.file_id] : null
      if (imageUrl) {
        pageValues[`imgurl${blockPosition}`] = imageUrl
        const file = files.value.find(f => f.id === slot.file_id)
        pageValues[`rotation${blockPosition}`] = file?.rotation || 0
      }
    }
    const sortedPhys = Array.from(pageValueMap.keys()).sort((a, b) => a - b)
    const pageValues = [{ page: 0 }]
    const firstSlotCaption = (sortedSlots[0]?.caption ?? '').trim()
    const pageTitle = (pageSlots[0]?.caption ?? '').trim()
    pageValues[0].caption = firstSlotCaption
    pageValues[0].title = pageTitle
    if (workDataForPDF.value?.order_year) {
      pageValues[0].slice_order_year = String(Number(workDataForPDF.value.order_year) - 2018).padStart(2, '0')
    }
    if (repairItemInput.value) {
      const lines = repairItemInput.value.split(/\r?\n/).filter(l => l.trim().length > 0)
      if (lines.length === 1) { pageValues[0].displaytext1 = lines[0].trim(); pageValues[0].displaytext2 = ''; pageValues[0].displaytext3 = '' }
      else if (lines.length === 2) { pageValues[0].displaytext1 = lines[1].trim(); pageValues[0].displaytext2 = lines[0].trim(); pageValues[0].displaytext3 = '' }
      else if (lines.length >= 3) { pageValues[0].displaytext1 = lines[2].trim(); pageValues[0].displaytext2 = lines[1].trim(); pageValues[0].displaytext3 = lines[0].trim() }
    }
    if (sortedPhys.length === 0) pageValues.push({ page: 1 })
    else for (const pn of sortedPhys) pageValues.push(pageValueMap.get(pn))

    // 末尾の「スロット無しページ」を切り落とし、表紙込み偶数終端へ補正
    // handleGeneratePDF 内で定義した補助関数を流用（同スコープにある想定）
    const lastContent = (typeof detectLastContentPhysicalPage === 'function')
      ? (detectLastContentPhysicalPage(pageValueMap) || 1)
      : 1
    pageCount = (typeof normalizePageCountForDuplex === 'function')
      ? normalizePageCountForDuplex(lastContent)
      : lastContent

    await supabaseService.deletePdfFileByInspectionNumber(workId.value, n)
    const applicationsCodes = ['11']
    const layoutData = await supabaseService.getPdfLayout(applicationsCodes, workId.value, pageCount, pageValues)
    const pdfBytes = await generatePDFFromLayout(layoutData, pageValues, getPdfGenerateOptions())
    const caption1 = (pageSlots[0]?.caption ?? '').trim()
    const captionPart = sanitizeFileName(caption1) || ''
    const fileName = `検査${n}-${sanitizeFileName(workDisplayName.value)}(${captionPart}).pdf`
    const blob = new Blob([pdfBytes], { type: 'application/pdf' })
    openGeneratedPdf(blob, { fileName, pdfWindow })
    pdfWindow = null
    await supabaseService.uploadPdfFile(workId.value, new File([blob], fileName, { type: 'application/pdf' }))
    await loadPdfFile()
  } catch (err) {
    console.error('検査ページ再アップロードエラー:', err)
    error.value = `再アップロードに失敗しました: ${err.message}`
    abortPdfTab()
  } finally {
    pdfGenerating.value = false
  }
}

// display_text変更時の処理（blur時）
async function handleDisplayTextChange() {
  if (!workId.value) {
    return
  }
  
  // 同期キューに追加（スタックにためて送信）
  try {
    await syncQueueService.addToQueue(
      workId.value,
      syncQueueService.OperationType.UPDATE_DISPLAY_TEXT,
      {
        display_text: repairItemInput.value || null
      },
      {
        priority: syncQueueService.QueuePriority.LOW
      }
    )
    console.log('✅ Display text update queued')
  } catch (err) {
    console.error('Failed to queue display_text update:', err)
    // フォールバック: 直接送信
    await saveDisplayText()
  }
}

