// 統合更新ボタンのハンドラー
async function handleReload() {
  // 同期キューまたはアップロードキューがある場合は確認モーダルを表示
  const queueCount = syncQueueCount.value || 0
  const uploadCount = uploadQueueCount.value || 0
  const totalCount = queueCount + uploadCount
  
  if (totalCount > 0) {
    showSyncQueueConfirmModal.value = true
    return
  }
  
  // 処理待ちがない場合は通常の更新処理
  await performReload()
}

// 実際の更新処理を実行
async function performReload() {
  if (activeTab.value === 'works') {
    reloadWorks()
  } else if (activeTab.value === 'edit') {
    // 未保存の変更がある場合は警告
    if (hasUnsavedChanges.value) {
      if (!await dialogConfirm('未保存の変更があります。\n更新すると変更が失われます。\n続けますか？', { title: '確認' })) {
        return
      }
      // ダーティフラグをクリア
      slotsDirty.value.clear()
      filesDirty.value.clear()
      categoriesDirty.value.clear()
      deletedSlots.value.clear()
      deletedFiles.value.clear()
      deletedCategories.value.clear()
            
      // 🆕 UNDO履歴もクリア
      slotsUndoHistory.value = []
      saveSlotsUndoToIndexedDB()
    }
    // 編集タブの更新ボタンはサーバーから強制的に取得
    loadData(true, false, true)
  } else if (activeTab.value === 'billingTemplates') {
    billingTemplatesTabRef.value?.loadTemplates?.()
  } else if (activeTab.value === 'templates') {
    reloadTemplateEditor()
  // } else if (activeTab.value === 'estimate') {
  //   // 見積スロットとプライスリストを両方読み込み（強制リロード）（削除済み）
  //   if (estimateEditorRef.value?.loadEstimateSlots) {
  //     estimateEditorRef.value.loadEstimateSlots(true)
  //   }
  //   if (estimateEditorRef.value?.loadPriceListItems) {
  //     estimateEditorRef.value.loadPriceListItems()
  //   }
  } else if (activeTab.value === 'cloudStorage') {
    // クラウドストレージタブの更新: list を再取得して再レンダリング
    cloudStorageRef.value?.loadList?.()
  } else if (activeTab.value === 'grid') {
    // グリッドタブの更新（テンプレートは IndexedDB / get_room_labels 経路）
    reloadEstimateGrid()
  } else if (activeTab.value === 'schedule') {
    scheduleGridLoading.value = true
    try {
      await scheduleGridEditorRef.value?.reloadList?.()
    } finally {
      scheduleGridLoading.value = false
    }
  } else if (activeTab.value === 'manual') {
    await manualSearchTabRef.value?.reloadDocuments?.()
  }
}

// グリッドタブの更新処理
async function reloadEstimateGrid() {
  if (!workId.value) {
    console.warn('⚠️ [Reload] No workId available for grid reload')
    return
  }
  
  try {
    gridLoading.value = true
    
    // グリッド編集の未保存変更をクリア（IndexedDBも削除）
    if (estimateGridEditorRef.value && estimateGridEditorRef.value.clearUnsavedChanges) {
      await estimateGridEditorRef.value.clearUnsavedChanges()
    }
    
    // IndexedDBからdisplay_textを再取得してrepairItemInputに設定
    try {
      const cachedWork = await indexedDBService.works.get(workId.value)
      if (cachedWork) {
        repairItemInput.value = cachedWork.display_text || ''
      } else {
        repairItemInput.value = ''
      }
    } catch (err) {
      console.warn('⚠️ [reloadEstimateGrid] Failed to get display_text from IndexedDB:', err)
      repairItemInput.value = ''
    }
    
    // サーバーから最新データを再取得してレンダリング
    if (estimateGridEditorRef.value && estimateGridEditorRef.value.reloadFromServer) {
      await estimateGridEditorRef.value.reloadFromServer()
    }
    
  } catch (err) {
    console.error('❌ [Reload] Failed to reload estimate grid:', err)
    error.value = `見積グリッドの更新に失敗しました: ${err.message}`
  } finally {
    gridLoading.value = false
  }
}

