}

// 確認モーダルで「取消」を選択（同期キューとアップロードキューをクリアして更新）
async function handleSyncQueueConfirmCancel() {
  try {
    // 同期キューをクリア
    if (syncQueueCount.value > 0) {
      await syncQueueService.clearQueue()
      await updateSyncQueueCount()
    }
    
    // アップロードキューをクリア
    if (uploadQueueCount.value > 0) {
      uploadQueue.clear()
      uploadQueueCount.value = uploadQueue.getPendingCount()
    }
    
    // 更新処理を実行
    await performReload()
  } catch (error) {
    console.error('❌ [Reload] Error clearing queues:', error)
    error.value = `キューのクリアに失敗しました: ${error.message}`
  }
}

