// 同期キュー数を更新
async function updateSyncQueueCount() {
  try {
    const { indexedDBService } = await import('./utils/indexedDB.js')
    
    // すべてのキューアイテムを取得してステータスごとにカウント
    const allQueue = await indexedDBService.sync_queue.toArray()
    const statusCounts = {
      pending: 0,
      processing: 0,
      completed: 0,
      failed: 0
    }
    allQueue.forEach(item => {
      if (statusCounts[item.status] !== undefined) {
        statusCounts[item.status]++
      }
    })
    
    // pending と failed のみをカウント（バッジ表示用）
    const queue = await indexedDBService.sync_queue
      .where('status')
      .anyOf(['pending', 'failed'])
      .toArray()
    syncQueueCount.value = queue.length
    
    // 完了済みアイテムも表示
    if (statusCounts.completed > 0) {
      const completedItems = await indexedDBService.sync_queue
        .where('status')
        .equals('completed')
        .toArray()
    }
  } catch (error) {
    console.error('Failed to get sync queue count:', error)
  }
}

// 同期キュー変更イベントのリスナー
let unsubscribeQueueChange = null
let unsubscribeUploadQueueChange = null
let unsubscribeTemplateRefresh = null
let templateWatchRefreshHandler = null

onMounted(async () => {
  // 初回取得
  await updateSyncQueueCount()
  
  // アップロードキューの初期カウントも取得
  uploadQueueCount.value = uploadQueue.getPendingCount()
  
  // syncQueueServiceのイベントをリッスン
  const { syncQueueService } = await import('./utils/syncQueue.js')
  unsubscribeQueueChange = syncQueueService.onQueueChange(() => {
    updateSyncQueueCount()
  })
  
  // テンプレート更新イベントをリッスン
  unsubscribeTemplateRefresh = syncQueueService.onTemplateRefresh(() => {
    reloadSlotTemplates()
  })

  templateWatchRefreshHandler = (event) => {
    const changed = event?.detail?.changed || []
    if (changed.includes('contractors')) {
      reloadContractors()
    }
    if (changed.includes('report_slot_templates')) {
      reloadSlotTemplates()
    }
    if (changed.includes('estimate_slot_templates')) {
      reloadTemplateEditor()
    }
  }
  window.addEventListener('template-watch-refreshed', templateWatchRefreshHandler)
  
  // uploadQueueのイベントもリッスン
  unsubscribeUploadQueueChange = uploadQueue.onQueueChange(() => {
    // アップロードキューの未処理数を更新
    uploadQueueCount.value = uploadQueue.getPendingCount()
  })
  
  // 初回ロード時にテンプレートデータを強制的に更新（user_profile_idが含まれていない古いデータをクリア）
  if (isAuthenticated.value && userProfileId.value) {
    try {
      await syncQueueService.refreshReportSlotTemplates()
    } catch (err) {
      console.error('❌ [App] Failed to refresh templates on mount:', err)
    }
  }
})

// コンポーネント破棄時にスクロールを復元とイベントリスナーのクリーンアップ
onUnmounted(() => {
  document.body.style.overflow = ''
  if (errorDismissTimer) {
    clearTimeout(errorDismissTimer)
    errorDismissTimer = null
  }
  if (visibilityChangeHandler) {
    document.removeEventListener('visibilitychange', visibilityChangeHandler)
  }
  if (unsubscribeQueueChange) {
    unsubscribeQueueChange()
  }
  if (unsubscribeUploadQueueChange) {
    unsubscribeUploadQueueChange()
  }
  if (unsubscribeTemplateRefresh) {
    unsubscribeTemplateRefresh()
  }
  if (templateWatchRefreshHandler) {
    window.removeEventListener('template-watch-refreshed', templateWatchRefreshHandler)
  }
})
