export const MANUAL_FIGURE_IMG_SELECTOR = 'img.doc-figure-img[data-src]'

export function loadManualFigureImage(img) {
  if (!(img instanceof HTMLImageElement)) return false
  const src = img.dataset.src?.trim()
  if (!src) return false

  img.src = src
  img.removeAttribute('data-src')
  img.decoding = 'async'
  img.classList.remove('doc-figure-img--pending')
  img.addEventListener(
    'error',
    () => {
      img.classList.add('doc-figure-img--error')
    },
    { once: true },
  )
  return true
}

function collectFigureImagesNear(root, targetEl, before, after) {
  const targetBlock = targetEl.closest?.('.doc-block') || targetEl
  const blocks = Array.from(root.querySelectorAll('.doc-block'))
  const idx = blocks.indexOf(targetBlock)
  if (idx < 0) {
    const article = targetEl.closest?.('.doc-article')
    if (article) {
      return Array.from(article.querySelectorAll(MANUAL_FIGURE_IMG_SELECTOR))
    }
    return []
  }

  const imgs = []
  const start = Math.max(0, idx - before)
  const end = Math.min(blocks.length, idx + after + 1)
  for (let i = start; i < end; i += 1) {
    blocks[i].querySelectorAll(MANUAL_FIGURE_IMG_SELECTOR).forEach((img) => imgs.push(img))
  }
  return imgs
}

/**
 * @param {HTMLElement|null} root html-viewport
 * @param {{ rootMargin?: string, threshold?: number }} [options]
 */
export function setupManualFigureLazyLoad(root, options = {}) {
  const { rootMargin = '200px 0px', threshold = 0 } = options

  if (!root) {
    return {
      disconnect() {},
      preloadNear() {},
      preloadInElement() {},
    }
  }

  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue
        const img = entry.target
        if (loadManualFigureImage(img)) {
          observer.unobserve(img)
        }
      }
    },
    { root, rootMargin, threshold },
  )

  root.querySelectorAll(MANUAL_FIGURE_IMG_SELECTOR).forEach((img) => {
    observer.observe(img)
  })

  return {
    disconnect() {
      observer.disconnect()
    },
    preloadNear(targetEl, { before = 2, after = 2 } = {}) {
      if (!targetEl || !root.contains(targetEl)) return
      collectFigureImagesNear(root, targetEl, before, after).forEach((img) => {
        if (loadManualFigureImage(img)) {
          observer.unobserve(img)
        }
      })
    },
    preloadInElement(el) {
      if (!el) return
      el.querySelectorAll(MANUAL_FIGURE_IMG_SELECTOR).forEach((img) => {
        if (loadManualFigureImage(img)) {
          observer.unobserve(img)
        }
      })
    },
  }
}
