/**
 * アップロード系全画面オーバーレイの文言（半角括弧・三点リーダーなし）
 */

export const SLOT_UPLOAD_PHASE = {
  FOLDER: 'folder',
  COMMIT: 'commit',
  EMBEDDING: 'embedding'
}

export const FOLDER_CREATING_OVERLAY_LABEL = 'フォルダ作成中'

export function formatUploadProgressMessage(label, current, total) {
  const t = Number(total) || 0
  const c = Math.min(Math.max(Number(current) || 0, 0), t > 0 ? t : Number(current) || 0)
  if (t > 0) return `${label} (${c}/${t})`
  return label
}

/** コミット（疑似反映）フェーズ */
export function formatReflectProgressMessage(total) {
  const t = Math.max(Number(total) || 0, 1)
  return `画像を反映中 (${t}/${t})`
}

/** 特徴値ベクトル生成フェーズ */
export function formatFeatureGenerateProgressMessage(current, total) {
  const t = Number(total) || 0
  const c = Math.min(Math.max(Number(current) || 0, 0), t > 0 ? t : Number(current) || 0)
  if (t > 0) return `特徴値を生成中 (${c}/${t})`
  return '特徴値を生成中'
}

/** スロット編集タブ uploadProgress 用 */
export function formatSlotUploadOverlayMessage(progress) {
  if (!progress) return 'アップロード中'
  if (
    progress.phase === SLOT_UPLOAD_PHASE.FOLDER ||
    progress.fileName === FOLDER_CREATING_OVERLAY_LABEL ||
    progress.fileName === 'フォルダ作成中...'
  ) {
    return FOLDER_CREATING_OVERLAY_LABEL
  }
  if (progress.phase === SLOT_UPLOAD_PHASE.COMMIT) {
    return formatReflectProgressMessage(progress.total)
  }
  if (progress.phase === SLOT_UPLOAD_PHASE.EMBEDDING) {
    return formatFeatureGenerateProgressMessage(progress.current, progress.total)
  }
  if (progress.active || (Number(progress.total) || 0) > 0) {
    return formatUploadProgressMessage('アップロード中', progress.current, progress.total)
  }
  return 'アップロード中'
}

/** クラウドストレージ UP 後フェーズ用 */
export function formatCloudUploadPostPhaseMessage(phase, current, total) {
  if (phase === SLOT_UPLOAD_PHASE.COMMIT) {
    return formatReflectProgressMessage(total)
  }
  if (phase === SLOT_UPLOAD_PHASE.EMBEDDING) {
    return formatFeatureGenerateProgressMessage(current, total)
  }
  return ''
}
