import { isHeicLikeFile } from './imageResize'

const FORBIDDEN_FOLDER_NAME_CHARS = /[\\/:*?"<>|]/

const SYSTEM_FILE_NAMES = new Set([
  '.ds_store',
  'thumbs.db',
  'desktop.ini'
])

const SLOT_ALLOWED_IMAGE_EXTENSIONS = new Set([
  'jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'heic', 'heif'
])

const SLOT_DISALLOWED_IMAGE_EXTENSIONS = new Set([
  'svg', 'ico', 'tiff', 'tif', 'avif', 'psd', 'ai', 'eps', 'raw', 'cr2', 'nef', 'orf', 'sr2'
])

export const FOLDER_DROP_MESSAGES = {
  MULTIPLE_FOLDERS: 'フォルダは1つだけドロップできます。',
  MIXED_FOLDER_FILES: 'フォルダとファイルを同時にドロップすることはできません。',
  NESTED_FOLDER: 'フォルダ内にさらにフォルダが含まれています。直下のファイルのみドロップできます。',
  NO_UPLOADABLE_FILES: 'アップロードできるファイルがありません。',
  CATEGORY_ZONE: 'フォルダはカテゴリー上にドロップできません。未分類エリアにドロップしてください。',
  SLOT: 'スロットにフォルダはドロップできません。',
  WORK_SCOPE_ONLY: '工事情報にしかフォルダドロップできません。',
  DUPLICATE_FOLDERS: (name) => `「${name}」と同じ名前のフォルダが複数あります。`,
}

/** @typedef {'files'|'folder'|'error'} ExternalDropKind */

/**
 * @param {DataTransfer|null|undefined} dataTransfer
 * @returns {{ dropKind: ExternalDropKind, entry?: FileSystemDirectoryEntry, message?: string }}
 */
export function inspectExternalDrop(dataTransfer) {
  const items = dataTransfer?.items
  if (!items || items.length === 0) {
    return { dropKind: 'files' }
  }

  /** @type {Array<FileSystemEntry>} */
  const entries = []
  for (let i = 0; i < items.length; i += 1) {
    const item = items[i]
    if (item.kind !== 'file') continue
    const entry = typeof item.webkitGetAsEntry === 'function'
      ? item.webkitGetAsEntry()
      : typeof item.getAsEntry === 'function'
        ? item.getAsEntry()
        : null
    if (entry) entries.push(entry)
  }

  if (entries.length === 0) {
    return { dropKind: 'files' }
  }

  const dirs = entries.filter((e) => e.isDirectory)
  const plainFiles = entries.filter((e) => e.isFile)

  if (dirs.length > 1 || (dirs.length > 0 && plainFiles.length > 0)) {
    return {
      dropKind: 'error',
      message: dirs.length > 1 ? FOLDER_DROP_MESSAGES.MULTIPLE_FOLDERS : FOLDER_DROP_MESSAGES.MIXED_FOLDER_FILES
    }
  }

  if (dirs.length === 1) {
    return { dropKind: 'folder', entry: /** @type {FileSystemDirectoryEntry} */ (dirs[0]) }
  }

  return { dropKind: 'files' }
}

export function isSystemOrHiddenFileName(name) {
  const base = String(name ?? '').trim()
  if (!base) return true
  if (base.startsWith('.')) return true
  return SYSTEM_FILE_NAMES.has(base.toLowerCase())
}

/**
 * @param {string} rawName
 * @returns {{ ok: true, name: string } | { ok: false, message: string }}
 */
export function validateDroppedFolderName(rawName) {
  const name = String(rawName ?? '').trim()
  if (!name) {
    return { ok: false, message: 'フォルダ名が空です。' }
  }
  if (FORBIDDEN_FOLDER_NAME_CHARS.test(name)) {
    return { ok: false, message: 'フォルダ名に使用できない文字が含まれています（\\ / : * ? " < > |）。' }
  }
  return { ok: true, name }
}

function readDirectoryEntries(dirReader) {
  return new Promise((resolve, reject) => {
    /** @type {FileSystemEntry[]} */
    const batch = []
    const readBatch = () => {
      dirReader.readEntries((entries) => {
        if (!entries.length) {
          resolve(batch)
          return
        }
        batch.push(...entries)
        readBatch()
      }, reject)
    }
    readBatch()
  })
}

function fileEntryToFile(fileEntry) {
  return new Promise((resolve, reject) => {
    fileEntry.file(resolve, reject)
  })
}

/**
 * @param {FileSystemDirectoryEntry} dirEntry
 * @returns {Promise<{ files: File[], error?: string }>}
 */
export async function readFlatFolderFiles(dirEntry) {
  const dirReader = dirEntry.createReader()
  const entries = await readDirectoryEntries(dirReader)

  /** @type {File[]} */
  const files = []
  for (const entry of entries) {
    if (entry.isDirectory) {
      return { files: [], error: FOLDER_DROP_MESSAGES.NESTED_FOLDER }
    }
    if (!entry.isFile) continue
    if (isSystemOrHiddenFileName(entry.name)) continue
    files.push(await fileEntryToFile(/** @type {FileSystemFileEntry} */ (entry)))
  }

  return { files }
}

/**
 * @param {Array<{ id: string, name?: string, label?: string, parent_id?: string|null }>} folders
 * @param {string} folderName
 * @param {string|null|undefined} parentId
 */
export function findFoldersByNameCaseInsensitive(folders, folderName, parentId) {
  const target = String(folderName ?? '').trim().toLowerCase()
  const normParent = parentId ?? null
  return (folders || []).filter((folder) => {
    const label = String(folder.label ?? folder.name ?? '').trim().toLowerCase()
    const folderParent = folder.parent_id ?? null
    return label === target && folderParent === normParent
  })
}

/**
 * @param {object} params
 * @param {Array<{ id: string, name?: string, label?: string, parent_id?: string|null }>} params.folders
 * @param {string} params.folderName
 * @param {string|null|undefined} params.parentId
 * @param {(name: string, parentId: string|null) => Promise<{ id: string }>} params.createFolder
 */
export async function resolveFolderTargetId({ folders, folderName, parentId, createFolder }) {
  const validation = validateDroppedFolderName(folderName)
  if (!validation.ok) {
    throw new Error(validation.message)
  }

  const matches = findFoldersByNameCaseInsensitive(folders, validation.name, parentId)
  if (matches.length > 1) {
    throw new Error(FOLDER_DROP_MESSAGES.DUPLICATE_FOLDERS(validation.name))
  }
  if (matches.length === 1) {
    return matches[0].id
  }

  const created = await createFolder(validation.name, parentId ?? null)
  if (!created?.id) {
    throw new Error('フォルダの作成に失敗しました。')
  }
  return created.id
}

/**
 * @param {File[]} files
 * @returns {{ valid: File[], excluded: Array<{ name: string, reason: string }> }}
 */
export function partitionSlotImageUploadFiles(files) {
  /** @type {File[]} */
  const valid = []
  /** @type {Array<{ name: string, reason: string }>} */
  const excluded = []

  for (const file of files) {
    if (isSystemOrHiddenFileName(file.name)) continue

    if ((!file.type || !file.type.startsWith('image/')) && !isHeicLikeFile(file)) {
      excluded.push({ name: file.name, reason: '画像ファイル以外' })
      continue
    }

    const ext = file.name.toLowerCase().split('.').pop()
    if (!ext) {
      excluded.push({ name: file.name, reason: '拡張子なし' })
      continue
    }
    if (SLOT_DISALLOWED_IMAGE_EXTENSIONS.has(ext)) {
      excluded.push({ name: file.name, reason: '非対応の画像形式' })
      continue
    }
    if (!SLOT_ALLOWED_IMAGE_EXTENSIONS.has(ext)) {
      excluded.push({ name: file.name, reason: '非対応の画像形式' })
      continue
    }

    valid.push(file)
  }

  return { valid, excluded }
}

const CLOUD_ALLOWED_IMAGE_EXT = new Set([
  'jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'tif', 'tiff', 'heic', 'heif', 'jpe', 'jfif'
])

const CLOUD_BLOCKED_EXTENSIONS = new Set([
  'exe', 'msi', 'bat', 'cmd', 'com', 'pif', 'scr',
  'ps1', 'psm1', 'psd1',
  'sh', 'bash', 'zsh',
  'vbs', 'vbe', 'ws', 'wsf', 'wsh', 'jse',
  'js', 'mjs', 'cjs',
  'jar', 'war', 'class',
  'py', 'pyc', 'pyw',
  'rb', 'pl', 'pm', 'php', 'phtml', 'phar',
  'asp', 'aspx', 'asa', 'cer', 'cdx',
  'jsp', 'jspx',
  'hta',
  'reg', 'cpl', 'msc',
  'lnk', 'scf', 'inf', 'url',
  'dll', 'so', 'dylib'
])

const CLOUD_MAX_FILE_SIZE = 50 * 1024 * 1024

function getFileExtension(name) {
  const idx = String(name ?? '').lastIndexOf('.')
  if (idx === -1) return ''
  return name.slice(idx + 1).trim().toLowerCase()
}

function isAllowedCloudStorageUpload(file) {
  if (!(file instanceof File)) return false
  const mt = String(file.type || '').toLowerCase()
  if (mt.startsWith('image/')) return true
  if (mt === 'application/pdf') return true
  if (mt === 'application/zip' || mt === 'application/x-zip-compressed') return true
  const ext = getFileExtension(file.name)
  if (ext === 'pdf' || ext === 'zip' || ext === 'jww') return true
  return CLOUD_ALLOWED_IMAGE_EXT.has(ext)
}

/**
 * @param {File[]} files
 * @returns {{ valid: File[], excluded: Array<{ name: string, reason: string }> }}
 */
export function partitionCloudStorageUploadFiles(files) {
  /** @type {File[]} */
  const valid = []
  /** @type {Array<{ name: string, reason: string }>} */
  const excluded = []

  for (const file of files) {
    if (isSystemOrHiddenFileName(file.name)) continue

    if (!isAllowedCloudStorageUpload(file)) {
      excluded.push({ name: file.name, reason: '画像・PDF・ZIP・jww以外' })
      continue
    }

    const ext = getFileExtension(file.name)
    if (CLOUD_BLOCKED_EXTENSIONS.has(ext)) {
      excluded.push({ name: file.name, reason: 'アップロード禁止' })
      continue
    }

    if (file.size > CLOUD_MAX_FILE_SIZE) {
      excluded.push({ name: file.name, reason: '50MB超過' })
      continue
    }

    valid.push(file)
  }

  return { valid, excluded }
}

/**
 * @param {{ confirm: (message: string, options?: object) => Promise<boolean> }} dialog
 * @param {Array<{ name: string, reason: string }>} excluded
 */
export async function confirmContinueWithoutExcluded(dialog, excluded) {
  if (!excluded.length) return true
  const lines = excluded.map((item) => `${item.name}（${item.reason}）`).join('\n')
  return dialog.confirm(
    `以下のファイルはアップロード対象外です。除いて続行しますか？\n\n${lines}`,
    { title: '確認' }
  )
}
