import { normalizeExternalCode } from './instructionMerge'

function parseComparisonQuantity(value) {
  if (value === null || value === undefined || value === '') return null
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

function formatQuantityForClipboard(value) {
  const n = parseComparisonQuantity(value)
  if (n === null) return ''
  return String(n)
}

function formatUnitSuffix(unit) {
  const u = unit != null ? String(unit).trim() : ''
  return u ? ` ${u}` : ''
}

/** @param {Date} [date] */
export function formatComparisonClipboardHeaderDate(date = new Date()) {
  const month = date.getMonth() + 1
  const day = date.getDate()
  return `(${month}/${day})`
}

/**
 * billing_items から normCode 別に description / unit / sort_order を引く（変更・削除行用）
 * @param {Array<Record<string, unknown>>} billingItems
 */
export function buildBillingItemLookupByNormCode(billingItems) {
  /** @type {Map<string, { sort_order: number | null, description: string, unit: string }>} */
  const map = new Map()

  for (const b of billingItems || []) {
    const nk = normalizeExternalCode(b?.external_code)
    if (!nk) continue
    const soRaw = b?.sort_order
    const so = soRaw != null && soRaw !== '' ? Number(soRaw) : null
    const entry = {
      sort_order: Number.isFinite(so) ? so : null,
      description: b?.description != null ? String(b.description) : '',
      unit: b?.unit != null ? String(b.unit) : ''
    }

    const cur = map.get(nk)
    if (!cur) {
      map.set(nk, entry)
      continue
    }
    if (Number.isFinite(so) && (cur.sort_order == null || so < cur.sort_order)) {
      cur.sort_order = so
      cur.description = entry.description
      cur.unit = entry.unit
    }
  }

  return map
}

function formatPriceListDescription(priceListItem) {
  if (!priceListItem) return ''
  const description = String(priceListItem.description ?? '').trim()
  const noteRaw = priceListItem.note
  const hasNote = noteRaw !== null && noteRaw !== undefined && String(noteRaw).trim() !== ''
  if (hasNote) {
    const note = String(noteRaw).trim()
    return description ? `${description}-${note}` : note
  }
  return description
}

function resolveAddDescription(item, priceListItems, resolveCompDesc) {
  const nk = normalizeExternalCode(item?.external_code)
  const plItem = (priceListItems || []).find(
    (it) => normalizeExternalCode(it.external_code) === nk
  )
  const plText = formatPriceListDescription(plItem)
  if (plText) return plText
  if (typeof resolveCompDesc === 'function') {
    return resolveCompDesc(item) || '--'
  }
  return item?.estimate_instruction || '--'
}

function resolveAddUnit(item, priceListItems) {
  const nk = normalizeExternalCode(item?.external_code)
  const plItem = (priceListItems || []).find(
    (it) => normalizeExternalCode(it.external_code) === nk
  )
  const unit = plItem?.unit
  if (unit != null && String(unit).trim() !== '') return String(unit).trim()
  return ''
}

export function comparisonItemIsClipboardChange(item) {
  const rq = parseComparisonQuantity(item?.request_quantity)
  const bq = parseComparisonQuantity(item?.billing_quantity)
  if (rq === null) return false
  if (rq === 0) return false
  if (bq === null) return false
  return rq !== bq
}

export function comparisonItemIsClipboardDelete(item) {
  const rq = parseComparisonQuantity(item?.request_quantity)
  const bq = parseComparisonQuantity(item?.billing_quantity)
  return rq === 0 && bq !== null
}

export function comparisonItemIsClipboardAdd(item) {
  const rq = parseComparisonQuantity(item?.request_quantity)
  const bq = parseComparisonQuantity(item?.billing_quantity)
  if (bq !== null) return false
  if (rq === null || rq === 0) return false
  return true
}

/** @param {Array<Record<string, unknown>>} comparisonData */
export function hasComparisonClipboardDiff(comparisonData) {
  for (const item of comparisonData || []) {
    if (
      comparisonItemIsClipboardChange(item) ||
      comparisonItemIsClipboardDelete(item) ||
      comparisonItemIsClipboardAdd(item)
    ) {
      return true
    }
  }
  return false
}

function billingSortKey(item) {
  const so = item?.billing_sort_order
  if (so != null && so !== '' && Number.isFinite(Number(so))) return Number(so)
  return 9999
}

/**
 * @param {{
 *   comparisonData: Array<Record<string, unknown>>,
 *   billingItems: Array<Record<string, unknown>>,
 *   priceListItems?: Array<Record<string, unknown>>,
 *   resolveCompDesc?: (item: Record<string, unknown>) => string,
 *   now?: Date
 * }} params
 */
export function buildComparisonChangeClipboardText({
  comparisonData,
  billingItems,
  priceListItems = [],
  resolveCompDesc,
  now = new Date()
}) {
  const billingLookup = buildBillingItemLookupByNormCode(billingItems)
  const list = comparisonData || []

  /** @type {string[]} */
  const changeLines = []
  /** @type {string[]} */
  const deleteLines = []
  /** @type {string[]} */
  const addLines = []

  const changeItems = []
  const deleteItems = []

  for (const item of list) {
    if (comparisonItemIsClipboardDelete(item)) deleteItems.push(item)
    else if (comparisonItemIsClipboardChange(item)) changeItems.push(item)
  }

  changeItems.sort((a, b) => billingSortKey(a) - billingSortKey(b))
  deleteItems.sort((a, b) => billingSortKey(a) - billingSortKey(b))

  for (const item of changeItems) {
    const nk = normalizeExternalCode(item.external_code)
    const billing = billingLookup.get(nk) || {}
    const sortOrder = billingSortKey(item)
    const description = billing.description ?? ''
    const billQty = formatQuantityForClipboard(item.billing_quantity)
    const reqQty = formatQuantityForClipboard(item.request_quantity)
    const unitSuffix = formatUnitSuffix(billing.unit)
    changeLines.push(`${sortOrder + 1}-${description} [${billQty}] → [${reqQty}]${unitSuffix}`)
  }

  for (const item of deleteItems) {
    const nk = normalizeExternalCode(item.external_code)
    const billing = billingLookup.get(nk) || {}
    const sortOrder = billingSortKey(item)
    const description = billing.description ?? ''
    const billQty = formatQuantityForClipboard(item.billing_quantity)
    const unitSuffix = formatUnitSuffix(billing.unit)
    deleteLines.push(`${sortOrder + 1}-${description} [${billQty}] → [0]${unitSuffix}`)
  }

  for (const item of list) {
    if (!comparisonItemIsClipboardAdd(item)) continue
    const code = String(item.external_code || '').trim()
    const description = resolveAddDescription(item, priceListItems, resolveCompDesc)
    const reqQty = formatQuantityForClipboard(item.request_quantity)
    const unitSuffix = formatUnitSuffix(resolveAddUnit(item, priceListItems))
    addLines.push(`${code}-${description} [${reqQty}]${unitSuffix}`)
  }

  /** @type {string[]} */
  const sections = []
  if (changeLines.length) sections.push(['・変更', ...changeLines].join('\n'))
  if (deleteLines.length) sections.push(['・削除', ...deleteLines].join('\n'))
  if (addLines.length) sections.push(['・追加', ...addLines].join('\n'))

  const header = `${formatComparisonClipboardHeaderDate(now)} 指示書変更お願いします。`
  const footer = 'よろしくお願いします。'

  return [header, '', sections.join('\n\n'), '', footer].join('\n')
}
