<template>
  <div class="billing-comparison-list" :class="{ 'is-mobile': isMobile }">
    <!-- ローディング表示 -->
    <div v-if="loading" class="comparison-loading">
      データを読み込み中
    </div>
    
    <!-- データなし -->
    <div v-else-if="!billingItems || billingItems.length === 0" class="comparison-empty">
      <p>比較データがありません</p>
      <p class="hint">物件を選択してください</p>
    </div>
    
    <!-- 比較アイテム一覧 -->
    <div v-else class="comparison-items-list">
      <div 
        v-for="item in sortedBillingItems" 
        :key="item.id"
        class="comparison-item"
        :class="{
          'comparison-item-selected': String(selectedComparisonItemId || '') === String(item.id || ''),
          'comparison-item-pick-mode': billingPickModeActive,
          'comparison-item-missing-photo-input': isMissingPhotoInput(item)
        }"
        draggable="true"
        @click="handleItemClick($event, item)"
        @dragstart="handleDragStart($event, item)"
        @dragend="handleDragEnd"
        @dblclick="handleDoubleClick($event, item)"
      >
        <div class="comparison-content">
          <div class="sort-order">{{ (item.sort_order || 0) + 1 }}</div>
          <div v-if="!isMobile" class="code">{{ item.external_code }}</div>
          <div class="description">{{ item.description }}</div>
          <div class="quantity">{{ formatQuantity(item.quantity) }}</div>
          <div class="unit">{{ item.unit || '-' }}</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'

const props = defineProps({
  billingItems: {
    type: Array,
    default: () => []
  },
  loading: {
    type: Boolean,
    default: false
  },
  beforeCategoryId: {
    type: [String, Number],
    default: null
  },
  beforeCategoryFiles: {
    type: Array,
    default: () => []
  },
  photoWorkLinksByFileId: {
    type: Object,
    default: () => ({})
  },
  selectedComparisonItemId: {
    type: [String, Number],
    default: ''
  },
  billingPickModeActive: {
    type: Boolean,
    default: false
  },
  isMobile: {
    type: Boolean,
    default: false
  }
})

const emit = defineEmits(['drag-start', 'drag-end', 'jump-to-all-by-code', 'update-selected-comparison-item-id', 'billing-item-append'])

// billing_sort_orderでソート（sort_orderフィールドを使用）
const sortedBillingItems = computed(() => {
  if (!props.billingItems || props.billingItems.length === 0) return []
  return [...props.billingItems].sort((a, b) => {
    const orderA = a.sort_order || 0
    const orderB = b.sort_order || 0
    return orderA - orderB
  })
})

// 数量のフォーマット
function formatQuantity(quantity) {
  if (quantity == null || quantity === '') return '-'
  // 小数点以下不要な場合は整数表示
  const num = parseFloat(quantity)
  return Number.isInteger(num) ? num.toString() : num.toFixed(2)
}

// ドラッグ開始
function handleDragStart(event, item) {
  event.dataTransfer.effectAllowed = 'copy'
  event.dataTransfer.setData('text/plain', JSON.stringify({
    type: 'billing-item',
    id: item.id,
    external_code: item.external_code,
    description: item.description,
    content: item.content || '',
    quantity: item.quantity,
    unit: item.unit,
    sort_order: item.sort_order
  }))
  emit('drag-start', item)
}

// ドラッグ終了
function handleDragEnd() {
  emit('drag-end')
}

function normalizeCode(code) {
  return String(code || '').trim()
}

function hasPhotoInputForCode(codeRaw) {
  const code = normalizeCode(codeRaw)
  const categoryId = String(props.beforeCategoryId || '').trim()
  if (!code || !categoryId) return false
  const candidateFiles = Array.isArray(props.beforeCategoryFiles) ? props.beforeCategoryFiles : []
  if (!candidateFiles.length) return false
  return candidateFiles.some((file) => {
    const fileId = String(file?.id || '')
    if (!fileId) return false
    const rows = props.photoWorkLinksByFileId?.[fileId] || []
    return rows.some((link) => normalizeCode(link?.external_code) === code)
  })
}

function isMissingPhotoInput(item) {
  return !hasPhotoInputForCode(item?.external_code)
}

function triggerComparisonAlert(itemEl) {
  if (!itemEl) return
  itemEl.classList.remove('alert-glow-effect')
  void itemEl.offsetWidth
  itemEl.classList.add('alert-glow-effect')
  setTimeout(() => {
    itemEl.classList.remove('alert-glow-effect')
  }, 1400)
}

function buildComparisonJumpTarget(codeRaw) {
  const code = normalizeCode(codeRaw)
  const categoryId = String(props.beforeCategoryId || '').trim()
  if (!hasPhotoInputForCode(codeRaw)) return null
  const candidateFiles = Array.isArray(props.beforeCategoryFiles) ? props.beforeCategoryFiles : []
  const matchedFileIds = candidateFiles
    .map((file) => String(file?.id || ''))
    .filter((fileId) => {
      if (!fileId) return false
      const rows = props.photoWorkLinksByFileId?.[fileId] || []
      return rows.some((link) => normalizeCode(link?.external_code) === code)
    })
  return {
    code,
    categoryId,
    fileIds: matchedFileIds
  }
}

// ダブルクリック - 全画像タブへジャンプ（未該当時は赤発光）
function handleItemClick(event, item) {
  if (!props.billingPickModeActive) return
  event.preventDefault()
  emit('billing-item-append', item)
}

function handleDoubleClick(event, item) {
  if (props.billingPickModeActive) return
  const target = buildComparisonJumpTarget(item?.external_code)
  if (!target) {
    triggerComparisonAlert(event.currentTarget)
    return
  }
  emit('update-selected-comparison-item-id', String(item?.id || ''))
  emit('jump-to-all-by-code', target)
}
</script>

