async function submitTempWork() {
  if (!canSubmitTempWork.value) return
  
  tempWorkSubmitting.value = true
  tempWorkResultMessage.value = ''
  tempWorkResultIsError.value = false
  
  try {
    const token = (await supabaseClient.auth.getSession()).data.session?.access_token
    if (!token) throw new Error('認証情報がありません')
    
    const response = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/manage_temp_work`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        action: 'insert',
        housing_detail_id: selectedHousingDetailId.value,
        room: tempWorkRoom.value,
        mc_id: parseInt(tempWorkMcId.value, 10),
      }),
    })
    
    const result = await response.json()
    
    if (!response.ok || !result.ok) {
      throw new Error(result.error || 'エラーが発生しました')
    }
    
    tempWorkResultMessage.value = result.message || '登録しました'
    tempWorkResultIsError.value = false
    clearTempWorkForm()
    
    // 差分同期を実行（新しく追加されたworkを取得）
    await performIncrementalSync('manual')
  } catch (err) {
    console.error('Failed to submit temp work:', err)
    tempWorkResultMessage.value = err.message || '登録に失敗しました'
    tempWorkResultIsError.value = true
  } finally {
    tempWorkSubmitting.value = false
  }
}

