// 種別キー（UI用）: small(小口) / large(空家)
function getWorkKindKey(work) {
  if (!work) return 'unknown'
  if (work.kind === 'large') return 'large'
  if (work.kind === 'small') return 'small'
  return work.kind || 'unknown'
}

function getWorkKindLabelByKey(kindKey) {
  const labels = { small: '小口', large: '空家' }
  return labels[kindKey] || kindKey
}

function getWorkKindLabel(work) {
  return getWorkKindLabelByKey(getWorkKindKey(work))
}

// 年度表示用：9999 -> 仮登録
function getYearLabel(year) {
  if (!year) return '-'
  return String(year) === '9999' ? '仮登録' : `${year}年`
}

// 年度表示（年のみ、単位なし）：9999 -> 仮登録
function getYearLabelShort(year) {
  if (!year) return '-'
  return String(year) === '9999' ? '仮登録' : year
}

// 検索結果（フラットリスト）用：スマホ時は短縮表記
function getWorkKindLabelForList(work) {
  const kindKey = getWorkKindKey(work)
  if (!isMobile.value) return getWorkKindLabelByKey(kindKey)
  // スマホ: 空家→空、小口→小
  const labels = { large: '空', small: '小' }
  return labels[kindKey] || kindKey
}

function splitKeywords(query) {
  return String(query || '')
    .split(/[\s　]+/)
    .map(k => k.trim().toLowerCase())
    .filter(k => k.length > 0)
}

function matchesAllKeywords(text, query) {
  const keywords = splitKeywords(query)
  if (keywords.length === 0) return true
  const target = String(text || '').toLowerCase()
  return keywords.every(k => target.includes(k))
}

function workMatchesOrderNoFilter(work) {
  const needle = normalizeOrderNoDigits(filterOrderNo.value)
  if (!needle) return true
  return normalizeOrderNoDigits(work?.order_no) === needle
}

function filterWorksByDetailQuery(works, detailQuery) {
  const keywords = splitKeywords(detailQuery)
  if (keywords.length === 0) return works
  return works.filter(w => {
    const searchableFields = [
      w.repair_item || '',
      w.jkk_note || '',
      w.kousya_change_text || '',
      w.kouji_change_text || '',
      w.note || '',
      w.execution_detail || ''
    ].join(' ').toLowerCase()
    return keywords.every(keyword => searchableFields.includes(keyword))
  })
}

function inDateRangeByOrderedOn(work, from, to) {
  if (!from && !to) return true
  if (!work.ordered_on) return false
  const d = new Date(work.ordered_on)
  if (from) {
    const f = new Date(from)
    if (d < f) return false
  }
  if (to) {
    const t = new Date(to)
    t.setDate(t.getDate() + 1)
    if (d >= t) return false
  }
  return true
}

