/** 表示名 → 年度（新しい年が先）→ MC（昇順） */
function compareDisplayNameYearMc(a, b) {
  const nameA = getWorkDisplayName(a)
  const nameB = getWorkDisplayName(b)
  const nameCompare = nameA.localeCompare(nameB, 'ja')
  if (nameCompare !== 0) return nameCompare
  const yearA = a.order_year || 0
  const yearB = b.order_year || 0
  const yearCompare = yearB - yearA
  if (yearCompare !== 0) return yearCompare
  const mcA = a.mc_id || 0
  const mcB = b.mc_id || 0
  return mcA - mcB
}

/** 指示番号（昇順）。未設定は末尾 */
function compareOrderNoAsc(a, b) {
  const noA = String(a?.order_no ?? '').trim()
  const noB = String(b?.order_no ?? '').trim()
  if (!noA && !noB) return 0
  if (!noA) return 1
  if (!noB) return -1
  return noA.localeCompare(noB, 'ja', { numeric: true })
}

/** 調査日（ordered_on）。未設定はいずれの向きでも末尾 */
function getWorkOrderedOnMs(work) {
  const s = work?.ordered_on
  if (!s) return null
  const t = new Date(s).getTime()
  return Number.isFinite(t) ? t : null
}

/**
 * @param {Array} list
 * @param {'none'|'desc'|'asc'} mode desc=調査日降順（新しい順）, asc=昇順（古い順）
 */
function sortWorksByOrderedOnMode(list, mode) {
  if (mode === 'none') {
    return [...list].sort(compareDisplayNameYearMc)
  }
  return [...list].sort((a, b) => {
    const ta = getWorkOrderedOnMs(a)
    const tb = getWorkOrderedOnMs(b)
    if (mode === 'desc') {
      if (ta === null && tb === null) return compareDisplayNameYearMc(a, b)
      if (ta === null) return 1
      if (tb === null) return -1
      const d = tb - ta
      if (d !== 0) return d
    } else {
      if (ta === null && tb === null) return compareDisplayNameYearMc(a, b)
      if (ta === null) return 1
      if (tb === null) return -1
      const d = ta - tb
      if (d !== 0) return d
    }
    return compareDisplayNameYearMc(a, b)
  })
}

function sortByDisplayNameYearMc(list) {
  return [...list].sort(compareDisplayNameYearMc)
}

