const tempWorksSorted = computed(() => {
  return [...tempWorksFiltered.value].sort((a, b) => {
    // MC -> 団地名 -> 棟 -> 部屋番号でソート
    if (a.mc_id !== b.mc_id) return a.mc_id - b.mc_id
    const aName = a.housing_details?.name || ''
    const bName = b.housing_details?.name || ''
    if (aName !== bName) return aName.localeCompare(bName)
    const aBuilding = a.housing_details?.building || ''
    const bBuilding = b.housing_details?.building || ''
    if (aBuilding !== bBuilding) return aBuilding.localeCompare(bBuilding)
    return (a.room || '').localeCompare(b.room || '')
  })
})

function toggleRegisterWork(workId) {
  const set = new Set(registerSelectedWorkIdSet.value)
  if (set.has(workId)) set.delete(workId)
  else set.add(workId)
  registerSelectedWorkIdSet.value = set
}

function hasActiveLongDetail(work) {
  const detail = work?.work_small_long_details
  if (detail && !detail.deleted_at) return true
  return !!work?.has_long_detail && (!detail || !detail.deleted_at)
}

function hasLongDetailStep(work) {
  if (!hasActiveLongDetail(work)) return false
  return !!work?.work_small_long_details?.has_step
}

