function toggleRegisterSelectAll() {
  const visible = registerWorksSorted.value.map(w => w.id)
  const set = new Set(registerSelectedWorkIdSet.value)
  if (visible.length === 0) return
  if (visible.every(id => set.has(id))) {
    visible.forEach(id => set.delete(id))
  } else {
    visible.forEach(id => set.add(id))
  }
  registerSelectedWorkIdSet.value = set
}

async function updateWorksLongDetailsInCacheAndState(workIds, { inspection_on, movein_on, scheduled_on }) {
  const nowIso = new Date().toISOString()
  const workIdSet = new Set(workIds)

  // 画面のstateを更新
  works.value = works.value.map(w => {
    if (!workIdSet.has(w.id)) return w
    return {
      ...w,
      has_long_detail: true,
      work_small_long_details: {
        inspection_on,
        movein_on,
        scheduled_on,
        has_repair: false,
        has_cleaning: false,
        has_step: false,
        updated_at: nowIso
      }
    }
  })

  // IndexedDBのworksも更新（存在するレコードのみ）
  // シリアライズ可能な形式に変換（参照を除去）
  const targets = works.value
    .filter(w => workIdSet.has(w.id))
    .map(w => JSON.parse(JSON.stringify(w)))
  
  if (targets.length > 0) {
    await indexedDBService.works.bulkPut(targets)
  }
}

async function removeWorksLongDetailsInCacheAndState(workIds) {
  const nowIso = new Date().toISOString()
  const workIdSet = new Set(workIds)

  works.value = works.value.map(w => {
    if (!workIdSet.has(w.id)) return w
    return {
      ...w,
      has_long_detail: false,
      work_small_long_details: w.work_small_long_details
        ? {
            ...w.work_small_long_details,
            deleted_at: nowIso,
            updated_at: nowIso
          }
        : {
            deleted_at: nowIso,
            updated_at: nowIso
          }
    }
  })

  const targets = works.value
    .filter(w => workIdSet.has(w.id))
    .map(w => JSON.parse(JSON.stringify(w)))

  if (targets.length > 0) {
    await indexedDBService.works.bulkPut(targets)
  }
}

async function handleDeleteLongDetail(work) {
  if (!work?.id) return
  if (!hasActiveLongDetail(work)) return
  if (longDetailDeletingIds.value.has(work.id)) return
  if (!await dialog.confirm('この長期データを削除しますか？', { title: '確認' })) return

  longDetailDeletingIds.value = new Set([...longDetailDeletingIds.value, work.id])
  try {
    await supabaseService.updateSmallLongDetails(work.id, {
      deleted_at: new Date().toISOString()
    })
    await removeWorksLongDetailsInCacheAndState([work.id])

    const selectedSet = new Set(registerSelectedWorkIdSet.value)
    selectedSet.delete(work.id)
    registerSelectedWorkIdSet.value = selectedSet

    if (selectedWork.value?.id === work.id) {
      selectedWork.value = works.value.find(w => w.id === work.id) || selectedWork.value
    }
    if (selectedSameHousingWork.value?.id === work.id) {
      selectedSameHousingWork.value = sameHousingWorks.value.find(w => w.id === work.id) || selectedSameHousingWork.value
    }
  } catch (err) {
    console.error('Failed to delete long detail:', err)
    error.value = `長期データの削除に失敗しました: ${err.message}`
  } finally {
    const next = new Set(longDetailDeletingIds.value)
    next.delete(work.id)
    longDetailDeletingIds.value = next
  }
}

async function submitBulk() {
  resultMessage.value = ''
  resultIsError.value = false

  const workIds = Array.from(registerSelectedWorkIdSet.value)
  if (workIds.length === 0) return

  if (!bulkInspectionOn.value && !bulkMoveinOn.value && !bulkScheduledOn.value) {
    resultIsError.value = true
    resultMessage.value = '入力が空です（inspection_on / movein_on / scheduled_on のいずれかを入力してください）'
    return
  }

  submitting.value = true
  try {
    const res = await supabaseService.bulkUpsertWorkSmallLongDetails(workIds, {
      inspection_on: bulkInspectionOn.value || null,
      movein_on: bulkMoveinOn.value || null,
      scheduled_on: bulkScheduledOn.value || null,
      employee_id: bulkEmployeeId.value || null
    })

    const skipped = res?.skipped_count || 0
    resultMessage.value = `登録完了: ${res?.inserted_or_updated || 0}件（スキップ: ${skipped}件）`
    await updateWorksLongDetailsInCacheAndState(workIds, {
      inspection_on: bulkInspectionOn.value || null,
      movein_on: bulkMoveinOn.value || null,
      scheduled_on: bulkScheduledOn.value || null,
      employee_id: bulkEmployeeId.value || null
    })
    clearRegisterFilters()
    clearBulkInputs()
    registerSelectedWorkIdSet.value = new Set()
  } catch (e) {
    resultIsError.value = true
    resultMessage.value = e?.message || '登録に失敗しました'
  } finally {
    submitting.value = false
  }
}

