function applyLongDetailToDraft(work, draftRef) {
  if (!work || !work.work_small_long_details) {
    draftRef.value = makeEmptyLongDetailDraft()
    return
  }
  const d = work.work_small_long_details
  draftRef.value = {
    inspection_on: d.inspection_on || '',
    movein_on: d.movein_on || '',
