// 物件の工事状況・公社状態によるクラスを返す（長期・小口共通）
function getWorkStatusClass(work) {
  if (!work || typeof work !== 'object') return ''
  // 工事状況IDを取得（largeまたはsmallに応じて）
  let progressiveStatusId = null
  let jkkStatusId = null
  
  if (work.kind === 'large') {
    progressiveStatusId = work.large_progressive_status_id
    jkkStatusId = work.large_jkk_status_id
  
    // 完了チェック
    if (jkkStatusId === 6 || jkkStatusId === 7 || jkkStatusId === 8 || jkkStatusId === 9) {
      return 'status-completed'
    }
    if (progressiveStatusId === 8 || progressiveStatusId === 9) {
      return 'status-done' // 一次完了
    }
    if (jkkStatusId === 3 || jkkStatusId === 4 || jkkStatusId === 5) {
      return 'status-in-progress' // 対応中
    }
    if (jkkStatusId === 2) {
      return 'status-adjusting' // 調整中
    }
    
  } else if (work.kind === 'small') {
    progressiveStatusId = work.small_progressive_status_id
    jkkStatusId = work.small_jkk_status_id
  
    // 取消チェック（工事状況=5 または 公社状態=5）
    if (progressiveStatusId === 5 || jkkStatusId === 5) {
      return 'status-cancelled'
    }
    
    // 完了チェック（工事状況=4 または 公社状態=3 or 4）
    if (progressiveStatusId === 4 || jkkStatusId === 3 || jkkStatusId === 4) {
      return 'status-completed'
    }
    
    // 工事状況による判定
    if (progressiveStatusId === 1) {
      return 'status-in-progress' // 対応中
    }
    if (progressiveStatusId === 2) {
      return 'status-adjusting' // 調整中
    }
    if (progressiveStatusId === 3) {
      return 'status-done' // 一次完了
    }
  }
  return ''
}

