// フィルター適用後のワークス
const filteredWorks = computed(() => {
  // ハウジングIDが存在しないワークスを除外
  let result = works.value.filter(w => w.housing_detail_id != null)
  
  // ★ボタンが押されている場合は、フェイバリットか否かだけを判定
  if (filterFavorite.value) {
    const favoriteWorkIds = new Set(userWorkFavorites.value.map(fav => fav.work_id))
    return result.filter(w => favoriteWorkIds.has(w.id))
  }

  // 種別フィルター（小口/空家）
  const selected = new Set()
  if (filterLarge.value) selected.add('large')
  if (filterSmall.value) selected.add('small')
  if (selected.size > 0) {
    result = result.filter(w => selected.has(getWorkKindKey(w)))
  }
  
  // 年度フィルター
  if (filterYear.value) {
    result = result.filter(w => w.order_year === filterYear.value)
  }
  
  // MCフィルター
  if (filterMc.value) {
    result = result.filter(w => w.mc_id === filterMc.value)
  }

  // 指示番号（完全一致）
  if (filterOrderNo.value) {
    result = result.filter(workMatchesOrderNoFilter)
  }
  
  // 担当フィルター
  if (filterEmployeeId.value) {
    result = result.filter(w => String(w.employee_id || '') === String(filterEmployeeId.value))
  }
  
  // 場所検索（housing_details.name + building + room で部分一致）
  // 複数条件対応：全角・半角スペース区切り
  if (filterLocation.value.trim()) {
    // 全角・半角スペースで分割してトリム
    const keywords = filterLocation.value
      .split(/[\s　]+/)
      .map(k => k.trim().toLowerCase())
      .filter(k => k.length > 0)
    
    if (keywords.length > 0) {
      result = result.filter(w => {
        const locationStr = getWorkDisplayName(w).toLowerCase()
        // すべてのキーワードが含まれているかチェック（AND条件）
        return keywords.every(keyword => locationStr.includes(keyword))
      })
    }
  }
  
  // 詳細検索（repair_item, jkk_note, note, execution_detail で検索）
  if (filterDetail.value.trim()) {
    result = filterWorksByDetailQuery(result, filterDetail.value)
  }
  
  // スーパー検索（請求アイテム検索結果でフィルタリング）
  if (superSearchWorkIds.value.length > 0) {
    const workIdSet = new Set(superSearchWorkIds.value)
    result = result.filter(w => workIdSet.has(w.id))
  }
  
  // お気に入りフィルター
  if (filterFavorite.value) {
    const favoriteWorkIds = new Set(userWorkFavorites.value.map(fav => fav.work_id))
    result = result.filter(w => favoriteWorkIds.has(w.id))
  }
  
  return result
})

