// ワークスの表示名を生成
function getWorkDisplayName(work) {
  const housingName = work.housing_details?.name || ''
  const building = work.housing_details?.building || ''
  const room = work.room || ''
  
  const parts = []
  if (housingName) parts.push(housingName)
  if (building) parts.push(building)
  if (room) parts.push(room)
  
  return parts.length > 0 ? parts.join('-') : `Work ${work.id}`
}

/** 顧客電話に発信可能な数字が含まれるか（* のみ等は false） */
function customerTelHasDigits(raw) {
  return /\d/.test(String(raw ?? ''))
}

/** 顧客電話の tel: リンク（数字と先頭の + のみ） */
function customerTelHref(raw) {
  const s = String(raw ?? '').trim()
  if (!s || !customerTelHasDigits(s)) return ''
  const digits = s.replace(/[^\d+]/g, '')
  if (!digits) return ''
  return `tel:${digits}`
}

// housing_details の住所を整形（1,2,3,4はスペースなし連結、5・6はハイフンで連結 例: 東京都三鷹市井の頭5-20-11）
function getWorkAddress(work) {
  const h = work?.housing_details
  if (!h) return ''
  const parts = [h.address_1, h.address_2, h.address_3, h.address_4].filter(Boolean)
  let s = parts.join('')
  if (h.address_5) s += (s ? '-' : '') + h.address_5
  if (h.address_6) s += (s ? '-' : '') + h.address_6
  return s.trim()
}

// 住所の Google マップ検索URL
function getWorkAddressGoogleMapsUrl(work) {
  const addr = getWorkAddress(work)
  if (!addr) return null
  return `https://www.google.co.jp/maps/place/${encodeURIComponent(addr)}`
}

