// 使用年月日を年とヶ月に分割
function formatUsageMonth(usageMonth) {
  if (!usageMonth) return { years: 0, months: 0 }
  const years = Math.floor(usageMonth / 12)
  const months = usageMonth % 12
  return { years, months }
}

