// 現在実行中のselectWorkリクエストを追跡
let currentSelectWorkId = null

// ワークスを選択（詳細は既に取得済み、PDF情報と請求項目のみ取得）
async function selectWork(work) {
  if (isTablet.value && showSameHousingWorks.value) {
    showSameHousingWorks.value = false
    selectedSameHousingWork.value = null
    sameHousingError.value = null
    sameHousingPdfFile.value = []
    sameHousingBillingItems.value = []
    sameHousingWorkHasStorageImages.value = false
  }

  // 現在のworkIdを保存（このリクエストのID）
  const requestWorkId = work.id
  currentSelectWorkId = requestWorkId
  
  // 既存のリスナーをクリーンアップ（即座に）
  if (unsubscribeBillingUpdate) {
    unsubscribeBillingUpdate()
    unsubscribeBillingUpdate = null
  }
  if (unsubscribeWorkLargeScheduleUpdate) {
    unsubscribeWorkLargeScheduleUpdate()
    unsubscribeWorkLargeScheduleUpdate = null
  }
  
  selectedWorkId.value = work.id
  
  // IndexedDBから最新のworkデータを取得（work_small_long_detailsを含む）
  let latestWork = work
  try {
    const dbWork = await indexedDBService.getWorkById(work.id)
    if (dbWork) {
      latestWork = dbWork
    }
  } catch (err) {
    console.warn('Failed to get work from IndexedDB, using cached work:', err)
  }
  
  selectedWork.value = latestWork
  syncLargeStepUiFromWork(latestWork)
  
  // works配列も更新（他の場所で参照される可能性があるため）
  const workIndex = works.value.findIndex(w => w.id === work.id)
  if (workIndex !== -1) {
    works.value[workIndex] = latestWork
  }
  
  if (isMobile.value) mobilePanel.value = 'details'
  pdfFile.value = []
  billingItems.value = []
  workHasStorageImages.value = false
  workLargeScheduleHasData.value = false
  
  try {
    detailsLoading.value = true
    error.value = null
    
    const fetchTasks = [
      supabaseService.getPdfFile(work.id).catch(() => ({ pdfFiles: [], hasWorkImages: false })),
      supabaseService.getBillingItems(work.id).catch(() => ({ billingItems: [] })),
    ]
    if (latestWork.kind === 'large') {
      fetchTasks.push(
        supabaseService.getWorkLargeSchedules(work.id).catch(() => ({ rows: [] }))
      )
    }

    const results = await Promise.all(fetchTasks)
    const storageInfo = results[0]
    const billing = results[1]
    const scheduleResult = latestWork.kind === 'large' ? results[2] : null
    
    // 非同期処理完了後、まだこのworkが選択されているかチェック
    if (currentSelectWorkId !== requestWorkId) {
      return // 別の物件が選択されているので、結果を破棄
    }
    
    pdfFile.value = storageInfo?.pdfFiles ?? []
    workHasStorageImages.value = storageInfo?.hasWorkImages === true
    billingItems.value = billing.billingItems || []
    if (latestWork.kind === 'large') {
      syncWorkLargeScheduleHasData(scheduleResult?.rows)
    }
    
    // 新しいリスナーを登録（バックグラウンド更新時にUIを自動更新）
    unsubscribeBillingUpdate = indexedDBService.onBillingItemsUpdate(
      requestWorkId,
      (newItems, kind) => {
        // 現在選択中のworkと一致する場合のみUIを更新（競合状態を防ぐ）
        if (selectedWork.value && selectedWork.value.id === requestWorkId) {
          billingItems.value = newItems
        }
      }
    )
    if (latestWork.kind === 'large') {
      unsubscribeWorkLargeScheduleUpdate = indexedDBService.onWorkLargeScheduleUpdate(
        requestWorkId,
        (rows) => {
          if (selectedWork.value && selectedWork.value.id === requestWorkId) {
            syncWorkLargeScheduleHasData(rows)
          }
        }
      )
    }
  } catch (err) {
    console.error('Error fetching work details:', err)
    error.value = `詳細の取得に失敗しました: ${err.message}`
  } finally {
    // 現在のリクエストの場合のみローディングを解除
    if (currentSelectWorkId === requestWorkId) {
      detailsLoading.value = false
    }
  }
}

