// お気に入り機能
async function handleFavorite() {
  if (!selectedWork.value) return
  
  const workId = selectedWork.value.id
  
  // 既にお気に入りの場合は削除
  if (isFavoriteWork.value) {
    try {
      // 楽観的更新: IndexedDBから先に削除
      await indexedDBService.removeFavorite(workId)
      userWorkFavorites.value = userWorkFavorites.value.filter(fav => fav.work_id !== workId)
      
      // 同期キューに追加
      await syncQueueService.addToQueue(
        workId,
        OperationType.REMOVE_FAVORITE,
        {}
      )
    } catch (error) {
      console.error('お気に入り削除エラー:', error)
      
      // エラー時はロールバック（再度追加）
      const tempFavoriteId = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
      await indexedDBService.addFavorite(tempFavoriteId, workId)
      userWorkFavorites.value.push({
        id: tempFavoriteId,
        work_id: workId,
        updated_at: new Date().toISOString()
      })
      
      await dialog.alert('お気に入りの削除に失敗しました', { title: 'エラー' })
    }
    return
  }
  
  // お気に入りに追加
  try {
    // 楽観的更新: IndexedDBに先に追加（仮ID）
    const tempFavoriteId = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
    await indexedDBService.addFavorite(tempFavoriteId, workId)
    userWorkFavorites.value.push({
      id: tempFavoriteId,
      work_id: workId,
      updated_at: new Date().toISOString()
    })
    
    // 同期キューに追加
    await syncQueueService.addToQueue(
      workId,
      OperationType.ADD_FAVORITE,
      {}
    )
  } catch (error) {
    console.error('お気に入り追加エラー:', error)
    
    // エラー時はロールバック
    userWorkFavorites.value = userWorkFavorites.value.filter(fav => fav.work_id !== workId)
    await indexedDBService.removeFavorite(workId)
    
    await dialog.alert('お気に入りの追加に失敗しました', { title: 'エラー' })
  }
}

// 同一住戸のWORKSを表示
function showSameHousing() {
  if (!selectedWork.value) return
  
  const housingDetailId = selectedWork.value.housing_detail_id
  const room = selectedWork.value.room
  
  if (!housingDetailId || !room) {
    sameHousingError.value = 'ハウジングIDまたはルームが設定されていません'
    showSameHousingWorks.value = true
    sameHousingWorks.value = []
    if (isMobile.value) mobilePanel.value = 'sameHousing'
    return
  }
  
  // エラーをクリア
  sameHousingError.value = null
  
  // 同じhousing_detail_idとroomを持つWORKSを抽出
  const filteredWorks = works.value.filter(w => 
    w.housing_detail_id === housingDetailId && w.room === room
  )
  
  // ordered_onで降順ソート（nullは一番上）
  const sortedWorks = filteredWorks.sort((a, b) => {
    if (a.ordered_on === null && b.ordered_on === null) return 0
    if (a.ordered_on === null) return -1
    if (b.ordered_on === null) return 1
    return new Date(b.ordered_on) - new Date(a.ordered_on)
  })
  
  sameHousingWorks.value = sortedWorks
  showSameHousingWorks.value = true
  if (isMobile.value) mobilePanel.value = 'sameHousing'
  selectedSameHousingWork.value = null
}

