// バックグラウンド差分同期用のタイマー
let syncInterval = null

// データ読み込み（IndexedDB統合版）
async function loadWorks() {
  // 既にデータが読み込まれている場合はスキップ（強制リロード以外）
  if (works.value.length > 0) {
    return
  }
  
  loading.value = true
  error.value = null
  
  try {
    // 認証チェック
    if (!props.isAuthenticated) {
      loading.value = false
      return
    }
    
    // まず IndexedDB の既存データを表示（キャッシュ期限に関わらず）
    const cachedFromDb = await indexedDBService.getAllWorks()
    if (cachedFromDb && cachedFromDb.length > 0) {
      works.value = cachedFromDb

      // 旧キャッシュ（has_long_detail が無い）ならサーバーから再取得してキャッシュ更新
      const hasLongFlag = (cachedFromDb || []).some(w => Object.prototype.hasOwnProperty.call(w, 'has_long_detail'))
      if (!hasLongFlag) {
        await performFullSyncWorks('tab')
      } else {
        // バックグラウンドで差分同期
        await performIncrementalSync('tab')
      }
    } else {
      // キャッシュ有効性チェック（IndexedDBに表示データが無い場合のみ）
      const isCacheValid = await indexedDBService.isCacheValid('works')
    
      if (isCacheValid) {
        // キャッシュから読み込み（0件の場合は後続のフル同期へ）
        const cached = await indexedDBService.getAllWorks()
        works.value = cached

        // 旧キャッシュ（has_long_detail が無い）ならサーバーから再取得してキャッシュ更新
        const hasLongFlag = (cached || []).some(w => Object.prototype.hasOwnProperty.call(w, 'has_long_detail'))
        if (!hasLongFlag) {
          await performFullSyncWorks('tab')
        } else {
          // バックグラウンドで差分同期
          await performIncrementalSync('tab')
        }
      } else {
        // フル同期
        await performFullSyncWorks('tab')
      }
    }
  } catch (err) {
    console.error('Error loading works:', err)
    error.value = `データの読み込みに失敗しました: ${err.message}`
    
    // 401エラーの場合は認証エラーメッセージを表示
    if (err.status === 401) {
      error.value = '認証が必要です。再度ログインしてください。'
      return
    }
    
    // フォールバック: サーバーから直接取得
    try {
      const worksData = await supabaseService.getAllWorks()
      await indexedDBService.cacheAllWorks(worksData)
      
      const staticData = await supabaseService.getAllStaticData()
      await indexedDBService.cacheAllStaticData(staticData)
      
      // IndexedDBから読み込んでUIに表示
      works.value = await indexedDBService.getAllWorks()
      
      // 静的データもUIに反映
      employees.value = await indexedDBService.getMasterData('master_employees')
      mcs.value = await indexedDBService.getMasterData('master_mc')
      largeSteps.value = await indexedDBService.getMasterData('master_large_steps')
      largeJkkStatuses.value = await indexedDBService.getMasterData('master_large_jkk_statuses')
      largeProgressiveStatuses.value = await indexedDBService.getMasterData('master_large_progressive_statuses')
      smallJkkStatuses.value = await indexedDBService.getMasterData('master_small_jkk_statuses')
      smallProgressiveStatuses.value = await indexedDBService.getMasterData('master_small_progressive_statuses')
      userWorkFavorites.value = await indexedDBService.getUserWorkFavorites()
      housingDetails.value = await indexedDBService.getMasterData('housing_details')
    } catch (fallbackErr) {
      console.error('Fallback also failed:', fallbackErr)
    }
  } finally {
    loading.value = false
  }
}

// Worksデータのリロード（差分同期または全件取得）
async function performFullSyncWorks(syncReason = 'manual') {
  loading.value = true
  try {
    // 認証チェック
    if (!props.isAuthenticated) {
      loading.value = false
      return
    }
    
    // lastSyncAtの有無を確認
    const lastSyncAt = await indexedDBService.getLastSyncTime('works')
    
    if (lastSyncAt) {
      // 差分同期を実行（worksとお気に入りの両方）
      await performIncrementalSync(syncReason)
    } else {
      // 初回または同期メタデータがない場合は全件取得
      // Works全件取得
      const worksData = await supabaseService.getAllWorks()
      await indexedDBService.cacheAllWorks(worksData)
      
      // 静的データ（マスター、テンプレート、お気に入り）も全件取得
      const staticData = await supabaseService.getAllStaticData()
      await indexedDBService.cacheAllStaticData(staticData)
      
