// Worksデータの差分同期（バックグラウンド）
// 差分同期実行中フラグ
let isIncrementalSyncRunning = false

async function performIncrementalSync(syncReason = 'background') {
  // 既に実行中の場合はスキップ
  if (isIncrementalSyncRunning) {
    return
  }
  
  isIncrementalSyncRunning = true
  
  try {
    const worksLastSyncAt = await indexedDBService.getLastSyncTime('works')
    const favoritesLastSyncAt = await indexedDBService.getLastSyncTime('user_work_favorites')
    const staticDataLastSyncAt = await indexedDBService.getLastSyncTime('static_data')
    const templateWatchPayload = await indexedDBService.buildTemplateWatchPayload()
    const hasTemplateWatchBaseline = staticDataLastSyncAt ||
      Object.values(templateWatchPayload).some((entry) => entry?.since)
    
    // works / favorites / 静的データのいずれも未同期ならスキップ
    if (!worksLastSyncAt && !favoritesLastSyncAt && !hasTemplateWatchBaseline) return

    // タブアクセス時は「前回取得から30分以内」なら Edge Function を叩かない
    if (syncReason === 'tab') {
      const templateSyncTimes = await Promise.all([
        ...TEMPLATE_WATCH_TABLES.map((key) => indexedDBService.getLastSyncTime(key)),
        indexedDBService.getLastSyncTime('contractor_selections'),
        indexedDBService.getLastSyncTime('report_slot_template_items')
      ])
      const lastCandidates = [
        worksLastSyncAt,
        favoritesLastSyncAt,
        staticDataLastSyncAt,
        ...templateSyncTimes
      ]
        .filter(Boolean)
        .map(s => new Date(s).getTime())
        .filter(t => !Number.isNaN(t))

      if (lastCandidates.length > 0) {
        const lastCheckTs = Math.max(...lastCandidates)
        const within30Min = Date.now() - lastCheckTs < 30 * 60 * 1000
        if (within30Min) {
          works.value = await indexedDBService.getAllWorks()
          userWorkFavorites.value = await indexedDBService.getUserWorkFavorites()
          return
        }
      }
    }
    
    // アクセストークン取得
    const { data: { session } } = await supabaseClient.auth.getSession()
    if (!session) return
    
    await indexedDBService.syncUpdatedWorksAndFavorites(
      worksLastSyncAt,
      favoritesLastSyncAt,
      session.access_token,
      { includeTemplateWatch: hasTemplateWatchBaseline }
    )
    
    // UIを更新（差分の有無に関わらずIndexedDBから読み込む）
    works.value = await indexedDBService.getAllWorks()
    userWorkFavorites.value = await indexedDBService.getUserWorkFavorites()
  } catch (err) {
    console.error('Incremental sync failed:', err)
    // エラーは無視（次回の同期で再試行）
  } finally {
    isIncrementalSyncRunning = false
  }
}

// 静的データ読み込み済みフラグ
let staticDataLoaded = false

// 静的データフラグをリセット（外部から呼び出し可能）
function resetStaticDataFlag() {
  staticDataLoaded = false
}

// 静的データ（マスター + テンプレート + 価格表）読み込み
async function loadAllStaticData(forceReload = false) {
  // 既に読み込み済みで、強制再読み込みでない場合はスキップ
  if (staticDataLoaded && !forceReload) {
    return
  }
  
  try {
    const isCacheValid = await indexedDBService.isCacheValid('static_data')
    
    if (isCacheValid && !forceReload) {
      // キャッシュから読み込み
      await loadStaticDataFromCache()
    } else {
      // サーバーから取得
      await fetchAndCacheStaticData()
    }
    
    // 読み込み完了フラグを設定
    staticDataLoaded = true
  } catch (err) {
    console.error('Error loading static data:', err)
    // フォールバック: サーバーから直接取得
    try {
      await fetchAndCacheStaticData()
      staticDataLoaded = true
    } catch (fallbackErr) {
      console.error('Fallback also failed:', fallbackErr)
    }
  }
}

// 静的データをサーバーから取得してキャッシュ
async function fetchAndCacheStaticData() {
  try {
    const data = await supabaseService.getAllStaticData()
    
    // IndexedDBにキャッシュ
    await indexedDBService.cacheAllStaticData(data)
    
    // IndexedDBから読み込んでUIに反映（確実に保存されたデータを使用）
    employees.value = await indexedDBService.getMasterData('master_employees')
    mcs.value = await indexedDBService.getMasterData('master_mc')
    largeSteps.value = await indexedDBService.getMasterData('master_large_steps')
    largeJkkStatuses.value = await indexedDBService.getMasterData('master_large_jkk_statuses')
    largeProgressiveStatuses.value = await indexedDBService.getMasterData('master_large_progressive_statuses')
    smallJkkStatuses.value = await indexedDBService.getMasterData('master_small_jkk_statuses')
    smallProgressiveStatuses.value = await indexedDBService.getMasterData('master_small_progressive_statuses')
    userWorkFavorites.value = await indexedDBService.getUserWorkFavorites()
    housingDetails.value = await indexedDBService.getMasterData('housing_details')
    await reloadScheduleLabelTemplates()
  } catch (err) {
    console.error('❌ [HomePage] Failed to fetch static data from server:', err.message)
    
    try {
      await loadStaticDataFromCache()
    } catch (cacheErr) {
      console.error('❌ [HomePage] Cache fallback also failed:', cacheErr.message)
      // キャッシュもない場合、空配列で初期化（アプリが完全に停止しないように）
      employees.value = []
      mcs.value = []
      largeSteps.value = []
      largeJkkStatuses.value = []
      largeProgressiveStatuses.value = []
      smallJkkStatuses.value = []
      smallProgressiveStatuses.value = []
      userWorkFavorites.value = []
      housingDetails.value = []
    }
    
    // エラーを再スローしない（呼び出し元でエラーハンドリング済み）
  }
}

// 静的データをキャッシュから読み込み
async function loadStaticDataFromCache() {
  employees.value = await indexedDBService.getMasterData('master_employees')
