// バックグラウンド差分同期を開始
function startBackgroundSync() {
  // 既存のタイマーをクリア
  if (syncInterval) {
    clearInterval(syncInterval)
  }
  
  // 5分ごとに差分同期
  syncInterval = setInterval(() => {
    performIncrementalSync('background')
  }, 30 * 60 * 1000)
}

// バックグラウンド差分同期を停止
function stopBackgroundSync() {
  if (syncInterval) {
    clearInterval(syncInterval)
    syncInterval = null
  }
}

