async function restoreHomePageFilterState() {
  if (homePageFilterStateRestored) return
  homePageFilterStateRestored = true
  const saved = await indexedDBService.getHomePageState()
  if (!saved) return

  if (saved.filterSmall != null) filterSmall.value = saved.filterSmall
  if (saved.filterLarge != null) filterLarge.value = saved.filterLarge
  if (saved.filterYear != null) filterYear.value = saved.filterYear
  if (saved.filterMc != null) filterMc.value = saved.filterMc
