  if (saved.filterEmployeeId != null) filterEmployeeId.value = saved.filterEmployeeId
  if (saved.orderedOnSortMode != null) orderedOnSortMode.value = saved.orderedOnSortMode
  if (saved.superSearchQuery != null) superSearchQuery.value = saved.superSearchQuery
  if (Array.isArray(saved.superSearchWorkIds)) superSearchWorkIds.value = saved.superSearchWorkIds
  if (saved.isWorkTabFilterCollapsed != null) {
    isWorkTabFilterCollapsed.value = saved.isWorkTabFilterCollapsed
  } else if (saved.isFilterCollapsed != null) {
    isWorkTabFilterCollapsed.value = saved.isFilterCollapsed
