async function bootIfAuthedAndActive() {
  if (!props.isAuthenticated) return
  if (!props.isActive) return

  await restoreHomePageFilterState()

  // F5リロード時（自動認証時）はIndexedDBから読み込む必要がある
  if (!staticDataLoaded) {
    await loadAllStaticData(false) // forceReload=falseなので、キャッシュから読み込む
  }
  
  if (works.value.length === 0) {
    await loadWorks()
  }
  startBackgroundSync()
