// 担当者変更
async function handleEmployeeChange() {
  if (!selectedWork.value) return
  
  const workId = selectedWork.value.id
  const newEmployeeId = selectedWork.value.employee_id
  
  try {
    // 同期キューに追加（楽観的更新）
    const { syncQueueService, OperationType } = await import('../utils/syncQueue.js')
    
    await syncQueueService.addToQueue(
      workId,
      OperationType.UPDATE_EMPLOYEE,
      { employee_id: newEmployeeId }
    )
    await syncQueueService.updateWorksCache(workId, { employee_id: newEmployeeId })

    // ローカルの works 配列も更新
    const workIndex = works.value.findIndex(w => w.id === workId)
    if (workIndex !== -1) {
      works.value[workIndex].employee_id = newEmployeeId
    }
  } catch (err) {
    console.error('Failed to queue employee update:', err)
    error.value = `担当者の更新に失敗しました: ${err.message}`
  }
}

