async function selectWorkById(workId) {
  const id = String(workId ?? '')
  if (!id) return false

  let work = works.value.find((row) => String(row.id) === id)
  if (!work) {
    try {
      work = await indexedDBService.getWorkById(id)
    } catch (err) {
      console.warn('[HomePage] selectWorkById failed to load work:', err)
      work = null
    }
  }
  if (!work) return false

  await selectWork(work)
  return true
