  justify-content: center;
  width: 1.125rem;
  height: 1.125rem;
  color: #6b7280;
  pointer-events: none;
}

.work-item-step-mark-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.work-item--long-tree-row .work-item-label {
  display: block;
  min-width: 0;
}

.work-item--long-tree-row.active .work-item-step-mark {
  color: #1e40af;
}

.work-item--long-tree-row.status-in-progress .work-item-step-mark {
  color: #1e88e5;
}

.work-item--long-tree-row.status-adjusting .work-item-step-mark {
  color: #fb8c00;
}

.work-item--long-tree-row.status-done .work-item-step-mark {
  color: #9c6ade
}

.work-item--long-tree-row.status-completed .work-item-step-mark {
  color: #2e7d32;
}

.work-item--long-tree-row.status-cancelled .work-item-step-mark {
  color: #9e9e9e;
}

/* 登録タブのクリック可能な行 */
.work-item-clickable {
  cursor: pointer;
  user-select: none;
}

.work-item-clickable:hover {
  background: #f3f4f6;
}

/* 長期詳細があるwork-itemは赤文字（優先順位を上げる） */
.work-item.has-long-detail,
.work-item-clickable.has-long-detail {
  color: #dc2626 !important;
  font-weight: 500;
}

/* 工事状況による色分け（長期・小口共通） */
.work-item.status-adjusting {
  color: #fb8c00;
}

.work-item.status-in-progress {
  color: #1e88e5;
}

.work-item.status-done {
  color: #9c6ade;
}

.work-item.status-completed {
  color: #2e7d32;
}

.work-item.status-cancelled {
  color: #9e9e9e;
}

/* 工事完了予定日のグループヘッダー */
.date-group-header {
  padding: 0.375rem 0.5rem 0.375rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: #6b7280;
  background: #f9fafb;
  border-radius: 0.25rem;
  margin-bottom: 0.25rem;
}

/* work-details-container と same-housing-details-container */
.work-details-container,
.same-housing-details-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

/* ヘッダー固定 */
.work-details-header,
.same-housing-details-header {
  flex-shrink: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid #e5e7eb;
  margin-bottom: 1rem;
}

.same-housing-details-header-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin-left: auto;
  flex-shrink: 0;
}

/* スクロール可能エリア */
.work-details,
.same-housing-details {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
}

/* 同一住戸リストコンテナ */
.same-housing-list-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

.same-housing-list {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
}

.header-left-buttons {
  display: flex;
  gap: 0.4rem;
}

.star-button {
  padding: 0.5rem 0.5rem;
  border: 1px solid #fbbf24;
  border-radius: 0.375rem;
  background: white;
  color: #9ca3af;
  cursor: pointer;
  font-size: 1.5rem;
  font-weight: 500;
  transition: all 0.2s;
  line-height: 1;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.star-button:hover {
  background: #fffbeb;
  border-color: #f59e0b;
  color: #f59e0b;
}

.star-button.is-favorite {
  background: white;
  color: #fbbf24;
  border-color: #fbbf24;
}

.star-button.is-favorite:hover {
  background: #fffbeb;
  color: #f59e0b;
  border-color: #f59e0b;
}

/* スマホ版: ☆ボタンの幅を狭く */
@media (max-width: 768px) {
  .star-button {
    padding: 0.5rem 0.5rem;
  }
}

.same-housing-button {
  padding: 0.5rem 0.8rem;
  border: 1px solid #8b5cf6;
  border-radius: 0.375rem;
  background: #8b5cf6;
  color: white;
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  min-width: 55px;
  height: 38px;
}

.same-housing-button:hover {
  background: #7c3aed;
}

.edit-button,
.pdf-button {
  padding: 0.5rem 0.8rem;
  border: 1px solid #3b82f6;
  border-radius: 0.375rem;
  background: #3b82f6;
  color: white;
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 55px;
  height: 38px;
}

.edit-button:hover,
.pdf-button:hover {
  background: #2563eb;
}

.pdf-button {
  background: #10b981;
  border-color: #10b981;
  width: 55px;
  min-width: 55px;
  box-sizing: border-box;
}

.pdf-button:hover {
  background: #059669;
}

.pdf-button:disabled {
  background: #d1d5db;
  border-color: #d1d5db;
  cursor: not-allowed;
}

/* 工程スケジュール（large のみ） */
.schedule-calendar-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 55px;
  min-width: 55px;
  height: 38px;
  padding: 2px;
  box-sizing: border-box;
  border: 1px solid #9ca3af;
  border-radius: 0.375rem;
  background: #fff;
  color: #2563eb;
  cursor: pointer;
  --schedule-calendar-icon-hole: #fff;
}

.schedule-calendar-btn .schedule-calendar-icon--fill {
  width: 80%;
  height: 80%;
}

.schedule-calendar-btn:hover {
  background: #eff6ff;
  border-color: #6b7280;
  color: #1d4ed8;
  --schedule-calendar-icon-hole: #eff6ff;
}

.schedule-calendar-btn--no-data {
  color: #d1d5db;
  border-color: #9ca3af;
}

.schedule-calendar-btn--no-data:hover {
  background: #f9fafb;
  border-color: #6b7280;
  color: #9ca3af;
  --schedule-calendar-icon-hole: #f9fafb;
}

/* クラウドストレージへ（PC・案件選択時のみ） 幅は写真・見積ボタンと同じ 55px */
.cloud-storage-folder-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 55px;
  min-width: 55px;
  height: 38px;
  padding: 0;
  box-sizing: border-box;
  border: 1px solid #9ca3af;
  border-radius: 0.375rem;
  background: #fff;
  color: #ffc83d;
  cursor: pointer;
}

.cloud-storage-folder-btn svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.cloud-storage-folder-btn:hover {
  background: #fffbeb;
  border-color: #6b7280;
  color: #f5b800;
}

/* 物件詳細: 画像なし時はフォルダ線を黒（押下は可能） */
.cloud-storage-folder-btn--no-images {
  color: #d1d5db;
  border-color: #9ca3af;
}

.cloud-storage-folder-btn--no-images:hover {
  background: #f9fafb;
  border-color: #6b7280;
  color: #9ca3af;
}

.cloud-storage-folder-btn:disabled {
  background: #f3f4f6;
  border-color: #e5e7eb;
  color: #9ca3af;
  cursor: not-allowed;
}

.cloud-storage-folder-btn:disabled:hover {
  background: #f3f4f6;
  border-color: #e5e7eb;
  color: #9ca3af;
}

.pdf-select-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.pdf-select-modal-box {
  background: white;
  border-radius: 0.5rem;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
  max-width: 420px;
  width: 100%;
  padding: 1.5rem;
}

.pdf-select-modal-title {
  margin: 0 0 1rem;
  font-size: 1.125rem;
  font-weight: 600;
}

.pdf-select-modal-list {
  list-style: none;
  margin: 0 0 1rem;
  padding: 0;
  max-height: 60vh;
  overflow-y: auto;
}

.pdf-select-modal-item {
  padding: 0.75rem 1rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.375rem;
  margin-bottom: 0.5rem;
  cursor: pointer;
  background: #fff;
  font-size: 0.9rem;
}

.pdf-select-modal-item:hover {
  background: #eff6ff;
  border-color: #3b82f6;
}

.pdf-select-modal-item:last-child {
  margin-bottom: 0;
}

.pdf-select-modal-close {
  padding: 0.5rem 1rem;
  border-radius: 0.25rem;
  font-size: 0.9rem;
  cursor: pointer;
  background: #f3f4f6;
  color: #374151;
  border: 1px solid #e5e7eb;
  width: 100%;
}

.pdf-select-modal-close:hover {
  background: #e5e7eb;
}

.estimate-button {
  padding: 0.5rem 0.8rem;
  border: 1px solid #f59e0b;
  border-radius: 0.375rem;
  background: #f59e0b;
  color: white;
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 55px;
  height: 38px;
}

.estimate-button:hover {
  background: #d97706;
  border-color: #d97706;
}

.pdf-button:disabled:hover {
  background: #d1d5db;
}

.work-info,
.work-info-unified,
.work-details-section {
  padding: 1rem;
  background: #f9fafb;
  border-radius: 0.375rem;
}

.work-info-unified {
  margin-bottom: 1rem;
}

/* 横並び行 */
.info-row-horizontal {
  display: flex;
  gap: 2rem;
  margin-bottom: 0.75rem;
}

.info-row-horizontal .info-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* 場所用（大きめの文字） */
.info-field-location {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.info-label-large {
  font-weight: 500;
  color: #374151;
  white-space: nowrap;
  font-size: 1rem;
}

.info-value-large {
  color: #111827;
  font-size: 1.125rem;
  font-weight: 600;
}

/* 縦並び行 */
.info-row-vertical {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 0.75rem;
}

/* ノート用テキストエリア */
.note-textarea {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-family: inherit;
  font-size: 0.875rem;
  resize: vertical;
}

/* 工事状況セレクト */
.status-select {
  padding: 0.375rem 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  background: white;
  cursor: pointer;
}

/* 物件詳細: 横並び行のセレクトは幅を抑えてレイアウトずれを防ぐ */
.info-row-horizontal .info-field .status-select {
  width: auto;
  max-width: 10.5rem;
  min-width: 0;
  font-size: 0.8125rem;
  padding: 0.3125rem 0.4375rem;
}

.employee-controls {
  display: flex;
  align-items: stretch;
  gap: 0.375rem;
  flex-wrap: nowrap;
  min-width: 0;
  flex: 1;
}

.info-field--employee .employee-select {
  flex: 1 1 auto;
  min-width: 0;
  max-width: 10.5rem;
}

.info-field--large-step .large-step-select {
  max-width: 9.5rem;
}

.inspection-toggle-btn {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 0.625rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  background: #fff;
  color: #374151;
  font-size: 0.8125rem;
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
  box-sizing: border-box;
}

.inspection-toggle-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.inspection-toggle-btn--active {
  border-color: #dc2626;
  background: #fef2f2;
  color: #dc2626;
  font-weight: 600;
}

/* 長期詳細（編集UI） */
.long-detail-editor {
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px dashed #e5e7eb;
}
.long-detail-row {
  display: grid;
  grid-template-columns: 1fr 1fr; /* 右列（チェック）は中央からスタート */
  column-gap: 1rem;
  align-items: start; /* ラベル行を揃える */
}
.long-detail-field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1;
  min-width: 0;
}
.long-detail-check-cell {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}
.long-detail-input {
  width: 100%;
  max-width: none;
  height: 34px;
  padding: 0.25rem 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  background: white;
}
.long-detail-gap {
  margin-top: 0.75rem; /* 鍵渡し日との間を空ける */
}
.long-detail-check {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.875rem;
  color: #374151;
}
.long-detail-checkbox-line {
  height: 34px; /* 日付inputと同じ高さに揃える */
  display: flex;
  align-items: center;
  padding-left: 0.5rem; /* 半角スペース1つ分くらい右にずらす */
}
.long-detail-checkbox {
  width: 18px;
  height: 18px;
  accent-color: #111827;
}

.work-info h3,
.work-details-section h3 {
  margin: 0 0 1rem 0;
  font-size: 1.125rem;
  font-weight: 600;
}

.info-row {
  display: flex;
  padding: 0.5rem 0;
  border-bottom: 1px solid #e5e7eb;
}

.info-row:last-child {
  border-bottom: none;
}

.info-label {
  font-weight: 500;
  color: #6b7280;
  min-width: 120px;
}

.info-value {
  color: #374151;
  flex: 1;
}

.address-map-link {
  color: #2563eb;
  text-decoration: none;
}

.address-map-link:hover {
  text-decoration: underline;
}

.info-value-tel-link {
  color: #2563eb;
  text-decoration: none;
}

.info-value-tel-link:hover {
  text-decoration: underline;
}

.no-selection {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: #6b7280;
}

/* 右パネル: 同一住戸WORKS */
.right-panel-header {
  display: flex;
  justify-content: flex-start;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
}

.right-panel-header h2 {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
}

.back-button {
  padding: 0.375rem 0.75rem;
  border: 1px solid #6b7280;
  border-radius: 0.375rem;
  background: white;
  color: #374151;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 500;
}

.back-button:hover {
  background: #f3f4f6;
}

.same-housing-item {
  padding: 0.75rem;
  cursor: pointer;
  border-radius: 0.25rem;
  border: 1px solid #e5e7eb;
  margin-bottom: 0.5rem;
  background: white;
  transition: all 0.2s;
}

.same-housing-item:hover {
  background: #f3f4f6;
  border-color: #8b5cf6;
}

.same-housing-item.current-work {
  color: #9ca3af;
  background: #f9fafb;
}

/* 同一住戸情報の工事状況による色分け（左パネルと同じ） */
.same-housing-item.status-adjusting {
  color: #fb8c00;
}

.same-housing-item.status-in-progress {
  color: #1e88e5; /* 対応（工事状況=1）: 青 */
}
.same-housing-item.status-done {
  color: #9c6ade;
}

.same-housing-item.status-completed {
  color: #2e7d32; /* 完了（工事状況=4 または 公社状態=3 or 4）: 緑 */
}

.same-housing-item.status-cancelled {
  color: #9e9e9e; /* 取消（工事状況=5 または 公社状態=5）: グレー */
}

.same-housing-details .work-info-unified {
  padding: 1rem;
  background: #f9fafb;
  border-radius: 0.375rem;
  margin-bottom: 1rem;
}

.same-housing-details .billing-section {
  padding: 1rem;
  background: #f9fafb;
  border-radius: 0.375rem;
  margin-top: 1rem;
}

.back-to-list-button {
  padding: 0.375rem 0.75rem;
  border: 1px solid #6b7280;
  border-radius: 0.375rem;
  background: white;
  color: #374151;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 500;
}

.back-to-list-button:hover {
  background: #f3f4f6;
}

/* ヘッダー右側ボタングループ */
.header-right-buttons {
  display: flex;
  gap: 0.4rem;
  align-items: center;
}

/* テンプレート登録ボタン */
.favorite-button {
  padding: 0.5rem 0.8rem;
  border: 1px solid #f59e0b;
  border-radius: 0.375rem;
  background: #f59e0b;
  color: white;
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 55px;
  height: 38px;
}

.favorite-button:hover:not(:disabled) {
  background: #d97706;
  border-color: #d97706;
}

.favorite-button:disabled {
  background: #d1d5db;
  border-color: #d1d5db;
  color: #9ca3af;
  cursor: not-allowed;
}

/* 請求項目セクション */
.billing-section {
  padding: 1rem;
  background: #f9fafb;
  border-radius: 0.375rem;
  margin-top: 1rem;
}

.billing-section h3 {
  margin: 0 0 1rem 0;
  font-size: 1.125rem;
  font-weight: 600;
}

/* 合計金額を上部に表示 */
.billing-total-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  background: #eff6ff;
  border: 2px solid #93c5fd;
  border-radius: 0.375rem;
  margin-bottom: 1rem;
  font-size: 1.125rem;
  font-weight: 600;
}

.billing-total-top .total-label {
