  border-collapse: collapse;
  font-size: 0.875rem;
}

.billing-table th,
.billing-table td {
  padding: 0.5rem;
  border: 1px solid #e5e7eb;
  text-align: left;
}

.billing-table th {
  background: #f3f4f6;
  font-weight: 600;
  color: #374151;
  white-space: nowrap;
}

.billing-table tbody tr:hover {
