  color: #6b7280;
}

.billing-table .col-description {
  min-width: 200px;
}

.billing-table .col-quantity,
.billing-table .col-unit {
  min-width: 60px;
  text-align: center;
}

.billing-table .col-price,
.billing-table .col-amount {
  min-width: 100px;
  text-align: right;
}

.billing-table tfoot .total-label {
