  font-weight: 600;
  background: #f3f4f6;
}

.billing-table tfoot .total-amount {
  font-weight: 600;
  background: #fef3c7;
  color: #92400e;
}

/* フィルターエリア */
.filter-area {
  padding: 0.75rem;
  background: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.filter-area:has(.work-tab-filter-body) {
  gap: calc(0.5rem * 0.75);
}

/* 左パネル内タブ */
.left-panel-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 10px;
  border-bottom: 1px solid #e5e7eb;
}

/* スマホ版で3つのタブの場合 */
.left-panel-tabs.tabs-three {
  grid-template-columns: repeat(3, 1fr);
}

.left-panel-tab {
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #fff;
  padding: 6px 8px;
  cursor: pointer;
  font-size: 0.875rem;
  color: #374151;
}

.left-panel-tab.active {
  background: #eff6ff;
  border-color: #3b82f6;
  color: #2563eb;
}

.filter-area-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.filter-header-right-buttons {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  flex-shrink: 0;
}

.favorite-filter-toggle {
  width: 32px;
  height: 24px;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  background: white;
  color: #9ca3af;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1rem;
  transition: all 0.2s;
}

.favorite-filter-toggle:hover {
  background: #f3f4f6;
}

.favorite-filter-toggle.active {
  background: white;
  color: #fbbf24;
  border-color: #fbbf24;
}

/* favorite-filter-toggle と同寸（調査日ソート切替・filter-row 先頭） */
.chronology-sort-toggle {
  width: 32px;
  height: 28px;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  background: white;
  color: #4b5563;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 0;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}

.chronology-sort-toggle:hover {
  background: #f3f4f6;
}

.chronology-sort-toggle.is-active,
.chronology-sort-toggle.on-desc,
.chronology-sort-toggle.on-asc {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0284c7;
}

/* 検索タブ：小口・空家トグル（調査日ボタンと同高・同色） */
.filter-kind-toggle {
  width: auto;
  min-width: 2.25rem;
  padding: 0.1rem 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.chronology-sort-toggle-svg {
  width: 14px;
  height: 14px;
  display: block;
}

.filter-area-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: #374151;
}

.filter-collapse-btn {
  width: 32px;
  height: 24px;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  background: white;
  color: #374151;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.filter-collapse-btn:hover {
  background: #f3f4f6;
}

.filter-area-body {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.filter-area-body.work-tab-filter-body {
  gap: calc(0.5rem * 0.75);
}

/* 検索・小口・空家タブ：フィルター行レイアウト固定（PC） */
.work-tab-filter-body .work-filter-row {
  display: grid;
  gap: calc(0.5rem * 0.75);
  align-items: center;
}

.work-tab-filter-body .work-filter-row-group-top {
  display: grid;
  grid-template-columns: 32px 2.75rem 2.75rem 0.9fr 0.9fr 1.2fr;
  gap: calc(0.5rem * 0.75);
  align-items: center;
}

.work-tab-filter-body .work-filter-row-group-top .work-filter-row-1,
.work-tab-filter-body .work-filter-row-group-top .work-filter-row-2 {
  display: contents;
}

.work-tab-filter-body .work-filter-row-3 {
  grid-template-columns: 0.9fr 0.9fr 2.2fr;
}

.work-tab-filter-body .work-filter-row-4 {
  grid-template-columns: 1fr 1fr 32px;
}

.work-tab-filter-body .work-filter-row-5 {
  grid-template-columns: 1fr 1fr;
  min-height: 30px;
}

.work-tab-filter-body .work-filter-slot {
  min-width: 0;
}

.work-tab-filter-body .work-filter-slot .filter-select,
.work-tab-filter-body .work-filter-slot > .filter-input-wrapper {
  width: 100%;
}

.work-tab-filter-body .slot-chrono .chronology-sort-toggle {
  width: 100%;
}

.work-tab-filter-body .slot-kind-small,
.work-tab-filter-body .slot-kind-large {
  min-height: 28px;
}

.work-tab-filter-body .slot-kind-small .filter-kind-toggle,
.work-tab-filter-body .slot-kind-large .filter-kind-toggle {
  width: 100%;
  min-width: 0;
}

.work-tab-filter-body .slot-super-btn .super-search-btn {
  width: 100%;
  height: 30px;
  min-width: 0;
}

.work-tab-filter-body .filter-input-wrapper.filter-location,
.work-tab-filter-body .filter-input-wrapper.filter-detail,
.work-tab-filter-body .filter-input-wrapper.filter-super,
.work-tab-filter-body .filter-input-wrapper.filter-order-no {
  flex: none;
  width: 100%;
  min-width: 0;
}

.work-tab-filter-body .filter-input-wrapper.filter-order-no .filter-input::placeholder {
  font-size: calc(0.875rem * 0.95);
}

.work-tab-filter-body .filter-input-wrapper.filter-order-no .filter-input::-webkit-input-placeholder {
  font-size: calc(0.875rem * 0.95);
}

.work-tab-filter-body .filter-input {
  width: 100%;
}

.work-tab-filter-body .akiya-status-select {
  width: 100%;
}

.work-tab-filter-body .filter-select:disabled,
.work-tab-filter-body .filter-input:disabled {
  background: #d8d8d8;
  color: #374151;
  border-color: #b8bcc4;
  opacity: 1;
  cursor: not-allowed;
}

.work-tab-filter-body .chronology-sort-toggle:disabled,
.work-tab-filter-body .super-search-btn:disabled {
  background: #d8d8d8;
  color: #374151;
  border-color: #b8bcc4;
  opacity: 1;
  cursor: not-allowed;
}

.work-tab-filter-body .super-search-disabled-mark {
  font-size: 0.875rem;
  line-height: 1;
}

.work-tab-filter-body .chronology-sort-toggle.filter-kind-toggle:disabled.is-active {
  background: #c8ced6;
  border-color: #b8bcc4;
  color: #374151;
}

.akiya-status-selects {
  display: flex;
  gap: 0.5rem;
  flex: 1;
  min-width: 240px;
}

.akiya-status-select {
  flex: 1 1 0;
  min-width: 0;
}

.filter-row {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.filter-clear-all-btn {
  padding: 0 0.5rem;
  height: 24px;
  width: 32px;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  background: white;
  color: #9ca3af;
  font-size: 0.875rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.2s;
}

.filter-clear-all-btn:hover {
  color: #ef4444;
  background: #f3f4f6;
  border-color: #ef4444;
}

.filter-clear-all-btn:hover {
  color: #ef4444;
}

.filter-select {
  padding: 0.375rem 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  background: white;
  min-width: 80px;
  height: 30px;
}

.filter-select:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.date-range {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.date-range-full {
  width: 100%;
}

.date-range-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: #374151;
  white-space: nowrap;
}

.date-range-sep {
  color: #6b7280;
  font-size: 0.875rem;
  white-space: nowrap;
}

.filter-date {
  padding: 0.375rem 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  background: white;
  height: 30px;
  box-sizing: border-box;
}

.filter-date:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.filter-date-wide {
  flex: 1 1 0;
  min-width: 140px;
}

.small-action-btn {
  height: 30px;
  padding: 0 0.75rem;
  border-radius: 0.25rem;
  border: 1px solid #d1d5db;
  background: #fff;
  color: #374151;
  font-size: 0.8125rem;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
}

.small-action-btn:hover {
  background: #f3f4f6;
}

.small-action-btn.select-all {
  border-color: #3b82f6;
  background: #eff6ff;
  color: #2563eb;
}

.small-action-btn.clear-all {
  border-color: #ef4444;
  background: #fef2f2;
  color: #dc2626;
}

.works-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0.5rem 0;
}

.works-list .work-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  border-radius: 0.25rem;
  color: #374151;
  margin: 0 0.5rem 0.25rem 0.5rem;
}

.works-list .work-item:hover {
  background: #f3f4f6;
}

.work-item-checkbox {
  display: flex;
  align-items: center;
  margin-right: 0.25rem;
}

.work-item-checkbox input[type="checkbox"] {
  width: 16px;
  height: 16px;
}

.register-long-delete-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-right: 0.25rem;
  padding: 0.15rem 0.45rem;
  border: none;
  border-radius: 0.25rem;
  background: #ef4444;
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  flex-shrink: 0;
}

.register-long-delete-btn:hover:not(:disabled) {
  background: #dc2626;
}

.register-long-delete-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.bulk-date-column {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.bulk-date-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.bulk-date-input {
  flex: 1 1 0;
  min-width: 0;
  max-width: 33%;
}

.filter-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.filter-input-wrapper .filter-input {
  width: 100%;
  padding-right: 24px;
}

.filter-input-clear {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  background: #d1d5db;
  color: white;
  font-size: 10px;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.filter-input-clear:hover {
  background: #ef4444;
}

.filter-input {
  padding: 0.375rem 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  height: 30px;
  box-sizing: border-box;
}

.filter-input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.filter-input-wrapper.filter-location {
  flex: 2;
  min-width: 180px;
}

.filter-input-wrapper.filter-detail {
  flex: 1;
  min-width: 150px;
}

.filter-input-wrapper.filter-super {
  width: 200px;
  flex-shrink: 0;
}

.filter-input-wrapper.filter-super .filter-input {
  width: 100%;
  padding-right: 24px;
}

.super-search-btn {
  padding: 0.375rem 0.5rem;
  border: 1px solid #f59e0b;
  border-radius: 0.25rem;
  background: #f59e0b;
  color: white;
  font-size: 0.875rem;
  cursor: pointer;
  white-space: nowrap;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
}

.super-search-btn svg {
  display: block;
}

.super-search-btn:hover:not(:disabled) {
  background: #d97706;
  border-color: #d97706;
}

.super-search-btn:disabled {
  background: #d1d5db;
  border-color: #d1d5db;
  cursor: not-allowed;
}

.loading-dots {
  font-size: 12px;
  letter-spacing: 2px;
}

/* フラットリスト表示 */
.works-flat-list {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem 0;
}

.works-flat-list .work-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  cursor: pointer;
  border-radius: 0.25rem;
  color: #374151;
  margin: 0 0.5rem 0.25rem 0.5rem;
}

.works-flat-list .work-item:hover {
  background: #f3f4f6;
}

.works-flat-list .work-item.active {
  background: #dbeafe;
  font-weight: 500;
  /* color削除: 工事状況による色分けを優先 */
}

/* フラットリスト用: 工事状況による色分け */
.works-flat-list .work-item.status-adjusting {
  color: #fb8c00; /* 調整中: オレンジ */
}

.works-flat-list .work-item.status-in-progress {
  color: #1e88e5; /* 対応: 青 */
}

.works-flat-list .work-item.status-done {
  color: #9c6ade;
}

.works-flat-list .work-item.status-completed {
  color: #2e7d32; /* 完了: 緑 */
}

.works-flat-list .work-item.status-cancelled {
  color: #9e9e9e; /* 取消: グレー */
}

.work-kind-badge {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  font-weight: 500;
  white-space: nowrap;
}

.work-kind-badge.small {
  background: #dbeafe;
  color: #1e40af;
}

.work-kind-badge.large {
  background: #fef3c7;
  color: #92400e;
}

.work-kind-badge.long {
  background: #ede9fe;
  color: #5b21b6;
}

.work-year-badge {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  font-weight: 500;
  white-space: nowrap;
  background: #e0e7ff;
  color: #3730a3;
}

.work-mc-badge {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  font-weight: 500;
  white-space: nowrap;
  background: #d1fae5;
  color: #065f46;
}

.work-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* iPhone SE 向け: 1画面1パネル表示のため、固定幅を解除 */
@media (max-width: 900px) {
  .home-content {
    flex-direction: column;
  }
  .left-panel,
  .center-panel,
  .right-panel {
    width: 100%;
    flex: 1;
    border-right: none;
    padding: 0.75rem;
  }

  /* 検索・小口・空家フィルター：スマホ5行レイアウト */
  .work-tab-filter-body .work-filter-row-group-top {
    display: flex;
    flex-direction: column;
    gap: calc(0.5rem * 0.75);
  }

  .work-tab-filter-body .work-filter-row-group-top .work-filter-row-1,
  .work-tab-filter-body .work-filter-row-group-top .work-filter-row-2 {
    display: grid;
  }

  .work-tab-filter-body .work-filter-row-1 {
    grid-template-columns: 32px 1fr 1fr;
  }

  .work-tab-filter-body .work-filter-row-2 {
    grid-template-columns: 0.9fr 0.9fr 1.2fr;
  }

  .work-tab-filter-body .work-filter-row-3 {
    grid-template-columns: 1fr 1fr 2fr;
  }

  .work-tab-filter-body .work-filter-row-4 {
    grid-template-columns: 1fr 1fr 32px;
  }

  .work-tab-filter-body .work-filter-row-5 {
    grid-template-columns: 1fr 1fr;
  }

  .left-panel {
    min-width: unset; /* PC版のmin-widthを無効化 */
    max-width: unset; /* PC版のmax-widthを無効化 */
    border-bottom: 1px solid #e5e7eb;
  }

  /* 物件詳細：PCの2列レイアウトをスマホでは1列にする（縦位置合わせ不要） */
  .info-row-horizontal {
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 0.75rem;
  }
  .info-row-horizontal .info-field {
    flex: none;
    width: 100%;
    flex-direction: column; /* ラベル→入力の縦並び（必ず1列） */
    align-items: stretch;
    gap: 0.25rem;
  }
  .info-label {
    min-width: 0;
  }
  .status-select {
    width: 100%;
  }
  .info-row-horizontal .info-field .status-select {
    max-width: none;
    font-size: 0.875rem;
    padding: 0.375rem 0.5rem;
  }

  .info-field--employee .employee-controls {
    flex-direction: row;
    flex-wrap: nowrap;
  }
  .info-field--employee .employee-controls .employee-select {
    width: auto;
    flex: 1 1 auto;
    min-width: 0;
    max-width: none;
  }

  /* 長期詳細の日付入力は工事状況セレクトと同じく親幅いっぱい（date の既定 min-width を打ち消す） */
  .long-detail-input {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
  }

  /* 長期詳細の2列グリッドもスマホは1列 */
  .long-detail-row {
    grid-template-columns: 1fr;
    row-gap: 0.5rem;
  }
  .long-detail-check-cell {
    padding-left: 0;
  }

  /* 長期チェック3つを横並び */
  .long-detail-checkboxes {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    align-items: center;
    margin-top: 0.5rem;
  }
  .long-detail-checkbox-item {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.875rem;
    color: #374151;
    white-space: nowrap;
  }

  .work-details-header {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 0.2rem;
    align-items: stretch;
  }

  .header-left-buttons,
  .header-right-buttons {
    display: contents;
  }

  .back-button,
  .edit-button,
  .pdf-button,
  .estimate-button,
  .favorite-button,
  .cloud-storage-folder-btn,
  .schedule-calendar-btn,
  .star-button,
  .same-housing-button {
    width: 100%;
    min-width: 0;
    padding-left: 0.35rem;
    padding-right: 0.35rem;
  }

  /* 同一住戸: 戻る・一覧に戻る・PDF はラベル幅に追従（7 列グリッドの均等セル割り当てを使わない） */
  .right-panel-header .back-button {
    width: auto;
    min-width: unset;
    align-self: flex-start;
  }

  .same-housing-details-header {
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .same-housing-details-header .back-to-list-button,
  .same-housing-details-header .pdf-button {
    width: auto;
    min-width: unset;
    flex: 0 0 auto;
  }

  .same-housing-details-header-actions {
    margin-left: auto;
  }

  .same-housing-details-header-actions .pdf-button,
  .same-housing-details-header-actions .cloud-storage-folder-btn {
    width: 55px;
    min-width: 55px;
    flex: 0 0 auto;
  }

  /* iPhone Safari の入力フォーカス時ズーム対策（font-size < 16px を避ける） */
  .filter-area input,
  .filter-area select,
  .filter-area textarea,
  .filter-input,
  .filter-select,
  .status-select,
  .long-detail-input,
  .note-textarea {
    font-size: 16px !important;
  }

  /* 検索結果（フラットリスト）の表示調整：
     空/小↔年度、年度↔MC の間隔をゼロにし、名前だけ少し空ける */
  .works-flat-list .work-item {
    gap: 0;
  }
  .works-flat-list .work-name {
    margin-left: 0.5rem;
  }
}

/* 仮work一覧の削除ボタン */
.temp-work-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
}

.temp-work-delete-btn {
  padding: 0.25rem 0.5rem;
  background: #dc2626;
  color: white;
  border: none;
  border-radius: 0.25rem;
  font-size: 0.75rem;
  cursor: pointer;
  transition: background 0.2s;
}

.temp-work-delete-btn:hover {
  background: #b91c1c;
}

/* 空家仮追加フォーム */
.temp-work-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.temp-work-field {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.temp-work-field .info-label {
  font-weight: 500;
  font-size: 0.875rem;
