export const BOARD_FIELD_KEYS = ['projectName', 'companyName', 'siteName', 'subject']

function cloneFieldLayout(layout) {
  const o = {}
  for (const key of Object.keys(layout)) {
    o[key] = { ...layout[key] }
  }
  return o
}

function cloneFixedTexts(arr) {
  return arr.map((box) => ({ ...box }))
}

/** getUserMedia の ideal（1280×960）相当を想定した基準。プリセット width/height はこの解像度でのビデオ上ピクセル寸法として定義する */
export const BOARD_VIDEO_SPACE_REF = { width: 1280, height: 960 }

/**
 * 黒板の固定サイズプリセット。
 * width / height … ビデオフレーム上のピクセル（videoWidth×videoHeight 基準）。240×180 は 1280×960 時の目安。
 * プレビューでは枠内 contain と同じ倍率 min(枠W/vw, 枠H/vh) で CSS px に換算する。
 *
 * templatePublicFile:
 *   public/board-templates/ 以下のファイル名。例: 'board-240.png'
 *   未設定・null のときは既定の board.png（assets + public）を使用。
 *
 * templateRef:
 *   上記 PNG のピクセルサイズ。fieldLayout / fixedTexts の座標はこのサイズ基準。
 *   未設定のときは BOARD_TEMPLATE_REF.default（1280×960）
 */
export const BOARD_SIZE_PRESETS = [
  {
    id: '320x240',
    width: 320,
    height: 240,
    templatePublicFile: null,
    templateRef: null,
    fieldLayout: cloneFieldLayout(BOARD_FIELD_LAYOUT.default),
    fixedTexts: cloneFixedTexts(BOARD_FIXED_TEXTS.default)
  },
  {
    id: '400x300',
    width: 400,
    height: 300,
    templatePublicFile: null,
    templateRef: null,
    fieldLayout: cloneFieldLayout(BOARD_FIELD_LAYOUT.default),
    fixedTexts: cloneFixedTexts(BOARD_FIXED_TEXTS.default)
  },
  {
    id: '520x390',
    width: 520,
    height: 390,
    templatePublicFile: null,
    templateRef: null,
    fieldLayout: cloneFieldLayout(BOARD_FIELD_LAYOUT.default),
    fixedTexts: cloneFixedTexts(BOARD_FIXED_TEXTS.default)
  }
]

/** @param {string} id */
export function getBoardSizePresetById(id) {
  return BOARD_SIZE_PRESETS.find((p) => p.id === id) ?? BOARD_SIZE_PRESETS[1]
}

/**
 * プリセット／保存データの fieldLayout に textFitMode 等が欠けていても BOARD_FIELD_LAYOUT.default で補完する。
 */
export function mergeBoardFieldLayoutWithDefaults(layout) {
  const base = BOARD_FIELD_LAYOUT.default
  if (!layout || typeof layout !== 'object') {
    return cloneFieldLayout(base)
  }
  const out = {}
  for (const key of BOARD_FIELD_KEYS) {
    const b = base[key]
    const l = layout[key]
    if (!b && !l) continue
    out[key] = { ...(b || {}), ...(l || {}) }
  }
  return out
}

/**
 * 合成・再描画用。board.boardPresetId を優先。旧データは default レイアウト。
 * @param {{ boardPresetId?: string, layoutWidth?: number, layoutHeight?: number } | null | undefined} board
 */
export function resolveBoardDrawParts(board) {
  const fromPreset = (p) => ({
    fieldLayout: mergeBoardFieldLayoutWithDefaults(p.fieldLayout),
    fixedTexts: p.fixedTexts,
    templatePublicFile: p.templatePublicFile || null,
    templateRef:
      p.templateRef && typeof p.templateRef.width === 'number' && typeof p.templateRef.height === 'number'
        ? { width: p.templateRef.width, height: p.templateRef.height }
        : null
  })
  if (board?.boardPresetId) {
    const p = BOARD_SIZE_PRESETS.find((x) => x.id === board.boardPresetId)
    if (p) return fromPreset(p)
  }
  return {
    fieldLayout: mergeBoardFieldLayoutWithDefaults(BOARD_FIELD_LAYOUT.default),
    fixedTexts: BOARD_FIXED_TEXTS.default,
    templatePublicFile: null,
    templateRef: null
  }
}
