/** file_id NULL のプレーン補足バケット用 room_label_order（room_labels.sort_order 0 等と衝突しない値） */
export const SUPPLEMENT_ROOM_LABEL_ORDER = 99

/**
 * 施工前後セレクトの補足用 value（数値 99 だと 0,1,… の後に並ぶブラウザ対策）
 * 空白('')の直後・実ルーム('0'…)の前になる文字
 */
export const BACMP_SELECT_VALUE_SUPPLEMENT = '-'

/** プレーン補足バケット（__null_file__）として扱う order */
export function isSupplementRoomLabelOrder(ord) {
  if (ord === null || ord === undefined || ord === '') return false
  const n = Number(ord)
  return Number.isFinite(n) && n === SUPPLEMENT_ROOM_LABEL_ORDER
}

/** ルームラベル一覧から除外する sort_order（補足予約のみ） */
export function isReservedSupplementRoomLabelOrder(ord) {
  return isSupplementRoomLabelOrder(ord)
}

/** 施工前後ルームセレクト: 空白 → 補足(99) → 実ルーム（sort_order 昇順） */
export function buildBacmpRoomLabelSelectOptions(roomLabels) {
  const roomOpts = []
  for (const r of roomLabels || []) {
    const ord = Number(r?.sort_order)
    if (!Number.isFinite(ord) || isReservedSupplementRoomLabelOrder(ord)) continue
    const lbl = String(r?.label ?? '').trim()
    if (!lbl) continue
    roomOpts.push({ value: ord, label: lbl })
  }
  roomOpts.sort((a, b) => Number(a.value) - Number(b.value))
  return [
    { value: null, label: '\u00A0' },
    { value: SUPPLEMENT_ROOM_LABEL_ORDER, label: '補足' },
    ...roomOpts
  ]
}

export function bacmpSelectOptionValue(opt) {
  if (opt?.value === null || opt?.value === undefined) return ''
  if (Number(opt.value) === SUPPLEMENT_ROOM_LABEL_ORDER) return BACMP_SELECT_VALUE_SUPPLEMENT
  return String(opt.value)
}

export function bacmpRoomLabelOrderFromSelectValue(raw) {
  if (raw === '' || raw === null || raw === undefined) return null
  if (raw === BACMP_SELECT_VALUE_SUPPLEMENT) return SUPPLEMENT_ROOM_LABEL_ORDER
  const n = Number(raw)
  return Number.isFinite(n) ? n : null
}
