  async cacheAllStaticData(data) {
    try {
      // マスターデータ
      const masterRecords = [
        ...this.formatMasterData('master_employees', data.employees),
        ...this.formatMasterData('master_mc', data.mc),
        ...this.formatMasterData('master_large_steps', data.largeSteps),
        ...this.formatMasterData('master_large_jkk_statuses', data.largeJkkStatuses),
        ...this.formatMasterData('master_large_progressive_statuses', data.largeProgressiveStatuses),
        ...this.formatMasterData('master_small_jkk_statuses', data.smallJkkStatuses),
        ...this.formatMasterData('master_small_progressive_statuses', data.smallProgressiveStatuses),
        ...this.formatMasterData('master_work_phases', data.workPhases || []),
        ...this.formatMasterData('master_price_categories', data.priceCategories || []),
        ...this.formatMasterData('housing_details', data.housingDetails || []),
        ...this.formatMasterData('master_work_schedule_statuses', data.workScheduleStatuses || [])
      ]
      await this.master_data.bulkPut(masterRecords)
      
      // テンプレートデータ
      // custom_note_snippetsからcustom_note_snippet_itemsを展開
      const customNoteSnippetItems = []
      const customNoteSnippets = (data.customNoteSnippets || []).map(snippet => {
        // ネストされたitemsを展開して別テーブルに保存
        if (snippet.custom_note_snippet_items && Array.isArray(snippet.custom_note_snippet_items)) {
          customNoteSnippetItems.push(...snippet.custom_note_snippet_items)
        }
        // custom_note_snippet_itemsプロパティを削除してスニペット本体を保存
        const { custom_note_snippet_items, ...snippetWithoutItems } = snippet
        return snippetWithoutItems
      })

      // estimate_slot_templates から estimate_slot_template_items を展開
      // get_static_data の全取得ではネスト名が estimate_slot_template_items になるため両対応する
      const estimateSlotTemplateItems = []
      const estimateSlotTemplates = (data.estimateSlotTemplates || []).map(tpl => {
        const nestedItems =
          (tpl && Array.isArray(tpl.estimate_slot_template_items) && tpl.estimate_slot_template_items) ||
          (tpl && Array.isArray(tpl.items) && tpl.items) ||
          []

        if (nestedItems.length > 0) {
          estimateSlotTemplateItems.push(...nestedItems)
        }

        const { estimate_slot_template_items, items, ...tplWithoutItems } = tpl || {}
        return tplWithoutItems
      })
      
      const templateRecords = [
        ...this.formatTemplateData('custom_note_snippets', customNoteSnippets),
        ...this.formatTemplateData('custom_note_snippet_items', customNoteSnippetItems),
        ...this.formatTemplateData('estimate_slot_templates', estimateSlotTemplates),
        ...this.formatTemplateData('estimate_slot_template_items', estimateSlotTemplateItems),
        ...this.formatTemplateData('report_slot_templates', data.reportSlotTemplates),
        ...this.formatTemplateData('room_label_templates', data.roomLabelTemplates),
        ...this.formatTemplateData('schedule_label_templates', data.scheduleLabelTemplates || []),
        ...this.formatTemplateData('contractors', data.contractors),
        ...this.formatTemplateData('contractor_selections', (data.contractorSelections || []).map(r => ({
          ...r,
          id: `${r.user_profile_id}_${r.contractor_id}`
        }))),
        ...this.formatTemplateData('excel_templates', data.excelTemplates || [])
      ]

      // templates ストアは全テンプレが混在するため、サーバー側で削除されたものや
      // temp_id（楽観的追加）が残ると「削除したのに出る」「二重に見える」が起きる。
      // なので full static 取得時は対象 table_name を毎回全削除 → 置き換えする。
      const templateTableNames = Array.from(new Set([
        ...templateRecords.map(r => r.table_name),
        'contractor_selections',
        'billing_templates'
      ]))
      await Promise.all(
        templateTableNames.map(tableName =>
          this.templates.where('table_name').equals(tableName).delete()
        )
      )

      await this.templates.bulkPut(templateRecords)

      // template_watch 用: テーブルごとの同期メタデータ
      await this.updateSyncMetadata('contractors', (data.contractors || []).length, 'full')
      await this.updateSyncMetadata(
        'contractor_selections',
        (data.contractorSelections || []).length,
        'full'
      )
      await this.updateSyncMetadata('estimate_slot_templates', estimateSlotTemplates.length, 'full')
      await this.updateSyncMetadata('room_label_templates', (data.roomLabelTemplates || []).length, 'full')
      await this.updateSyncMetadata('report_slot_templates', (data.reportSlotTemplates || []).length, 'full')
      await this.updateSyncMetadata(
        'schedule_label_templates',
        (data.scheduleLabelTemplates || []).length,
        'full'
      )
      
      // 価格表データ
      const priceListRecords = [
        ...this.formatPriceListData('price_lists', data.priceLists),
        ...this.formatPriceListData('price_list_items', data.priceListItems)
      ]
      await this.price_lists.bulkPut(priceListRecords)
      
      // ユーザーワークお気に入りデータ
      if (data.userWorkFavorites && Array.isArray(data.userWorkFavorites)) {
        await this.user_work_favorites.clear()
        await this.user_work_favorites.bulkPut(data.userWorkFavorites)
        
        // お気に入りデータの同期メタデータを更新
        await this.updateSyncMetadata('user_work_favorites', data.userWorkFavorites.length, 'full')
      }
      
      // 同期メタデータ更新
      await this.updateSyncMetadata(
        'static_data', 
        masterRecords.length + templateRecords.length + priceListRecords.length, 
        'full'
      )
    } catch (error) {
      console.error('Error caching static data:', error)
      throw error
    }
  }
  
