  async getTemplates(tableName, userProfileId) {
    if (!userProfileId) {
      return await this.templates
        .where('table_name')
        .equals(tableName)
        .and(t => t.deleted_at === null || t.deleted_at === undefined)
        .toArray()
    }
    
    return await this.templates
      .where('table_name')
      .equals(tableName)
      .and(t => {
        // user_profile_idがないテーブル（custom_note_snippet_itemsなど）も含める
        const hasNoUserProfileId = t.user_profile_id === undefined
        const matchesUserProfileId = t.user_profile_id === userProfileId
        const notDeleted = t.deleted_at === null || t.deleted_at === undefined
        
        return (hasNoUserProfileId || matchesUserProfileId) && notDeleted
      })
      .toArray()
  }
  
