  /** template_watch リクエスト用: 各テーブルの since */
  async buildTemplateWatchPayload() {
    const staticSince = await this.getLastSyncTime('static_data')
    const payload = {}

    for (const tableName of TEMPLATE_WATCH_TABLES) {
      const since = (await this.getLastSyncTime(tableName)) || staticSince || null

      if (tableName === 'contractors') {
        payload.contractors = {
          since,
          contractor_selections: {
            since: (await this.getLastSyncTime('contractor_selections')) || staticSince || null
          }
        }
        continue
      }

      if (tableName === 'report_slot_templates') {
        payload.report_slot_templates = {
          since,
          report_slot_template_items: {
            since: (await this.getLastSyncTime('report_slot_template_items')) || staticSince || null
          }
        }
        continue
      }

      payload[tableName] = { since }
    }

    return payload
  }

  /** template_watch で changed になったテーブルを get_static_data 経由で全置換 */
  async refreshChangedTemplates(templateWatchResult) {
    if (!templateWatchResult || typeof templateWatchResult !== 'object') {
      return { refreshed: [] }
    }

    const changed = TEMPLATE_WATCH_TABLES.filter(
      (table) => templateWatchResult[table]?.changed === true
    )
    if (changed.length === 0) {
      return { refreshed: [] }
    }

    const { supabaseService } = await import('../services/supabase.js')
    await supabaseService.refreshWatchedTemplates(changed)

    const serverTime = new Date().toISOString()
    for (const tableName of changed) {
      const info = templateWatchResult[tableName]
      const syncedAt = info?.max_updated_at || serverTime
      const existing = await this.sync_metadata.get(tableName)
      await this.sync_metadata.put({
        key: tableName,
        last_sync_at: syncedAt,
        last_full_sync_at: syncedAt,
        cache_expires_at: this.addHours(serverTime, 24),
        record_count: existing?.record_count ?? 0,
        sync_strategy: 'full'
      })
      if (tableName === 'contractors') {
        const selSyncedAt = info?.contractor_selections?.max_updated_at || syncedAt
        const selExisting = await this.sync_metadata.get('contractor_selections')
        await this.sync_metadata.put({
          key: 'contractor_selections',
          last_sync_at: selSyncedAt,
          last_full_sync_at: selSyncedAt,
          cache_expires_at: this.addHours(serverTime, 24),
          record_count: selExisting?.record_count ?? 0,
          sync_strategy: 'full'
        })
      }
      if (tableName === 'report_slot_templates') {
        const itemsSyncedAt = info?.report_slot_template_items?.max_updated_at || syncedAt
        const itemsExisting = await this.sync_metadata.get('report_slot_template_items')
        await this.sync_metadata.put({
          key: 'report_slot_template_items',
          last_sync_at: itemsSyncedAt,
          last_full_sync_at: itemsSyncedAt,
          cache_expires_at: this.addHours(serverTime, 24),
          record_count: itemsExisting?.record_count ?? 0,
          sync_strategy: 'full'
        })
      }
    }

    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('template-watch-refreshed', {
        detail: { changed }
      }))
    }

    return { refreshed: changed }
  }
  
  // Works・お気に入り・template_watch を1回のリクエストで実行
  async syncUpdatedWorksAndFavorites(worksLastSyncAt, favoritesLastSyncAt, accessToken, options = {}) {
    const { includeTemplateWatch = true } = options
    try {
      const body = {
        data_type: 'all',
        works_last_sync_at: worksLastSyncAt,
        favorites_last_sync_at: favoritesLastSyncAt
      }

      if (includeTemplateWatch) {
        body.template_watch = await this.buildTemplateWatchPayload()
      }

      const response = await fetch(
        `${SUPABASE_URL}/functions/v1/check_work_update`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${accessToken}`,
            'apikey': import.meta.env.VITE_SUPABASE_ANON_KEY
          },
          body: JSON.stringify(body)
        }
      )
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }
      
      const result = await response.json()
      
      // Worksの処理
      let worksResult = { updated: 0, deleted: 0 }
      if (result.works && worksLastSyncAt) {
        const { updated_records, deleted_ids } = result.works
        
        // 削除されたレコードを削除
        if (deleted_ids && deleted_ids.length > 0) {
          await this.works.bulkDelete(deleted_ids)
        }
        
        // 更新されたレコードを保存
        // deleted_atがnullかつhousing_detail_idが存在するもののみ保存
        const activeRecords = (updated_records || []).filter(r => !r.deleted_at && r.housing_detail_id != null)
        if (activeRecords.length > 0) {
          await this.works.bulkPut(activeRecords)
        }
        
        await this.updateSyncMetadata('works', null, 'incremental')
        
        worksResult = {
          updated: activeRecords.length,
          deleted: deleted_ids ? deleted_ids.length : 0
        }
      }
      
      // お気に入りの処理
      let favoritesResult = { updated: 0, deleted: 0 }
      if (result.user_work_favorites && favoritesLastSyncAt) {
        const { updated_records, deleted_ids } = result.user_work_favorites
        
        // 削除されたレコードを削除
        if (deleted_ids && deleted_ids.length > 0) {
          await this.user_work_favorites.bulkDelete(deleted_ids)
        }
        
        // 更新されたレコードを保存（deleted_atがnullのもののみ）
        const activeRecords = (updated_records || []).filter(r => !r.deleted_at)
        if (activeRecords.length > 0) {
          await this.user_work_favorites.bulkPut(activeRecords)
        }
        
        await this.updateSyncMetadata('user_work_favorites', null, 'incremental')
        
        favoritesResult = {
          updated: activeRecords.length,
          deleted: deleted_ids ? deleted_ids.length : 0
        }
      }

      let templatesResult = { refreshed: [] }
      if (result.template_watch) {
        templatesResult = await this.refreshChangedTemplates(result.template_watch)
      }
      
      return {
        works: worksResult,
        favorites: favoritesResult,
        templates: templatesResult
      }
    } catch (error) {
      console.error('Error syncing updated works and favorites:', error)
      throw error
    }
  }
  
