  // ========================================
  // 同期メタデータ
  // ========================================
  
  async updateSyncMetadata(key, recordCount, strategy) {
    const now = new Date().toISOString()
    const existing = await this.sync_metadata.get(key)
    
    await this.sync_metadata.put({
      key,
      last_sync_at: now,
      last_full_sync_at: strategy === 'full' ? now : (existing?.last_full_sync_at || now),
      cache_expires_at: this.addHours(now, 24),
      record_count: recordCount ?? existing?.record_count ?? 0,
      sync_strategy: strategy
    })
  }
  
  async isCacheValid(key) {
    const metadata = await this.sync_metadata.get(key)
    if (!metadata) return false
    
    const now = new Date()
    const expiresAt = new Date(metadata.cache_expires_at)
    return now < expiresAt
  }
  
  async getLastSyncTime(key) {
    const metadata = await this.sync_metadata.get(key)
    return metadata?.last_sync_at || null
  }
  
  addHours(isoString, hours) {
    const date = new Date(isoString)
    date.setHours(date.getHours() + hours)
    return date.toISOString()
  }
  
