  async getStorageStats() {
    try {
      const stats = {
        works: await this.works.count(),
        master_data: await this.master_data.count(),
        templates: await this.templates.count(),
        price_lists: await this.price_lists.count(),
        sync_metadata: await this.sync_metadata.count()
      }
      
      stats.total = stats.works + stats.master_data + stats.templates + stats.price_lists + stats.sync_metadata
      
      // ブラウザのストレージ使用量
      if (navigator.storage && navigator.storage.estimate) {
        const estimate = await navigator.storage.estimate()
        stats.usage_bytes = estimate.usage
        stats.quota_bytes = estimate.quota
        stats.usage_mb = (estimate.usage / 1024 / 1024).toFixed(2)
        stats.quota_mb = (estimate.quota / 1024 / 1024).toFixed(2)
        stats.percent_used = ((estimate.usage / estimate.quota) * 100).toFixed(2)
      }
      
      return stats
    } catch (error) {
      console.error('Error getting storage stats:', error)
      throw error
    }
  }
  
