  async getSyncInfo() {
    const metadata = await this.sync_metadata.toArray()
    
    const info = {}
    for (const item of metadata) {
      info[item.key] = {
        last_sync_at: item.last_sync_at,
        last_full_sync_at: item.last_full_sync_at,
        cache_expires_at: item.cache_expires_at,
        record_count: item.record_count,
        sync_strategy: item.sync_strategy,
        is_valid: new Date() < new Date(item.cache_expires_at)
      }
    }
    
    return info
  }
  
