  /**
   * お気に入りデータを取得
   * @returns {Array} お気に入りの配列
   */
  async getUserWorkFavorites() {
    return await this.user_work_favorites
      .filter(f => !f.deleted_at)  // nullまたはundefinedの場合に含める
      .toArray()
  }
  
  /**
   * 特定のワークがお気に入りかチェック
   * @param {string} workId - Work ID
   * @returns {boolean} お気に入りならtrue
   */
  async isFavorite(workId) {
    const favorite = await this.user_work_favorites
      .where('work_id')
      .equals(workId)
      .and(f => !f.deleted_at)  // nullまたはundefinedの場合に含める
      .first()
    return !!favorite
  }
  
  /**
   * お気に入りを追加（ローカルのみ）
   * @param {string} favoriteId - お気に入りID
   * @param {string} workId - Work ID
   */
  async addFavorite(favoriteId, workId) {
    await this.user_work_favorites.put({
      id: favoriteId,
      work_id: workId,
      updated_at: new Date().toISOString()
    })
  }
  
  /**
   * お気に入りを削除（ローカルのみ）
   * @param {string} workId - Work ID
   */
  async removeFavorite(workId) {
    await this.user_work_favorites
      .where('work_id')
      .equals(workId)
      .delete()
  }
  
  /**
   * すべてのお気に入りをクリア
   */
  async clearAllFavorites() {
    await this.user_work_favorites.clear()
  }
  
  /**
   * ユーザープロフィールをキャッシュに保存
   * @param {Object} profileData - ユーザープロフィールデータ
   */
  async cacheUserProfile(profileData) {
    try {
      await this.user_profile.put({
        key: 'current',
        ...profileData,
        cached_at: new Date().toISOString()
      })
    } catch (error) {
      console.error('Error caching user profile:', error)
      throw error
    }
  }
  
  /**
   * キャッシュからユーザープロフィールを取得
   * @param {number} maxAgeHours - キャッシュの有効期限（時間、デフォルト24時間）
   * @returns {Object|null} - ユーザープロフィールデータ、またはnull
   */
  async getUserProfile(maxAgeHours = 24) {
    try {
      const cached = await this.user_profile.get('current')
      if (!cached) {
        return null
      }
      
      // キャッシュの有効期限をチェック
      const cachedAt = new Date(cached.cached_at)
      const now = new Date()
      const ageHours = (now - cachedAt) / (1000 * 60 * 60)
      
      if (ageHours > maxAgeHours) {
        // 有効期限切れの場合は削除してnullを返す
        await this.user_profile.delete('current')
        return null
      }
      
      // cached_atを除いて返す
      const { key, cached_at, ...profileData } = cached
      return profileData
    } catch (error) {
      console.error('Error getting user profile from cache:', error)
      return null
    }
  }
  
  /**
   * ユーザープロフィールのキャッシュをクリア
   */
  async clearUserProfileCache() {
    try {
      await this.user_profile.delete('current')
    } catch (error) {
      console.error('Error clearing user profile cache:', error)
    }
  }

