/** 材工A判定: 90000000 以上の単価コードは対象外 */
export const MATERIAL_LABOR_CODE_CEILING = 90000000

export function normalizePriceCode(value) {
  if (!value) return ''
  let normalized = String(value).replace(/[Ａ-Ｚａ-ｚ]/g, (s) =>
    String.fromCharCode(s.charCodeAt(0) - 0xfee0)
  )
  normalized = normalized.replace(/[０-９]/g, (s) =>
    String.fromCharCode(s.charCodeAt(0) - 0xfee0)
  )
  normalized = normalized.toUpperCase().replace(/[^A-Z0-9]/g, '')
  return normalized
}

export function parsePriceCodeNumber(code) {
  const norm = normalizePriceCode(code)
  if (!norm || !/^\d+$/.test(norm)) return null
  const n = Number(norm)
  return Number.isFinite(n) ? n : null
}

/** 90000000 以下（上限含む） */
export function isWithinMaterialLaborScope(code) {
  const n = parsePriceCodeNumber(code)
  return n != null && n <= MATERIAL_LABOR_CODE_CEILING
}

/** 90000000 未満（90000000 以上を除く） */
export function isBelowMaterialLaborCeiling(code) {
  const n = parsePriceCodeNumber(code)
  return n != null && n < MATERIAL_LABOR_CODE_CEILING
}

export function getLastDigit(code) {
  const s = normalizePriceCode(code)
  return s.length ? s.slice(-1) : null
}

export function swapLastDigit(code, digit) {
  const s = normalizePriceCode(code)
  if (!s) return null
  return s.slice(0, -1) + String(digit)
}

export function isMeterLikeUnit(unit) {
  const u = String(unit ?? '')
    .trim()
    .toLowerCase()
    .replace(/²/g, '2')
    .replace(/㎡/g, 'm2')
  return u === 'm' || u === 'm2'
}

function scopedItems(items) {
  return (items || []).filter((it) => isWithinMaterialLaborScope(it?.external_code))
}

/** 保存前確認: 下1桁2が複数、または下1桁2と1が両方ある */
export function shouldConfirmSaveForMaterialLabor(items) {
  const scoped = scopedItems(items)
  const ending2BelowCeiling = scoped.filter(
    (it) => getLastDigit(it.external_code) === '2' && isBelowMaterialLaborCeiling(it.external_code)
  )
  const ending1 = scoped.filter((it) => getLastDigit(it.external_code) === '1')
  return ending2BelowCeiling.length >= 2 || (ending2BelowCeiling.length >= 1 && ending1.length >= 1)
}

/** A単価判定ボタン押下時の事前確認 */
export function shouldConfirmBeforeMaterialLaborJudge(items) {
  const scoped = scopedItems(items)
  const hasEnding2 = scoped.some(
    (it) => getLastDigit(it.external_code) === '2' && isBelowMaterialLaborCeiling(it.external_code)
  )
  const hasEnding1 = scoped.some((it) => getLastDigit(it.external_code) === '1')
  return hasEnding2 || hasEnding1
}

/**
 * A単価算出の候補を決定
 * @param {Array} items 登録済みアイテム
 * @param {Record<string, object>} priceMap external_code → プライス行
 */
export function computeMaterialLaborAJudge(items, priceMap) {
  const ending3Items = (items || []).filter(
    (it) => getLastDigit(it.external_code) === '3' && isBelowMaterialLaborCeiling(it.external_code)
  )

  if (ending3Items.length === 0) {
    return { ok: false, reason: 'no_ending3' }
  }

  const candidates = []
  for (const sourceItem of ending3Items) {
    const code3 = normalizePriceCode(sourceItem.external_code)
    const code2 = swapLastDigit(code3, '2')
    if (!code2) continue

    const row2 = priceMap[code2]
    if (!row2) continue

    const price2 = Number(row2.unit_price)
    if (!Number.isFinite(price2)) continue

    const row3 = priceMap[code3]
    const price3 = row3 != null ? Number(row3.unit_price) : null

    candidates.push({
      sourceItem,
      code3,
      code2,
      priceRow2: row2,
      priceRow3: row3,
      unitPrice2: price2,
      unitPrice3: Number.isFinite(price3) ? price3 : null
    })
  }

  if (candidates.length === 0) {
    return { ok: false, reason: 'no_valid_candidate' }
  }

  candidates.sort((a, b) => {
    if (b.unitPrice2 !== a.unitPrice2) return b.unitPrice2 - a.unitPrice2
    const bPrice3 = b.unitPrice3 ?? -Infinity
    const aPrice3 = a.unitPrice3 ?? -Infinity
    return bPrice3 - aPrice3
  })

  const best = candidates[0]
  if (isMaterialLaborCandidateNoPriceChange(best)) {
    return { ok: false, reason: 'no_price_change', best, ending3Items }
  }

  return {
    ok: true,
    best,
    ending3Items
  }
}

/** A単価とB単価が同額で変換しても金額が変わらない */
export function isMaterialLaborCandidateNoPriceChange(best) {
  if (!best) return false
  const a = best.unitPrice2
  const b = best.unitPrice3
  return Number.isFinite(a) && Number.isFinite(b) && a === b
}

/**
 * 算出結果に基づく数量・追加・削除方針
 * @param {object} best computeMaterialLaborAJudge の best
 * @param {(n: number) => number|null} roundQty
 */
export function planMaterialLaborApply(best, roundQty) {
  const source = best.sourceItem
  const srcQtyRaw = Number(source.quantity)
  const srcQty = Number.isFinite(srcQtyRaw) ? srcQtyRaw : 0
  const unit = best.priceRow2?.unit
  const transferAll = isMeterLikeUnit(unit) || srcQty <= 1

  if (transferAll) {
    return {
      code2: best.code2,
      newQuantity: srcQty,
      removeSource: true,
      sourceQuantityAfter: null
    }
  }

  const reduced = roundQty(srcQty - 1)
  return {
    code2: best.code2,
    newQuantity: 1,
    removeSource: reduced == null || reduced <= 0,
    sourceQuantityAfter: reduced == null || reduced <= 0 ? null : reduced
  }
}

/**
 * A単価判定の確認モーダル用プレビュー行
 * @param {object} best
 * @param {ReturnType<typeof planMaterialLaborApply>} plan
 * @param {Record<string, object>} priceMap
 */
export function buildMaterialLaborPreviewLines(best, plan, priceMap) {
  const source = best.sourceItem
  const row3 = priceMap[best.code3] || {}
  const row2 = best.priceRow2 || priceMap[best.code2] || {}
  const srcQtyRaw = Number(source.quantity)
  const srcQty = Number.isFinite(srcQtyRaw) ? srcQtyRaw : 0

  const lineFrom = (code, row, quantity) => ({
    code,
    priceType: row?.price_type || '-',
    description: row?.description || '-',
    quantity
  })

  const before = [lineFrom(best.code3, row3, srcQty)]
  const after = [lineFrom(plan.code2, row2, plan.newQuantity)]

  if (!plan.removeSource && plan.sourceQuantityAfter != null) {
    after.push(lineFrom(best.code3, row3, plan.sourceQuantityAfter))
  }

  return { before, after }
}

/** プライスリストから材工Aを除外するフィルタ */
export function isMaterialLaborAPriceType(priceType) {
  return String(priceType ?? '').trim() === '材工A'
}

export function isLaborPriceType(priceType) {
  return String(priceType ?? '').trim() === '労務'
}

export function isMaterialLaborBPriceType(priceType) {
  return String(priceType ?? '').trim() === '材工B'
}

/**
 * 詳細編集の price_type ラベル色（A単価判定ロジックとは独立）
 * @returns {string|null} CSS クラス名（未該当はデフォルト紫）
 */
export function getPriceTypeDisplayClass(priceType) {
  const pt = String(priceType ?? '').trim()
  if (pt === '労務') return 'price-type--labor'
  if (pt === '材工A') return 'price-type--material-labor-a'
  if (pt === '材工B') return 'price-type--material-labor-b'
  if (pt === '材料') return 'price-type--material'
  if (pt === '総合') return 'price-type--general'
  if (pt === '時間外') return 'price-type--overtime'
  return null
}

/** @deprecated 表示色は getPriceTypeDisplayClass を使用 */
export function isMaterialOrLaborHighlightPriceType(priceType) {
  return isMaterialLaborAPriceType(priceType) || isLaborPriceType(priceType)
}
