<template>
  <div class="excel-template-editor">
    <div class="editor-header">
      <div class="editor-header-left">
        <h3>Excelテンプレート（指示書）</h3>
        <div class="fixed-badges">
          <span class="badge">template_name: 指示書（固定）</span>
          <span class="badge">is_estimate: true（固定）</span>
          <span class="badge">is_active: true（固定）</span>
        </div>
      </div>
      <div class="editor-header-right">
        <button class="refresh-btn" @click="loadTemplate" :disabled="loading">
          {{ loading ? '読込中' : '再読込' }}
        </button>
      </div>
    </div>

    <div v-if="error" class="error-state">
      {{ error }}
    </div>

    <div class="form">
      <div class="row">
        <label class="label">アップロード（.xlsx）</label>
        <input class="file-input" type="file" accept=".xlsx" @change="handleFileChange" :disabled="saving" />
        <div class="hint">
          アップロード時は <code>estimate_(user_profile_id).xlsx</code> にリネームし、既存ファイルは削除します。
        </div>
      </div>

      <div class="row">
        <label class="label">説明</label>
        <input class="text-input" type="text" v-model="description" :disabled="saving" />
      </div>

      <div class="row">
        <label class="label">word_count</label>
        <input class="num-input" type="number" step="1" v-model="wordCount" :disabled="saving" />
      </div>

      <div class="row">
        <label class="label">highlighted_word_count</label>
        <input class="num-input" type="number" step="1" v-model="highlightedWordCount" :disabled="saving" />
      </div>

      <div class="row">
        <label class="label">highlighted_font_size</label>
        <input class="num-input" type="number" step="1" v-model="highlightedFontSize" :disabled="saving" />
      </div>

      <div class="row meta">
        <div class="meta-item"><span class="meta-k">storage_path</span> <code>{{ template?.storage_path || '-' }}</code></div>
        <div class="meta-item"><span class="meta-k">updated_at</span> <code>{{ template?.updated_at || '-' }}</code></div>
      </div>

      <div class="actions">
        <button class="save-btn" @click="save" :disabled="saving">
          {{ saving ? '保存中' : '保存 / アップロード' }}
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { supabaseService } from '../services/supabase'
import { indexedDBService } from '../utils/indexedDB'

const loading = ref(false)
const saving = ref(false)
const error = ref('')

const template = ref(null)

const description = ref('')
const wordCount = ref('')
const highlightedWordCount = ref('')
const highlightedFontSize = ref('')

const fileBase64 = ref(null)
const fileContentType = ref('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')

onMounted(() => {
  loadTemplate()
})

async function loadTemplate() {
  loading.value = true
  error.value = ''
  try {
    // まずIndexedDBから
    const cached = await indexedDBService.getTemplates('excel_templates')
    const estimateTemplate = (cached || []).find(t => t.is_estimate === true) || null
    if (estimateTemplate) {
      applyToForm(estimateTemplate)
      template.value = estimateTemplate
    }

    // その後サーバーから最新を取得
    const fresh = await supabaseService.getExcelTemplate()
    if (fresh) {
      template.value = fresh
      applyToForm(fresh)
      await indexedDBService.saveTemplate('excel_templates', [fresh])
    }
  } catch (e) {
    error.value = e?.message || '取得に失敗しました'
  } finally {
    loading.value = false
  }
}

function applyToForm(t) {
  description.value = t.description ?? ''
  wordCount.value = t.word_count ?? ''
  highlightedWordCount.value = t.highlighted_word_count ?? ''
  highlightedFontSize.value = t.highlighted_font_size ?? ''
}

async function handleFileChange(ev) {
  const file = ev.target.files?.[0]
  if (!file) return

  // xlsxのみ
  if (!file.name.toLowerCase().endsWith('.xlsx')) {
    error.value = 'xlsxファイルを選択してください'
    ev.target.value = ''
    return
  }

  fileContentType.value = file.type || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'

  const b64 = await readFileAsDataURL(file)
  fileBase64.value = b64
}

function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = reject
    reader.readAsDataURL(file)
  })
}

async function save() {
  saving.value = true
  error.value = ''
  try {
    const saved = await supabaseService.saveExcelTemplate({
      description: description.value || null,
      word_count: wordCount.value === '' ? null : Number(wordCount.value),
      highlighted_word_count: highlightedWordCount.value === '' ? null : Number(highlightedWordCount.value),
      highlighted_font_size: highlightedFontSize.value === '' ? null : Number(highlightedFontSize.value),
      file_base64: fileBase64.value,
      content_type: fileContentType.value
    })

    template.value = saved
    fileBase64.value = null
  } catch (e) {
    error.value = e?.message || '保存に失敗しました'
  } finally {
    saving.value = false
  }
}
</script>

<style scoped>
.excel-template-editor {
  padding: 1rem;
}

.editor-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.fixed-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.25rem;
}

.badge {
  background: #f3f4f6;
  border: 1px solid #e5e7eb;
  color: #374151;
  font-size: 0.75rem;
  padding: 0.15rem 0.4rem;
  border-radius: 999px;
}

.refresh-btn, .save-btn {
  border: 1px solid #d1d5db;
  background: white;
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  cursor: pointer;
}

.save-btn {
  border-color: #3b82f6;
  background: #3b82f6;
  color: white;
}

.save-btn:disabled, .refresh-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error-state {
  background: #fee2e2;
  border: 1px solid #fecaca;
  color: #991b1b;
  padding: 0.75rem;
  border-radius: 8px;
  margin-bottom: 1rem;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-width: 680px;
}

.row {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 0.75rem;
  align-items: center;
}

.row.meta {
  grid-template-columns: 1fr;
}

.label {
  color: #374151;
  font-weight: 600;
  font-size: 0.875rem;
}

.text-input, .num-input, .file-input {
  width: 100%;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  padding: 0.5rem;
  font-size: 0.875rem;
}

.hint {
  grid-column: 2 / 3;
  color: #6b7280;
  font-size: 0.75rem;
}

.meta-item {
  color: #374151;
  font-size: 0.875rem;
}

.meta-k {
  display: inline-block;
  min-width: 120px;
  color: #6b7280;
}

.actions {
  margin-top: 0.5rem;
  display: flex;
  justify-content: flex-end;
}
</style>




